schemas.schema-01-systematic.prisma:
/// Discussion board categories - Implements categorization as specified in the requirements analysis section regarding navigability, content organization, and moderation targeting. This model supports organized user experience and functional requirements for thread placement, filtering, and role-based content management. Maintains 3NF by keeping category metadata atomic, without duplicating section or configuration data. For example, a member starts a thread under the 'Economics' category, which is mapped here for retrieval. Key relationships: references to discussionboard_sections (for section grouping) and possible linkage to threads (managed in another component). Special behaviors: categories can be disabled or reordered without affecting thread data.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_categories {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each category, supporting distributed system architecture and audit trailing.
  id String @id @db.Uuid

  /// Parent section's {@link discussionboard_sections.id} - Implements hierarchical grouping as per business requirements, enabling categories to be nested within sections for enhanced organization.
  discussionboard_section_id String @db.Uuid

  /// Category name - Implements the display and search requirement for category labeling. Ensures normalization by isolating the label as atomic data. For example, 'Politics', 'Economics', 'International' etc.
  name String

  /// Category description - Provides contextual information to users and moderators. Maintains normalization by keeping explanations independent of other data. For instance, 'High-level discussions of macroeconomic issues.'
  description String?

  /// Category display order - Controls sequence in UI navigation and listings. Maintains 3NF as it's not derived or duplicated from any other data. For example, '1' = top position on board.
  order Int @db.Integer

  /// Is category enabled - Implements business rule for soft-hiding or disabling a category without deleting its record. Used in admin flows to turn categories on/off. For example, admins can disable a category temporarily during moderation.
  enabled Boolean

  //----
  // RELATIONS
  //----
  fk_discussionboard_categories_sections discussionboard_sections @relation(fields: [discussionboard_section_id], references: [id], onDelete: Cascade)

  discussionboard_threads discussionboard_threads[]

  @@unique([discussionboard_section_id, name])
  @@index([enabled])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Discussion board sections - Implements section-level grouping as per requirements covering board segmentation, navigation, and high-level access control. This entity solves the business need for upper-level organization beneath which categories (and subsequently threads) are grouped, supporting both frontend navigation and backend moderation targeting. Fully 3NF: atomic section label, description, and configuration linkage. For example, a section named 'Global Politics' groups multiple categories. Key relationships: can be referenced by categories and linked to board-wide configuration. Special behaviors: sections can be archived, reordered, or locked for content submission by toggling their enabled state.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_sections {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each section, supporting scalable, distributed storage and system traceability.
  id String @id @db.Uuid

  /// Configuration link {@link discussionboard_configurations.id} - Associates the section with platform configuration for access control or behavior settings as per business policy.
  discussionboard_configuration_id String @db.Uuid

  /// Section name - Implements navigation and search requirements for board-level organization. Normalized as atomic data. For example, 'Domestic Affairs', 'International Relations'.
  name String

  /// Section description - Context for users about the topical intent or rules. Fully normalized; avoids data redundancy. For instance, 'Contains threads related to domestic economic policy.'
  description String?

  /// Section display order - Determines appearance in navigation and configuration panels. For example, order '0' = top section. 3NF: not dependent on non-key fields.
  order Int @db.Integer

  /// Is section enabled - Controls visibility and posting capability for the section. Provides admin tools for platform segmentation as required by business rules.
  enabled Boolean

  //----
  // RELATIONS
  //----
  fk_discussionboard_sections_configurations discussionboard_configurations @relation(fields: [discussionboard_configuration_id], references: [id], onDelete: Cascade)

  discussionboard_categories discussionboard_categories[]

  @@index([discussionboard_configuration_id])

  @@unique([name])
  @@index([enabled])
}

/// Discussion board configurations - Implements board-wide or section-specific settings, as required by platform policy and business rules for extensibility, permissions, and behavior customization. This model addresses operational flexibility: toggling feature flags, adjusting settings without schema changes, and supporting future platform growth. Maintains strict normalization: each configuration record atomic. For example, holding JSON settings for poll behaviors, default moderation options, or feature enablement. Key relationships: referenced by discussionboard_sections and possibly others in the future. Special behaviors: changes are audit-logged elsewhere; configurations are never deleted outright—only updated or replaced.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_configurations {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each configuration, supporting distributed storage and reliable referencing by other entities.
  id String @id @db.Uuid

  /// Configuration name/key - Used for identification in admin tools and code. Normalized primary config label. Example: 'default_section_policy', 'poll_settings'.
  name String

  /// Serialized configuration JSON - Stores all behavioral settings as a JSON string. Normalized: each config in its own row. For example, '{"allow_polls": true, "max_poll_options": 10}'
  settings_json String

  /// Human-readable descriptive text about the configuration's purpose. Maintains normalization. For instance, 'Settings controlling default behaviors for domestic threads.'
  description String?

  //----
  // RELATIONS
  //----
  discussionboard_sections discussionboard_sections[]

  @@unique([name])
}

schemas.schema-02-actors.prisma:
/// Admin Role Model - This implements the administrative user role specification from '02_discussionboard_user_roles_and_authentication.md'. 
///
/// Represents site administrators who have full access for platform management, policy enforcement, user control, and official dispute handling. Maintains 3NF normalization by only holding role-specific identity, inheriting account details via shared foreign key references in actual system (e.g., via member or user account tables in other domains). For example, admins may be mapped to existing accounts for login. 
///
/// Key relationships: Not directly referencing other components to avoid duplication, but will use external user/member tables for ID in full implementation. 
/// Special behaviors: Only users elevated to this table have admin permissions; removal here revokes all admin rights.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_admins {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique admin role identifier.
  id String @id @db.Uuid

  /// Role assignment timestamp - Implements the auditability requirement. Records when the admin privilege was granted. Ensures temporal traceability for permission changes, supporting snapshot patterns by explicitly separating the assignment history. For example, when new admins are added, this field logs the event.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  discussionboard_bans discussionboard_bans[]
}

/// Moderator Role Model - This implements the moderator role specification from '02_discussionboard_user_roles_and_authentication.md'. 
///
/// Represents users with moderation powers: content review, temporary suspensions, and community management, without full admin rights. 3NF compliance is achieved by separating moderator role assignments from general user/member identity, with actual references made to external user/member accounts for linkage. 
///
/// Key relationships: In a full system, would reference members/users for role mapping. 
/// Special behaviors: Inclusion grants moderation rights; records are auditable for community trust and escalation protocols.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_moderators {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique moderator role identifier.
  id String @id @db.Uuid

  /// Role assignment timestamp - Tracks when the moderator privilege was activated. Supports audit trails and historical analysis of role distribution and trust elevation. For example, elevated by senior admins or via governance process.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  discussionboard_moderation_actions discussionboard_moderation_actions[]
  discussionboard_warning_logs discussionboard_warning_logs[]
  discussionboard_suspensions discussionboard_suspensions[]
}

/// Member Role Model - Implements core registered user account role as specified in '02_discussionboard_user_roles_and_authentication.md'. 
///
/// Represents all authenticated users authorized to create content, interact, and participate in member-only features. Complies with 3NF by storing only role/enrollment information; user profile, security, and credentials exist in separate tables/domains. For example, email/username/password managed elsewhere but ID assigned here upon registration completion.
///
/// Key relationships: Mapped to outer user or authentication entity in wider system. 
/// Special behaviors: Granting/removing a row in this table assigns permission to create threads, participate in polls, etc.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_members {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique member role identifier.
  id String @id @db.Uuid

  /// Role assignment timestamp - Logged at registration or membership upgrade. Used for eligibility/rule tracking and supports audit trails. For example, new signups receive this timestamp.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  discussionboard_threads discussionboard_threads[]
  discussionboard_posts discussionboard_posts[]
  discussionboard_post_histories discussionboard_post_histories[]
  discussionboard_post_edit_logs discussionboard_post_edit_logs[]
  discussionboard_thread_archives discussionboard_thread_archives[]
  discussionboard_content_reports discussionboard_content_reports[]
  discussionboard_moderation_actions discussionboard_moderation_actions[]
  discussionboard_warning_logs discussionboard_warning_logs[]
  discussionboard_suspensions discussionboard_suspensions[]
  discussionboard_bans discussionboard_bans[]
  discussionboard_post_reactions discussionboard_post_reactions[]
  discussionboard_post_likes discussionboard_post_likes[]
  discussionboard_polls discussionboard_polls[]
  discussionboard_poll_votes discussionboard_poll_votes[]
  discussionboard_mentions discussionboard_mentions[]
  discussionboard_notifications discussionboard_notifications[]
  discussionboard_alerts discussionboard_alerts[]
  discussionboard_search_histories discussionboard_search_histories[]
  discussionboard_filters discussionboard_filters[]
}

/// Guest Role Model - Implements the guest browsing entity from '02_discussionboard_user_roles_and_authentication.md'. 
///
/// Represents unauthenticated and optionally semi-tracked users who may browse public content but not post/interact. Maintains 3NF as a distinct normalized table to assign and trace guest viewing sessions, apply access controls, and support future conversion (upgrade to member). For example, may store guest session or visitor tokens mapped to analytics.
///
/// Key relationships: May relate to external analytics/logs for guest tracking in broader system. 
/// Special behaviors: Deleting a guest here does not affect any member/admin records, ensuring normalization between roles.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_guests {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique guest identifier, e.g., guest session or pseudonymous token.
  id String @id @db.Uuid

  /// Guest session/browsing assignment timestamp - Set when a guest session is first tracked or created. Used for analysis, conversion tracking to members, and policy enforcement (e.g., access window).
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  discussionboard_content_reports discussionboard_content_reports[]
  discussionboard_bans discussionboard_bans[]
}

/// Authentication Session Model - Implements the authentication and session tracking requirement from '02_discussionboard_user_roles_and_authentication.md' and ties policies in '05_discussionboard_business_rules_and_policies.md' (account locking, session expiry, etc.). 
///
/// Tracks active user/member sessions for login management, enforcing security policies, session timeouts, and role mapping. Complies with 3NF by separating session management from user identity, allowing independent lifecycle. For example, on login, a new row is created; on logout or expiry, row is ended.
///
/// Key relationships: Would reference user/member/role tables for session ownership in a full system.
/// Special behaviors: Supports device/session concurrency policies, auditing of all critical actions (policy: audit trail for edits, deletions, moderation decisions).
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_auth_sessions {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique session identifier.
  id String @id @db.Uuid

  /// Role type associated with the session. Implements session role typing for permission checks (e.g., 'admin', 'moderator', 'member', 'guest'). Ensures normalization by separating session against role tables. For example: 'member' session tracks a logged in member, 'guest' for unauthenticated visitor.
  actor_type String

  /// Associated actor id (admin/member/moderator/guest). Implements role linking for session ownership. Ensures normalization so that user/role are tracked externally, this is a foreign key reference in broader system. For example, points to the 'id' of the corresponding role table depending on actor_type.
  actor_id String @db.Uuid

  /// Session start timestamp. Implements session record creation for login audit trails. For example, set when user completes login.
  issued_at DateTime @db.Timestamptz

  /// Session expiration timestamp - Used to implement session expiry, security policy on inactivity, or explicit logout. For example, calculated by security policy or upon logout event.
  expires_at DateTime @db.Timestamptz

  /// Timestamp of the last activity on this session. Implements last-used tracking for security checks (token expiration, forced logout). For example, updated on each page load or action.
  last_activity_at DateTime? @db.Timestamptz

  /// Time at which session was revoked, if applicable. Implements security and forced logout. For example, set if session is invalidated by admin or system.
  revoked_at DateTime? @db.Timestamptz

  /// IP address recorded when session was initiated. Provides security auditing for login source and supports fraud monitoring. For example, '192.168.1.1'.
  ip_address String?

  /// User agent string recorded on session establishment. Implements browser/device tracking policy for audit and security. For example, 'Mozilla/5.0 (Windows NT 10...)'.
  user_agent String?

  //----
  // RELATIONS
  //----
  @@index([actor_type, actor_id])
  @@index([issued_at])
}

schemas.schema-03-threads_posts.prisma:
/// Thread Root Entity - This implements the 'thread management and creation' requirement from the features and user journeys documentation. Each instance represents an individual discussion thread (topic) started by a member, with links to category/section and root post. Maintains 3NF compliance by separating main thread data (title, status, author/member, section/category) from posts, histories, and related engagement. For example, a new thread '2025 Elections Discussion' would have one record here and many related post/comment records elsewhere. 
/// Key relationships: Links to author member, category, and root post via foreign keys. Special behaviors: Soft-deletion (archived flag), per-thread lock/pin status for moderation/admins.
///
/// @namespace ThreadsPosts
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_threads {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique thread identifier.
  id String @id @db.Uuid

  /// Thread author's {@link discussionboard_members.id}. Refers to the member who created the thread.
  discussionboard_member_id String @db.Uuid

  /// Thread's assigned {@link discussionboard_categories.id}. Refers to the topic/category under which this thread is created.
  discussionboard_category_id String @db.Uuid

  /// Thread title - Implements the required summary/title as per requirements document. Atomic, and always present. For example: '2025 Economic Outlook'.
  title String

  /// Thread status - Active, archived, locked. Implements moderation control requirement. For example: 'active', 'locked', 'archived'.
  status String

  /// Pinned flag - Whether this thread is pinned at the top. Implements thread management feature for moderators/admins. true if pinned by moderation.
  is_pinned Boolean

  /// Locked flag - Whether this thread is locked. Implements moderation tool for controlling participation. true if thread no longer accepts replies.
  is_locked Boolean

  /// Soft delete/archive flag. If true, thread is hidden from public but data is retained for admins/audit. Implements audit/compliance rules.
  archived Boolean

  /// Thread creation timestamp. For audit/logging as per business rules.
  created_at DateTime @db.Timestamptz

  /// Thread last updated timestamp. Updated on edits or moderation events. Required for audit trail and UX.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  member discussionboard_members @relation(fields: [discussionboard_member_id], references: [id], onDelete: Cascade)
  category discussionboard_categories @relation(fields: [discussionboard_category_id], references: [id], onDelete: Cascade)

  discussionboard_posts discussionboard_posts[]
  discussionboard_thread_archives discussionboard_thread_archives[]
  discussionboard_polls discussionboard_polls[]
  discussionboard_tagged_threads discussionboard_tagged_threads[]

  @@index([discussionboard_category_id])

  @@unique([title, discussionboard_category_id])
  @@index([discussionboard_member_id, created_at], map: "discussionboard_threads_discussionboard_member_id_crea_978c1236")
  @@index([status])
  @@index([is_pinned, is_locked])
  @@index([title(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Thread Post Entity - Implements the 'thread and comment posting', 'reply', and 'content moderation/reporting' features. Each represents an individual post or comment in a thread, with parent-child relation for comments (nested structure). Maintains 3NF compliance by keeping each post atomic and referring to its thread, author, and parent. For example, a threaded reply is a record here with a parent post. Key relationships: thread linkage, post author (member), optional parent for comments. Special behaviors: supports nested replies, soft deletion.
///
/// @namespace ThreadsPosts
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_posts {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique post identifier.
  id String @id @db.Uuid

  /// Referenced thread's {@link discussionboard_threads.id}. Indicates which thread this post belongs to.
  discussionboard_thread_id String @db.Uuid

  /// Author member's {@link discussionboard_members.id}. Refers to the member who wrote this post or comment.
  discussionboard_member_id String @db.Uuid

  /// Optional parent {@link discussionboard_posts.id} (for replies/comments). Null for root posts; non-null for comments/replies to other posts.
  parent_post_id String? @db.Uuid

  /// Post content body. Implements textual content storage. Fully normalized. For example: 'I think the economic forecast is optimistic.'
  body String

  /// Edit flag. True if post has been edited after initial creation. Implements edit tracking policy.
  is_edited Boolean

  /// Soft delete flag. True if post is hidden from general users, retained for moderation/audit. Implements compliance and moderation rules.
  is_deleted Boolean

  /// Timestamp of post creation. For chronology, moderation review, and user display.
  created_at DateTime @db.Timestamptz

  /// Timestamp of last update. Reflects edit or moderation action.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  thread discussionboard_threads @relation(fields: [discussionboard_thread_id], references: [id], onDelete: Cascade)
  member discussionboard_members @relation(fields: [discussionboard_member_id], references: [id], onDelete: Cascade)
  parent_post discussionboard_posts? @relation("recursive", fields: [parent_post_id], references: [id], onDelete: Cascade)

  recursive discussionboard_posts[] @relation("recursive")
  discussionboard_post_histories discussionboard_post_histories[]
  discussionboard_post_edit_logs discussionboard_post_edit_logs[]
  discussionboard_content_reports discussionboard_content_reports[]
  discussionboard_moderation_actions discussionboard_moderation_actions[]
  discussionboard_post_reactions discussionboard_post_reactions[]
  discussionboard_post_likes discussionboard_post_likes[]
  discussionboard_mentions discussionboard_mentions[]

  @@index([discussionboard_thread_id, created_at])
  @@index([discussionboard_member_id, created_at])
  @@index([parent_post_id])
  @@index([body(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Post History Snapshot Entity - Implements post edit/version control requirement. Each record is a snapshot of a post's content and metadata before or after an edit/action, maintaining a complete audit trail. Ensures 3NF by storing versions separately. For example, if a post is edited three times, there are three snapshot entries linked to the post. Key relationships: belongs to post, links to member who performed the edit/action. Special rules: records must not be deletable by regular users, only by admin/audit purge.
///
/// @namespace ThreadsPosts
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_post_histories {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique snapshot record identifier.
  id String @id @db.Uuid

  /// Target post's {@link discussionboard_posts.id}. Indicates which post this snapshot is for.
  discussionboard_post_id String @db.Uuid

  /// Member's {@link discussionboard_members.id} who performed the edit/action. For tracking responsible user.
  edit_member_id String @db.Uuid

  /// Prior post body (before edit/action). Implements versioned content requirement. Null if post was created (not edited yet).
  old_body String?

  /// Edited (new) post body. Required for post change logs. Null if snapshot is for deletion (not rewording).
  new_body String?

  /// Type of edit/action (e.g., 'edit', 'delete', 'restore'). For audit and moderation policy linkage. For example: 'edit', 'delete'.
  edit_type String

  /// Reason/comment for the edit, as recorded by the member or moderator. For moderation transparency, compliance.
  edit_reason String?

  /// Timestamp when this history/snapshot record was created. Fully normalized.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  post discussionboard_posts @relation(fields: [discussionboard_post_id], references: [id], onDelete: Cascade)
  edit_member discussionboard_members @relation(fields: [edit_member_id], references: [id], onDelete: Cascade)

  @@index([discussionboard_post_id, created_at], map: "discussionboard_post_histories_discussionboard_post_id_882b9fd8")
  @@index([edit_member_id, created_at])
}

/// Post Edit Log Entity - Implements granular audit-purposed logging for all post edits, satisfying compliance and traceability requirements beyond typical edit history. Each entry records who, when, and what change occurred, for every modification to any post. Maintains 3NF as every field relates directly to the primary key. For example, if a user performs three edits, all are logged here for admins/audits. Key relationships: links to post, edit-performing member.
///
/// @namespace ThreadsPosts
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_post_edit_logs {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique edit log record identifier.
  id String @id @db.Uuid

  /// Edited post's {@link discussionboard_posts.id}.
  discussionboard_post_id String @db.Uuid

  /// Editing member's {@link discussionboard_members.id}.
  edit_member_id String @db.Uuid

  /// Brief summary of the edit. For quick audit purposes. Example: 'Fixed typo', 'Added reference'.
  change_summary String

  /// Detailed information about the change (could be JSON or text). For investigation and compliance. Example: '{"from":"draft version","to":"final version"}'.
  change_details String

  /// Edit timestamp. For chronology.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  post discussionboard_posts @relation(fields: [discussionboard_post_id], references: [id], onDelete: Cascade)
  edit_member discussionboard_members @relation(fields: [edit_member_id], references: [id], onDelete: Cascade)

  @@index([discussionboard_post_id, created_at], map: "discussionboard_post_edit_logs_discussionboard_post_id_ad1737a7")
  @@index([edit_member_id, created_at])
  @@index([change_summary(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Thread Archive Entity - Implements thread archival/inactivation feature (from user cases/policies) whereby entire threads are hidden from public view on closure or due to compliance policy. This normalized entity stores archive records with references to thread, member (initiator), and reason. Example: a thread archived due to policy contains record here. Key relationships: links to thread, admin/mod who performed archival. Special behavior: archival should not delete thread/posts. Maintains 3NF.
///
/// @namespace ThreadsPosts
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_thread_archives {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique archive record identifier.
  id String @id @db.Uuid

  /// Thread's {@link discussionboard_threads.id} being archived.
  discussionboard_thread_id String @db.Uuid

  /// Member (admin/moderator) {@link discussionboard_members.id} who performed the archival.
  archived_by_member_id String @db.Uuid

  /// Reason/archive comment per moderation/audit policy implementation. Example: 'Thread closed for being off-topic.'
  archive_reason String

  /// Archival timestamp.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  thread discussionboard_threads @relation(fields: [discussionboard_thread_id], references: [id], onDelete: Cascade)
  archived_by_member discussionboard_members @relation(fields: [archived_by_member_id], references: [id], onDelete: Cascade)

  @@unique([discussionboard_thread_id])
  @@index([archived_by_member_id])
}

schemas.schema-04-moderation.prisma:
/// Content Report Entity - This implements the requirement for capturing and tracking user-reported content as defined in 'Business Rules and Policies' and across 'Features and Functional Specifications'.
///
/// This model records when a member or guest files a report on a post, comment, or thread for policy violations, harassment, or inappropriate content. It maintains normalized structure (3NF) by capturing report details and referencing the post/content in violation, along with the reporting user and reason. For example, when a member reports a post they believe is a violation, a new row is created here and linked to the moderation review process.
///
/// Key relationships: References reporter (member or guest by user_id/actor_id) and the offending content (from the threads/posts tables in the ThreadsPosts component).
/// Special behaviors: Maintains audit trail; supports escalation workflow and status updates.
///
/// @namespace Moderation
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_content_reports {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each content report entry.
  id String @id @db.Uuid

  /// Target post's {@link discussionboard_posts.id} reported for violation or moderation. May also be used to reference a comment if required.
  reported_post_id String @db.Uuid

  /// Reporting member's {@link discussionboard_members.id}, if the reporter is a registered member.
  reporter_member_id String? @db.Uuid

  /// Reporting guest's {@link discussionboard_guests.id}, if the report was filed by a guest user (optional).
  reporter_guest_id String? @db.Uuid

  /// Reason for content report - Implements requirement to capture user's motivation for reporting content. Ensures normalization by storing only reason text; examples include 'spam', 'abuse', 'off-topic', etc. Required for moderation triage and analytics.
  report_reason String

  /// Moderation status of the report - Implements status tracking for the moderation queue. Allowed values are 'pending', 'in_review', 'action_taken', 'dismissed', reflecting different workflow states. Ensures normalization by storing only the status token. For example, 'pending' is assigned on creation.
  status String

  /// Timestamp when the content was reported - Implements audit trail requirement and ensures detailed moderation history. Not nullable.
  reported_at DateTime @db.Timestamptz

  /// Moderator's note on review outcome - Allows documenting justification for resolution or further actions. Nullable; present after moderator review.
  moderator_note String?

  //----
  // RELATIONS
  //----
  fk_content_reports_post discussionboard_posts @relation(fields: [reported_post_id], references: [id], onDelete: Cascade)
  fk_content_reports_member discussionboard_members? @relation(fields: [reporter_member_id], references: [id], onDelete: Cascade)
  fk_content_reports_guest discussionboard_guests? @relation(fields: [reporter_guest_id], references: [id], onDelete: Cascade)

  discussionboard_moderation_actions discussionboard_moderation_actions[]

  @@index([reporter_guest_id])

  @@index([reported_post_id])
  @@index([reporter_member_id])
  @@index([report_reason, status])
  @@index([report_reason(ops: raw("gin_trgm_ops"))], type: Gin)
}

