  //----
  // RELATIONS
  //----
  fk_discussionboard_tagged_threads_thread discussionboard_threads @relation(fields: [discussionboard_thread_id], references: [id], onDelete: Cascade)
  fk_discussionboard_tagged_threads_tag discussionboard_thread_tags @relation(fields: [discussionboard_thread_tag_id], references: [id], onDelete: Cascade, map: "discussionboard_tagged_threads_discussionboard_thread__7255cea4")

  @@unique([discussionboard_thread_id, discussionboard_thread_tag_id], map: "discussionboard_tagged_threads_discussionboard_thread__1f84d336")
  @@index([discussionboard_thread_tag_id], map: "discussionboard_tagged_threads_discussionboard_thread__ac60e66e")
}

/// Discussion thread tag library - Implements tagging, search, and organization requirements, allowing tag-based topic discovery and moderation. This table stores a catalog of available tags that can be assigned to threads, such as 'economy', 'election', or 'policy'. Maintains 3NF by not including aggregate info, only atomic tag data. For example, site admin creates/tag 'fiscal_policy', which members can assign to threads. Key relationships: Referenced by tagged-thread junction table. Uniqueness by code. Special behaviors: Tag codes are unique, names are searchable, can be marked as moderated/restricted via flags.
///
/// @namespace Discovery
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_thread_tags {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique ID for each tag definition.
  id String @id @db.Uuid

  /// Canonical tag code. Implements uniqueness and fast search requirement. Lower-case alphanumeric/underscore.
  code String

  /// Tag display name, e.g. 'Fiscal Policy'. User-friendly labeling.
  display_name String

  /// Explanation or usage guideline for this tag. Fulfills moderation/discussion guideline mapping. Nullable if not present.
  description String?

  /// Tag moderation flag. If true, only moderators/admins can assign tag. Implements requirements for moderated tags.
  is_restricted Boolean

  /// Soft deprecation flag. If true, users should not see/assign this tag except admin.
  is_hidden Boolean

  /// Timestamp of tag creation. Implements audit trail.
  created_at DateTime @db.Timestamptz

  /// Last updated. Allows admin track of edits to tags.
  updated_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  discussionboard_tagged_threads discussionboard_tagged_threads[]

  @@unique([code])
  @@index([display_name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Saved search/filter configuration - Implements the 'filters' and 'recall/discovery tools', for example, members saving useful filter sets for fast access or sharing. Records configurations for reusable search or discovery filters, which can be user-specific (member) or system-wide. Strictly 3NF: only atomic filter info. For example, a member can save a filter called 'Recent Elections' for all threads with tag 'elections' in 'current events' section, stored as a JSON or string formula. Key relationships: References member for user-specific filters via foreign key. System-wide filters are marked by null member id. Special behaviors: Unique name per user, supports public/private visibility, allows deletion (soft).
///
/// @namespace Discovery
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_filters {
  //----
  // COLUMNS
  //----
  /// Primary Key. ID for each filter definition.
  id String @id @db.Uuid

  /// Filter owner's {@link discussionboard_members.id} if user-specific. Null if shared/system-wide.
  discussionboard_member_id String? @db.Uuid

  /// Name for this filter as seen by user. Unique per owner (enforced by index). Atomic string. For example: 'Recent Macroeconomics'.
  name String

  /// Serialized filter definition (could be a query language or JSON-based formula). For example: '{tags: ["elections"], section: "current_events"}'.
  definition String

  /// Visibility setting. True if filter is shared or system-wide, false if private to member.
  is_public Boolean

  /// Timestamp of filter creation. For filtering, order-by, and audit.
  created_at DateTime @db.Timestamptz

  /// Last updated. For management and recall tools.
  updated_at DateTime? @db.Timestamptz

  /// Soft deletion (null if active). For removal and right-to-be-forgotten policies.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_discussionboard_filters_member discussionboard_members? @relation(fields: [discussionboard_member_id], references: [id], onDelete: Cascade)

  @@unique([discussionboard_member_id, name])
  @@index([is_public])
}

schemas.schema-08-policy_audit.prisma:
/// Business Rule Definition - This implements the requirement for system-wide governance and operational rules, mapped from section 5.1 of the requirements analysis (Business Rules and Policies). 
///
/// Defines a single rule with versioning and enforcement notes, allowing traceability of policy enforcement. Maintains 3NF by storing only atomic rule data, with version history tracked elsewhere. For example, 'No hate speech' or 'Maximum post length'.
///
/// Key relationships: May be referenced by platform policy and audit log entities. 
/// Special behaviors: Immutable after approval except via re-versioning.
///
/// @namespace PolicyAudit
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_business_rules {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each business rule record.
  id String @id @db.Uuid

  /// Machine-friendly rule code - Implements unique policy identification as a short string (e.g., 'NO_HATE_SPEECH'). Facilitates referencing and linking, enforcing uniqueness per rule.
  rule_code String

  /// Rule short title - The human-readable name for the rule, for display and audit references. Ensures normalization by storing only the atomic rule label. Used in rule listings and selection forms.
  title String

  /// Rule full description - The verbose requirements, restrictions, and definitions for this rule. Maintains normalization by excluding enforcement history or modification logs; only static rule details. Used for admin summaries and user display.
  description String

  /// Rule activation flag - Determines if this business rule is currently in effect. Implements EARS specifications for system behavioral toggling; referenced when evaluating enforcement eligibility.
  is_active Boolean

  /// Timestamp of rule entry creation. Used for audit and historical reference; never updated.
  created_at DateTime @db.Timestamptz

  /// Timestamp of last rule information update (not enforcement event). Tracked only for rule text changes, not enforcement or violation logging.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  @@unique([rule_code])
  @@index([is_active])
  @@index([title(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([description(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Platform Policy Statement - Implements explicit documentation and versioning of the platform's rules and policies, based on requirements in the Business Rules and Policies document (section 1 and 3).
///
/// Captures high-level policy texts and their publication states, ensuring compliance with audit and transparency values. Maintains 3NF by not embedding related actions, incidents, or appeals.
///
/// Usage example: Published privacy policy, content moderation policy, or terms of service, referenced in user interfaces and admin dashboards.
///
/// Key relationships: May be linked in notifications or user onboarding flows.
/// Special behaviors: Replaces previous versions on update; policy text is immutable once published.
///
/// @namespace PolicyAudit
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_platform_policies {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each platform policy document.
  id String @id @db.Uuid

  /// Unique policy code - Implements compliance requirement for distinct identification (e.g., 'PRIVACY', 'MODERATION'). Used for referencing and policy change tracking. Enforces uniqueness per active policy.
  policy_code String

  /// Policy title - Human-readable title for display and search. Maintains normalization by excluding policy text or status.
  title String

  /// Policy content - The full published text of the policy, supporting platform communication transparency and legal reference. For user agreement and admin review screens.
  policy_text String

  /// Policy activation flag - Indicates if this version of the policy is currently in force. Supports rollback on major rule changes.
  is_active Boolean

  /// Publication timestamp - The datetime this policy was rendered active. Used in compliance audits; immutable after creation.
  published_at DateTime @db.Timestamptz

  /// Last update timestamp for this policy entry. Tracks administrative changes only, not user or enforcement logs. Required for policy update audit trails.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  @@unique([policy_code])
  @@index([is_active])
  @@index([title(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([policy_text(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// System Audit Log Entry - Implements the audit trail requirements for sensitive operations, as described in the Security Requirements and Data Retention sections.
///
/// Captures each critical action for traceability, legal compliance, and operational review. Maintains 3NF by linking only to atomic action data with foreign keys for originators if implemented in other schemas.
///
/// Usage: Whenever a mod/admin changes a rule, enforces a suspension, or alters system access. Allows search by actor, action type, or time window.
///
/// Key relationships: May point to actors by actor_id if available.
/// Special behaviors: Entries are strictly append-only; never updated or deleted except by court order.
///
/// @namespace PolicyAudit
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_audit_logs {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each audit log entry.
  id String @id @db.Uuid

  /// Action type code - Implements requirement for specific action tracking (e.g., 'RULE_EDIT', 'SUSPENSION_APPLY'). Supports compliance reporting without embedding further context.
  action_type String

  /// Detailed description of the action event taken, for compliance traceability. Maintains normalization by storing only the fact of the action, not duplicating target entity data.
  description String

  /// UUID of the actor (admin/moderator/member) who performed the action. May reference discussionboard_admins, discussionboard_moderators, or discussionboard_members in Actors schema for referential consistency. Nullable to allow system actions.
  actor_id String? @db.Uuid

  /// UUID of the primary entity affected (user, post, policy, etc.). Usage depends on action type. May reference models in other schemas or be null for system-wide actions.
  target_id String? @db.Uuid

  /// Timestamp of audit log creation. Recorded at the moment of action; immutable.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  @@index([action_type])
  @@index([actor_id])
  @@index([description(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Incident Report Entity - Implements the incident reporting and escalation workflows from Business Rules and Policies section 4.
///
/// Logs reports of rule/policy violations, capturing status, reporting party, action taken (if any), and timestamps. Maintains strict normalization by avoiding embedding of user or policy details; only links by code or ID where necessary. 
/// Usage example: A member or moderator submits a report of a suspected violation. Tracked through review, escalation, closure.
///
/// Key relationships: actor_id and possibly related audit_logs or policies.
/// Special behaviors: Once closed, cannot be edited; only reopened with admin approval for audits.
///
/// @namespace PolicyAudit
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_incident_reports {
  //----
  // COLUMNS
  //----
  /// Primary Key. Report Identifier.
  id String @id @db.Uuid

  /// Incident code - Unique identifier for each incident (e.g., 'INCIDENT-20240321-001'). Allows search, link to audit logs, and escalation procedures.
  incident_code String

  /// Incident status - Workflow indicator (e.g., 'OPEN', 'IN_REVIEW', 'CLOSED', 'ESCALATED'). Implements incident state requirement; supports escalation triggers and closure rules. (Enum recommended in app logic).
  status String

  /// Actor who submitted the report. UUID value; may reference admins, moderators, or members in Actors schema. Nullable if submitted anonymously.
  reporter_id String? @db.Uuid

  /// Incident details - Free text provided by the reporter explaining facts and relevant context. Maintains normalization by not including structured rule data; only the reported statement.
  description String

  /// Incident report creation timestamp - Used to measure response SLA and escalation timing.
  created_at DateTime @db.Timestamptz

  /// Last incident status update (e.g., progress, assignment, closure). Used for internal audit and dashboard tracking.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  @@unique([incident_code])
  @@index([status])
  @@index([description(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Appeal Record - Implements the appeals process for disciplinary or moderation outcomes, as required by the Business Rules and Policies (section 5), including role-based appeal rights and audit trails.
///
/// Captures every user-submitted appeal with status and outcome details. Maintains 3NF by recording only atomic data and referencing related incidents or users by ID or code, not duplicating content.
///
/// Usage: A sanctioned user (e.g., after a suspension or ban recorded elsewhere) appeals a decision; each appeal is logged with outcome and timestamps.
///
/// Key relationships: reporter_id, possibly related incident report or moderation action (cross-schema). 
/// Special behaviors: Once closed, appeals are immutable; status may affect complaint metrics.
///
/// @namespace PolicyAudit
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_appeals {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique appeal record identifier.
  id String @id @db.Uuid

  /// Unique appeal code (e.g., 'APPEAL-20240321-205'). Ensures tracking and cross-referencing with incidents and audit logs.
  appeal_code String

  /// Appeal status workflow value (e.g., 'PENDING', 'REVIEWING', 'UPHELD', 'REJECTED'). Enables SLA and dashboard reporting; suggested as an Enum in app logic. Maintains normalization by not storing duplicate status details.
  status String

  /// UUID of user who filed the appeal (may be admin, moderator, or member). Nullable for anonymous, though unusual. Cross-references the Actors models for full details.
  appellant_id String? @db.Uuid

  /// If linked to an incident report, holds the corresponding report's ID for audit and workflow consistency. Nullable for general appeals not tied to a specific incident.
  incident_id String? @db.Uuid

  /// Outcome memo - Short description of the appeal's result once closed (e.g., 'Ban upheld', 'Suspension reversed'). Maintains normalization by storing only atomic outcome description, not related evidence or reasoning.
  outcome String?

  /// Appeal submission timestamp.
  created_at DateTime @db.Timestamptz

  /// Last appeal update timestamp (e.g., outcome decided, status changed).
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  @@unique([appeal_code])
  @@index([status])
  @@index([incident_id])
  @@index([outcome(ops: raw("gin_trgm_ops"))], type: Gin)
}

