  /// Member's {@link discussionboard_members.id} who was suspended.
  suspended_member_id String @db.Uuid

  /// Reason suspension was issued - Implements requirement for tracking policy violations or abuse. Maintains 3NF (atomic value only). E.g., 'spamming', 'multiple policy violations'.
  suspension_reason String

  /// When suspension began - For audit trails and auto-expiry systems. Maintains precise timeline for enforcement.
  suspension_started_at DateTime @db.Timestamptz

