schemas.schema-06-notifications.prisma:
/// Discussion Board Notification - This implements the notification delivery and alerting requirement from the requirements documents (particularly 03_discussionboard_features_and_functional_specifications.md, section 7 Notifications and Alerts; see also user journeys and business rules). 
///
/// Business explanation: Stores detailed notifications generated by the system—such as mentions, replies, moderator actions, and administrative announcements—to be delivered to specific users. Ensures users are promptly informed of activity requiring their attention. Maintains full 3NF compliance: notification text, type, and linkage to recipient are atomic and non-redundant. For example, when a user is mentioned in a comment, a notification is created here detailing the context and recipient. 
///
/// Key relationships: References discussionboard_members as notification recipient; may also reference other entities (e.g., post/thread) as optional context if needed (not included here, but ID pattern allows for future extension). 
/// Special behaviors: Soft deletion via nullable deleted_at; status/opened flag; delivery details and related timestamps for auditability and analytics; all notifications are individualized and immutable after creation. Audit trails of delivery status handled within this model.
///
/// @namespace Notifications
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_notifications {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each notification record. Ensures entity uniqueness and supports distributed environments. Required for all entities for tracking and referencing.
  id String @id @db.Uuid

  /// Recipient's {@link discussionboard_members.id}. Indicates which member this notification is intended for. Enables delivery targeting and audit trail. Required for all notifications.
  discussionboard_member_id String @db.Uuid

  /// Notification type - Implements requirement for distinguishing system, user, moderation, and announcement notifications. Possible values: 'mention', 'reply', 'moderator_action', 'announcement', etc. Ensures clear categorization for UI badge and analytics. Example: When a thread is locked, moderators receive a 'moderator_action' type notification. Atomic and fully normalized.
  type String

  /// Notification title or brief summary - Implements clear communication of subject as required by UX guidelines. Summarizes notification content in a single line for user display. Example: 'You were mentioned in a post.' Fully normalized.
  title String

  /// Full textual content of the notification - Implements rich, readable notification context as required by the user journey and business rules. Contains detailed context such as source thread or action taken. Example: 'Your post in "2025 Elections Economy" was edited by a moderator.'
  body String?

  /// Optional URI to direct recipient to the notification context. Supports quick navigation to relevant thread, post, or profile. Implements UX quick-access requirement. Example: '/thread/abc123/post/xyz456'.
  url String? @db.VarChar(80000)

  /// Whether the notification has been opened/read by the recipient - Implements user status tracking for badge counts & UX feedback. Example: New notifications are false; becomes true when user visits notification center or clicks link. Fully normalized with no redundant status.
  opened Boolean

  /// Notification creation timestamp. Implements requirement to log when notifications are generated, for both UX ordering and audit trails. Non-nullable for history and analytics purposes.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the notification was opened/read. Enables precise auditing and user interaction analytics. Nullable for unopened notifications. Ensures atomic status-tracking in 3NF structure.
  opened_at DateTime? @db.Timestamptz

  /// Soft deletion timestamp. Implements compliance with audit and retention policies. Marks notification as deleted (hidden from end-user), but retention for admin/audit. Nullable; only set on soft delete.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_discussionboard_notifications_member discussionboard_members @relation(fields: [discussionboard_member_id], references: [id], onDelete: Cascade)

  @@index([discussionboard_member_id, opened], map: "discussionboard_notifications_discussionboard_member_i_f765790e")
  @@index([created_at])
  @@index([title(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([body(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Discussion Board Alert - Implements the alerts/urgent notifications requirement from the requirements analysis (03_discussionboard_features_and_functional_specifications.md, section 7; plus cross-reference with moderation & audit policies). 
///
/// Business explanation: This table stores urgent, high-visibility system or policy alerts targeted at users, typically for critical events (e.g., suspension warnings, urgent moderation outcomes, system-wide updates). Alerts are designed to demand prominent attention in user UI compared to routine notifications. Fully 3NF: each alert is atomic, unrelated fields and entity-specific details are externalized, audit events logged separately. For example, if a member is suspended, an alert is generated and displayed in a prominent banner.
///
/// Key relationships: References discussionboard_members for alert recipient.
/// Special behaviors: Alerts are prioritized for UI, include severity/type, full body, status, and are audited with timestamps. Could link to moderation/incident report context (future extension).
///
/// @namespace Notifications
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussionboard_alerts {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for this alert, ensuring system-wide traceability and immutability.
  id String @id @db.Uuid

  /// Recipient's {@link discussionboard_members.id}. Indicates which member this alert is for. Delivers alerts to the user's alert center or dashboard. Mandatory foreign key reference.
  discussionboard_member_id String @db.Uuid

  /// Alert type/category - Implements requirement to indicate nature and urgency (e.g., 'suspension_warning', 'policy_update', 'system_notice', 'important_announcement'). Used in UI sorting/filtering and analytics. Atomic and normalized.
  type String

  /// Severity level of the alert (e.g., 'critical', 'warning', 'info'). Implements requirement to differentiate UI treatment. Example: 'critical' triggers red banner; 'info' is less intrusive. Fully normalized, non-redundant.
  severity String

  /// Short alert headline - Implements prominent display and user clarity on subject. Example: 'Suspension Warning'. Used for attention-grabbing summaries in alerts center. Normalized for search/display.
  title String

  /// Full body of the alert - Implements detailed communication requirement for urgent incidents. Contains full explanation, relevant context, and actionable guidance. Example: 'Your account is suspended for policy violation XYZ.' Atomic, normalized.
  body String

  /// Alert is currently active and should be shown to user. Implements business rule for auto-dismissing resolved alerts, supports front-end badge logic, and analytics. Example: Suspension alert is_active until reinstated. Non-redundant, atomic trimmed down to status.
  is_active Boolean

  /// When the alert was generated. Supports audit and time-sequencing in UI. Fully normalized, required for analytics. Non-nullable.
  created_at DateTime @db.Timestamptz

  /// When the alert was marked as resolved/dismissed by system or recipient. Implements ability to archive past high-severity alerts, supports analytics on resolution speed. Nullable for active/unresolved alerts only. 3NF compliant.
  resolved_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_discussionboard_alerts_member discussionboard_members @relation(fields: [discussionboard_member_id], references: [id], onDelete: Cascade)

  @@index([discussionboard_member_id, is_active])
  @@index([created_at])
  @@index([title(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([body(ops: raw("gin_trgm_ops"))], type: Gin)
}

