import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardSection } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardSection";
import type { IPageIDiscussionboardSection } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardSection";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E test for admin discussion board section list retrieval with filters,
 * pagination, and sorting.
 *
 * Business context:
 *
 * - Admin users require robust listing of discussion board sections with
 *   full-featured filters, pagination, and sorting for management workflows.
 * - This test ensures all filterable fields (by configuration, name, enabled
 *   state, and order) and UI-level pagination/sorting are handled correctly.
 * - Also tests edge cases: empty result for non-existent filters, pagination
 *   boundaries, and proper handling of invalid sort column.
 *
 * Steps:
 *
 * 1. Create two sections with unique config IDs, names, orders, enabled/disabled
 *    states.
 * 2. Verify filtering by configuration ID returns only the correct record.
 * 3. Verify filtering by name returns only the right section.
 * 4. Verify filtering by enabled both true and false covers correct records.
 * 5. Filter by order returns section with the matching order value.
 * 6. Use pagination with limit=1, test both first and second page.
 * 7. Sorting by various columns (name descending, order ascending) is correct.
 * 8. Edge: Filtering with random values returns empty data as expected.
 * 9. Edge: Large page number returns no data.
 * 10. Edge: Sorting by unsupported column triggers validation error.
 */
export async function test_api_prefix_admin_discussionboardSections_test_list_sections_with_various_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create two distinct sections for testing
  const configurationId1 = typia.random<string & tags.Format<"uuid">>();
  const configurationId2 = typia.random<string & tags.Format<"uuid">>();
  const baseOrder = typia.random<number & tags.Type<"int32">>();
  const sectionName1 = RandomGenerator.alphabets(12);
  const sectionName2 = RandomGenerator.alphabets(12);
  const section1 =
    await api.functional.prefix.admin.discussionboardSections.create(
      connection,
      {
        body: {
          discussionboard_configuration_id: configurationId1,
          name: sectionName1,
          description: "Main generated alpha section.",
          order: baseOrder,
          enabled: true,
        } satisfies IDiscussionboardSection.ICreate,
      },
    );
  typia.assert(section1);
  const section2 =
    await api.functional.prefix.admin.discussionboardSections.create(
      connection,
      {
        body: {
          discussionboard_configuration_id: configurationId2,
          name: sectionName2,
          description: "Alt generated beta section.",
          order: baseOrder + 1,
          enabled: false,
        } satisfies IDiscussionboardSection.ICreate,
      },
    );
  typia.assert(section2);

  // 2. Filter by configuration ID
  let res = await api.functional.prefix.admin.discussionboardSections.index(
    connection,
    {
      body: {
        filters: { discussionboard_configuration_id: configurationId1 },
      },
    },
  );
  typia.assert(res);
  TestValidator.equals("filtered by config ID - only section1")(
    res.data.length,
  )(1);
  TestValidator.equals("config id match")(
    res.data[0].discussionboard_configuration_id,
  )(configurationId1);
  TestValidator.equals("id matches")(res.data[0].id)(section1.id);

  // 3. Filter by name (should yield only section2)
  res = await api.functional.prefix.admin.discussionboardSections.index(
    connection,
    {
      body: { filters: { name: sectionName2 } },
    },
  );
  typia.assert(res);
  TestValidator.equals("filtered by name - only section2")(res.data.length)(1);
  TestValidator.equals("name match")(res.data[0].name)(sectionName2);
  TestValidator.equals("id matches")(res.data[0].id)(section2.id);

  // 4. Filter by enabled state (true)
  res = await api.functional.prefix.admin.discussionboardSections.index(
    connection,
    {
      body: { filters: { enabled: true } },
    },
  );
  typia.assert(res);
  TestValidator.predicate("enabled section included")(
    res.data.some((s) => s.enabled === true && s.id === section1.id),
  );

  // 4b. Filter by enabled state (false)
  res = await api.functional.prefix.admin.discussionboardSections.index(
    connection,
    {
      body: { filters: { enabled: false } },
    },
  );
  typia.assert(res);
  TestValidator.predicate("disabled section included")(
    res.data.some((s) => s.enabled === false && s.id === section2.id),
  );

  // 5. Filter by order (should yield only section1)
  res = await api.functional.prefix.admin.discussionboardSections.index(
    connection,
    {
      body: { filters: { order: baseOrder } },
    },
  );
  typia.assert(res);
  TestValidator.equals("filtered by order")(res.data.length)(1);
  TestValidator.equals("order value")(res.data[0].order)(baseOrder);
  TestValidator.equals("id matches")(res.data[0].id)(section1.id);

  // 6. Pagination (limit=1, page=1)
  res = await api.functional.prefix.admin.discussionboardSections.index(
    connection,
    { body: { limit: 1, page: 1 } },
  );
  typia.assert(res);
  TestValidator.equals("pagination limit")(res.pagination.limit)(1);
  TestValidator.equals("pagination current page")(res.pagination.current)(1);
  TestValidator.predicate("pagination returns at most one")(
    res.data.length <= 1,
  );

  // Pagination: second page
  res = await api.functional.prefix.admin.discussionboardSections.index(
    connection,
    { body: { limit: 1, page: 2 } },
  );
  typia.assert(res);
  TestValidator.equals("pagination limit page 2")(res.pagination.limit)(1);
  TestValidator.equals("pagination second page")(res.pagination.current)(2);
  TestValidator.predicate("pagination second page at most one")(
    res.data.length <= 1,
  );

  // 7. Sorting by 'name:desc'
  res = await api.functional.prefix.admin.discussionboardSections.index(
    connection,
    { body: { sort: ["name:desc"] } },
  );
  typia.assert(res);
  TestValidator.predicate("sorted name descending")(
    res.data.length === 0 ||
      res.data.every((v, i, a) => i === 0 || a[i - 1].name >= v.name),
  );

  // Sorting by 'order:asc'
  res = await api.functional.prefix.admin.discussionboardSections.index(
    connection,
    { body: { sort: ["order:asc"] } },
  );
  typia.assert(res);
  TestValidator.predicate("sorted order ascending")(
    res.data.length === 0 ||
      res.data.every((v, i, a) => i === 0 || a[i - 1].order <= v.order),
  );

  // 8. Edge: non-existent filters
  const fakeConfig = typia.random<string & tags.Format<"uuid">>();
  res = await api.functional.prefix.admin.discussionboardSections.index(
    connection,
    { body: { filters: { discussionboard_configuration_id: fakeConfig } } },
  );
  typia.assert(res);
  TestValidator.equals("filter with non-existent config id")(res.data.length)(
    0,
  );

  res = await api.functional.prefix.admin.discussionboardSections.index(
    connection,
    { body: { filters: { name: "NonexistentSection" } } },
  );
  typia.assert(res);
  TestValidator.equals("filter with non-existent name")(res.data.length)(0);

  // 9. Edge: large page number (expect no data)
  res = await api.functional.prefix.admin.discussionboardSections.index(
    connection,
    { body: { limit: 1, page: 99 } },
  );
  typia.assert(res);
  TestValidator.equals("large page, no results")(res.data.length)(0);

  // 10. Edge: invalid sort column (should error)
  await TestValidator.error("invalid sort column")(() =>
    api.functional.prefix.admin.discussionboardSections.index(connection, {
      body: { sort: ["foobar:desc"] },
    }),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardSection } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardSection";

/**
 * Validate retrieval of a single discussion board section by sectionId.
 *
 * This test covers both successful fetching with a valid sectionId and error
 * handling for a non-existent ID:
 *
 * 1. Create a new section using the admin API, persist its key fields for
 *    verification.
 * 2. Retrieve the section by its newly assigned sectionId—verify all returned
 *    fields (id, configuration ref, name, description, order, enabled) match
 *    the originally created data (within business rules for auto-generated ids,
 *    nullable fields, etc).
 * 3. Attempt to retrieve a section with a random UUID that does not belong to any
 *    section (simulate a missing or unauthorized access)—expect a 404 'Not
 *    Found' error.
 * 4. This validates both normal operation and proper error response for invalid
 *    sectionId access.
 */
export async function test_api_discussionboardSections_test_get_section_details_by_id_with_valid_and_invalid_ids(
  connection: api.IConnection,
) {
  // 1. Create a new section for a known valid ID
  const createInput: IDiscussionboardSection.ICreate = {
    discussionboard_configuration_id: typia.random<
      string & tags.Format<"uuid">
    >(),
    name: RandomGenerator.alphabets(12),
    description: RandomGenerator.paragraph()(),
    order: typia.random<number & tags.Type<"int32">>(),
    enabled: true,
  };
  const createdSection =
    await api.functional.prefix.admin.discussionboardSections.create(
      connection,
      { body: createInput },
    );
  typia.assert(createdSection);

  // 2. Retrieve the section by its assigned sectionId
  const fetchedSection =
    await api.functional.prefix.admin.discussionboardSections.at(connection, {
      sectionId: createdSection.id,
    });
  typia.assert(fetchedSection);

  // 3. Check all relevant fields match the created data
  TestValidator.equals("discussionboard_configuration_id")(
    fetchedSection.discussionboard_configuration_id,
  )(createInput.discussionboard_configuration_id);
  TestValidator.equals("name")(fetchedSection.name)(createInput.name);
  TestValidator.equals("description")(fetchedSection.description)(
    createInput.description,
  );
  TestValidator.equals("order")(fetchedSection.order)(createInput.order);
  TestValidator.equals("enabled")(fetchedSection.enabled)(createInput.enabled);

  // 4. Negative test: use a new random UUID guaranteed not to match the created section
  let invalidSectionId = typia.random<string & tags.Format<"uuid">>();
  // Simple guarantee we don't match the real ID (low collision probability)
  while (invalidSectionId === createdSection.id) {
    invalidSectionId = typia.random<string & tags.Format<"uuid">>();
  }
  await TestValidator.error("404 Not Found for random UUID")(async () => {
    await api.functional.prefix.admin.discussionboardSections.at(connection, {
      sectionId: invalidSectionId,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardConfiguration } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardConfiguration";
import type { IDiscussionboardSection } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardSection";

/**
 * Test the creation and validation of discussion board section creation API.
 *
 * 1. Create a valid discussion board configuration (dependency) and use its id for
 *    section creation.
 * 2. Create a section: use valid properties (configuration id, unique name,
 *    description, order, enabled). Validate the section is created and fields
 *    match input values.
 * 3. Create a second section with the SAME name for EITHER the same config or a
 *    different one. Validate that a uniqueness constraint error is thrown (name
 *    is unique-per-table, not just per-config).
 * 4. Try creating a section with an invalid discussionboard_configuration_id:
 *    expect FK violation.
 * 5. Edge case validation - create with each required field missing (one at a
 *    time): should trigger validation errors.
 */
export async function test_api_prefix_admin_discussionboardSections_test_create_section_with_valid_and_duplicate_data(
  connection: api.IConnection,
) {
  // 1. Create a valid discussion board configuration
  const configurationInput: IDiscussionboardConfiguration.ICreate = {
    name: `cfg_${RandomGenerator.alphaNumeric(8)}`,
    settings_json: JSON.stringify({ allowPosts: true, moderation: "admin" }),
    description: "Test configuration for section tests",
  };
  const configuration =
    await api.functional.prefix.admin.discussionboardConfigurations.create(
      connection,
      { body: configurationInput },
    );
  typia.assert(configuration);

  // 2. Create a new section with valid properties
  const sectionInput: IDiscussionboardSection.ICreate = {
    discussionboard_configuration_id: configuration.id,
    name: `section_${RandomGenerator.alphaNumeric(8)}`,
    description: "Test section description",
    order: typia.random<number & tags.Type<"int32">>(),
    enabled: true,
  };
  const section =
    await api.functional.prefix.admin.discussionboardSections.create(
      connection,
      { body: sectionInput },
    );
  typia.assert(section);
  TestValidator.equals("configuration id")(
    section.discussionboard_configuration_id,
  )(sectionInput.discussionboard_configuration_id);
  TestValidator.equals("name")(section.name)(sectionInput.name);
  TestValidator.equals("order")(section.order)(sectionInput.order);
  TestValidator.equals("enabled")(section.enabled)(sectionInput.enabled);
  TestValidator.equals("description")(section.description)(
    sectionInput.description,
  );

  // 3. Attempt to create with duplicate name (should fail on uniqueness)
  // Optionally, use a new config for even stronger validation
  const secondConfigInput: IDiscussionboardConfiguration.ICreate = {
    name: `cfg_${RandomGenerator.alphaNumeric(8)}`,
    settings_json: JSON.stringify({ allowPosts: false, moderation: "user" }),
    description: "Second config for duplicate name edge check",
  };
  const secondConfig =
    await api.functional.prefix.admin.discussionboardConfigurations.create(
      connection,
      { body: secondConfigInput },
    );
  typia.assert(secondConfig);
  // Try duplicate name on the new (or same) config
  const duplicateInput: IDiscussionboardSection.ICreate = {
    ...sectionInput,
    discussionboard_configuration_id: secondConfig.id,
    order: sectionInput.order + 1,
    // use the EXACT same name to trigger global constraint
  };
  await TestValidator.error("duplicate section name should fail")(async () => {
    await api.functional.prefix.admin.discussionboardSections.create(
      connection,
      { body: duplicateInput },
    );
  });

  // 4. Attempt creation with invalid configuration id
  const invalidFkInput: IDiscussionboardSection.ICreate = {
    ...sectionInput,
    name: `section_${RandomGenerator.alphaNumeric(8)}`,
    discussionboard_configuration_id: typia.random<
      string & tags.Format<"uuid">
    >(), // random uuid likely non-existent
  };
  await TestValidator.error("invalid FK should fail")(async () => {
    await api.functional.prefix.admin.discussionboardSections.create(
      connection,
      { body: invalidFkInput },
    );
  });

  // 5. Edge cases: Omit each required field and expect validation errors
  // Required fields: discussionboard_configuration_id, name, order, enabled
  // (description is optional)
  const basePartial: Omit<
    IDiscussionboardSection.ICreate,
    "discussionboard_configuration_id" | "name" | "order" | "enabled"
  > = {
    description: "Partial for field omission cases",
  };
  const omitFieldCases: Array<Partial<IDiscussionboardSection.ICreate>> = [
    // Omitting configuration id
    {
      ...basePartial,
      name: `miss_cfg_${RandomGenerator.alphaNumeric(6)}`,
      order: typia.random<number & tags.Type<"int32">>(),
      enabled: true,
    },
    // Omitting name
    {
      ...basePartial,
      discussionboard_configuration_id: configuration.id,
      order: typia.random<number & tags.Type<"int32">>(),
      enabled: true,
    },
    // Omitting order
    {
      ...basePartial,
      discussionboard_configuration_id: configuration.id,
      name: `miss_order_${RandomGenerator.alphaNumeric(6)}`,
      enabled: true,
    },
    // Omitting enabled
    {
      ...basePartial,
      discussionboard_configuration_id: configuration.id,
      name: `miss_enabled_${RandomGenerator.alphaNumeric(6)}`,
      order: typia.random<number & tags.Type<"int32">>(),
    },
  ];
  for (const partialInput of omitFieldCases) {
    await TestValidator.error("missing required field validation error")(
      async () => {
        await api.functional.prefix.admin.discussionboardSections.create(
          connection,
          { body: partialInput as any },
        );
      },
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardConfiguration } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardConfiguration";
import type { IDiscussionboardSection } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardSection";

/**
 * Test updating a discussion board section, including valid updates and error
 * scenarios.
 *
 * This test covers:
 *
 * 1. Updating an existing section with new properties (name, description, config
 *    ref, order, enabled) and verifying persistence.
 * 2. Attempting to update a section to use a duplicate name (should fail with
 *    uniqueness violation).
 * 3. Attempting to update a section to reference a non-existent configuration
 *    (should fail with foreign key violation).
 * 4. Attempting to update a non-existent section (should fail with 404 not found).
 *
 * Steps:
 *
 * 1. Create two configurations (A and B).
 * 2. Create two sections, S1 (with config A) and S2 (with config B).
 * 3. Update S1 with new valid properties (change all updatable fields, including
 *    assignment to config B, and ensure persisted).
 * 4. Try to update S2's name to S1's updated name (should fail: uniqueness).
 * 5. Try to update S2 to use a random config id (should fail: foreign key
 *    violation).
 * 6. Try to update a random non-existent sectionId (should fail: 404).
 */
export async function test_api_discussionboardSections_test_update_section_with_valid_data_and_invalid_cases(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create configuration A
  const configA =
    await api.functional.prefix.admin.discussionboardConfigurations.create(
      connection,
      {
        body: {
          name: `config-A-${RandomGenerator.alphaNumeric(8)}`,
          settings_json: JSON.stringify({ allowPost: true, moderation: false }),
          description: "Test config A",
        },
      },
    );
  typia.assert(configA);

  // 2. Create configuration B
  const configB =
    await api.functional.prefix.admin.discussionboardConfigurations.create(
      connection,
      {
        body: {
          name: `config-B-${RandomGenerator.alphaNumeric(8)}`,
          settings_json: JSON.stringify({ allowPost: false, moderation: true }),
          description: "Test config B",
        },
      },
    );
  typia.assert(configB);

  // 3. Create two sections: S1 (with configA), S2 (with configB)
  const sectionA =
    await api.functional.prefix.admin.discussionboardSections.create(
      connection,
      {
        body: {
          discussionboard_configuration_id: configA.id,
          name: `section-A-${RandomGenerator.alphaNumeric(8)}`,
          description: "First test board section",
          order: 1,
          enabled: true,
        },
      },
    );
  typia.assert(sectionA);
  const sectionB =
    await api.functional.prefix.admin.discussionboardSections.create(
      connection,
      {
        body: {
          discussionboard_configuration_id: configB.id,
          name: `section-B-${RandomGenerator.alphaNumeric(8)}`,
          description: "Second test board section",
          order: 2,
          enabled: false,
        },
      },
    );
  typia.assert(sectionB);

  // 4. Update sectionA with new property values
  const newProps = {
    discussionboard_configuration_id: configB.id,
    name: `updated-section-${RandomGenerator.alphaNumeric(8)}`,
    description: "Section A updated description",
    order: 10,
    enabled: false,
  } satisfies IDiscussionboardSection.IUpdate;
  const updatedSectionA =
    await api.functional.prefix.admin.discussionboardSections.update(
      connection,
      {
        sectionId: sectionA.id,
        body: newProps,
      },
    );
  typia.assert(updatedSectionA);
  // Validate update
  TestValidator.equals("updated section config id")(
    updatedSectionA.discussionboard_configuration_id,
  )(configB.id);
  TestValidator.equals("updated section name")(updatedSectionA.name)(
    newProps.name,
  );
  TestValidator.equals("updated section description")(
    updatedSectionA.description,
  )(newProps.description);
