/**
 * Test that filtering the discussion board category list by name and enabled
 * status returns only matching categories.
 *
 * Business context: Admins should be able to filter categories to easily find
 * entries by name (exact match) and by their enabled/disabled status. This is
 * crucial for managing board organization and visibility. The test ensures the
 * filter logic strictly enforces these parameters and returns no spurious
 * entries.
 *
 * Test process:
 *
 * 1. Create multiple discussion board categories with varying values: at least two
 *    with different names, and both enabled and disabled states represented.
 *    Ensure at least two categories have the same name but different enabled
 *    values to validate combined filtering.
 * 2. Request a paginated category list, using a filter with name equal to the
 *    chosen test name and enabled=true.
 * 3. Verify the result only contains the category (or categories) with the target
 *    name and enabled=true. Ensure disabled or differently-named categories are
 *    excluded from the response.
 * 4. Check that all returned category records have the correct name and
 *    enabled=true; also validate none with the matching name have enabled=false
 *    and vice versa.
 */
export async function test_api_discussionboardCategories_test_list_discussionboard_categories_with_name_and_enabled_filter(
  connection: api.IConnection,
) {
  // 1. Prepare a section id for all test data (isolation)
  const sectionId = typia.random<string & tags.Format<"uuid">>();

  // 2. Create two categories with the same name, one enabled and one disabled
  const categoryName = "E2E_FILTER_TARGET";
  const createdEnabled =
    await api.functional.prefix.admin.discussionboardCategories.create(
      connection,
      {
        body: {
          discussionboard_section_id: sectionId,
          name: categoryName,
          order: 1,
          enabled: true,
          description: "test enabled filter",
        } satisfies IDiscussionboardCategory.ICreate,
      },
    );
  typia.assert(createdEnabled);
  const createdDisabled =
    await api.functional.prefix.admin.discussionboardCategories.create(
      connection,
      {
        body: {
          discussionboard_section_id: sectionId,
          name: categoryName,
          order: 2,
          enabled: false,
          description: "test disabled filter",
        } satisfies IDiscussionboardCategory.ICreate,
      },
    );
  typia.assert(createdDisabled);

  // 3. Create another category with a different name
  const otherName = "E2E_OTHER_CATEGORY";
  const createdOther =
    await api.functional.prefix.admin.discussionboardCategories.create(
      connection,
      {
        body: {
          discussionboard_section_id: sectionId,
          name: otherName,
          order: 3,
          enabled: true,
          description: "test other category",
        } satisfies IDiscussionboardCategory.ICreate,
      },
    );
  typia.assert(createdOther);

  // 4. Request a filtered category list with name=categoryName and enabled=true
  const listResult =
    await api.functional.prefix.admin.discussionboardCategories.index(
      connection,
      {
        body: {
          name: categoryName,
          enabled: true,
          discussionboard_section_id: sectionId, // for test isolation
        } satisfies IDiscussionboardCategory.IRequest,
      },
    );
  typia.assert(listResult);

  // 5. Assert all returned records have correct name and enabled=true in the correct section
  for (const entry of listResult.data) {
    TestValidator.equals("filtered by name")(entry.name)(categoryName);
    TestValidator.equals("filtered by enabled")(entry.enabled)(true);
    TestValidator.equals("filtered by section")(
      entry.discussionboard_section_id,
    )(sectionId);
  }

  // 6. Assert that only the enabled, correctly-named record is present (disabled/other are excluded)
  TestValidator.predicate(
    "should only return enabled entries with correct name and section",
  )(
    listResult.data.every(
      (e) =>
        e.name === categoryName &&
        e.enabled &&
        e.discussionboard_section_id === sectionId,
    ),
  );

  // 7. Assert that disabled record and unrelated names are excluded
  TestValidator.predicate(
    "should not include disabled or unrelated categories",
  )(
    listResult.data.every(
      (e) => e.id !== createdDisabled.id && e.name !== otherName,
    ),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
