import type { IPageIDiscussionboardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardCategory";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Verify paginated and sorted retrieval of discussion board categories via
 * admin API.
 *
 * This test checks that PATCH /prefix/admin//discussionboardCategories returns
 * categories sorted by the `order` field descending and, if supported,
 * paginated according to provided limit/offset. It bulk-creates categories with
 * controlled order values, then verifies the API's data order and paging
 * mechanics.
 *
 * Workflow:
 *
 * 1. Bulk-create > page-size categories, each with unique sequential "order"
 *    values, all in a single section.
 * 2. Issue a PATCH request with the section ID, requesting categories sorted by
 *    `order` descending (highest order first).
 * 3. Validate:
 *
 *    - Response data is sorted by `order` descending
 *    - (If pagination supported) number of items matches page size
 *    - Returned IDs and order fields match the expected slice
 */
export async function test_api_discussionboardCategories_test_list_discussionboard_categories_with_pagination_and_order_sorting(
  connection: api.IConnection,
) {
  // Step 1: Bulk-create categories with sequential order for deterministic test
  const sectionId: string = typia.random<string & tags.Format<"uuid">>();
  const totalCategories = 12;
  const limit = 5;
  const offset = 3;

  // Prepare and create categories with order fields 0..11
  const created: IDiscussionboardCategory[] = [];
  for (let i = 0; i < totalCategories; ++i) {
    const category =
      await api.functional.prefix.admin.discussionboardCategories.create(
        connection,
        {
          body: {
            discussionboard_section_id: sectionId,
            name: `Category #${i}`,
            description: `Description ${i}`,
            order: i,
            enabled: true,
          } satisfies IDiscussionboardCategory.ICreate,
        },
      );
    typia.assert(category);
    created.push(category);
  }

  // Step 2: Attempt a paginated, sorted query for categories in this section
  // Note: IDiscussionboardCategory.IRequest does not include explicit paging/sort fields, so this test focuses on verifying descending order
  const output =
    await api.functional.prefix.admin.discussionboardCategories.index(
      connection,
      {
        body: {
          discussionboard_section_id: sectionId,
          // order: omitted to NOT filter, but expect descending sorting in the test verifications
        },
      },
    );
  typia.assert(output);

  // Step 3: Validate that output is sorted by order descending
  const received = output.data;
  const expected = [...created].sort((a, b) => b.order - a.order);

  // 1. Categories must be sorted by order descending
  const isSorted = received.every(
    (v, i, arr) => i === 0 || arr[i - 1].order >= v.order,
  );
  TestValidator.predicate("categories sorted by order descending")(isSorted);

  // 2. If paging info provided, validate page size
  if (output.pagination && typeof output.pagination.limit === "number") {
    TestValidator.equals("page size matches")(received.length)(
      output.pagination.limit,
    );
  }

  // 3. Verify IDs and orders match the expected descending sequence for the first N items
  for (let i = 0; i < Math.min(received.length, expected.length); ++i) {
    TestValidator.equals(`category id at row ${i}`)(received[i].id)(
      expected[i].id,
    );
    TestValidator.equals(`category order at row ${i}`)(received[i].order)(
      expected[i].order,
    );
  }
}

