 * update(put)로 변경할 수 있는지 확인합니다. 모든 변경사항이 즉시 반영되고, 응답 필드는 갱신 요청값과 정확히 일치해야 함을
 * 보장합니다.
 *
 * [실행 순서]
 *
 * 1. 카테고리 신규 생성 (필수 필드 포함)
 * 2. 생성된 id를 대상으로 모든 주요 수정 필드(name, description, order, enabled) 변경
 * 3. 수정(put) API 호출 및 결과 검증
 *
 *    - 응답 값이 요청 body와 100% 일치 (id/section-id는 불변, 나머지는 요청한대로)
 * 4. 추가 타입 안정성 및 논리 불변성(type assert, id consistency 등) 체크
 */
export async function test_api_prefix_admin_discussionboardCategories_test_update_discussionboard_category_success(
  connection: api.IConnection,
) {
  // 1. 카테고리 신규 생성(임의/랜덤 값)
  const sectionId = typia.random<string & tags.Format<"uuid">>();
  const createBody: IDiscussionboardCategory.ICreate = {
    discussionboard_section_id: sectionId,
    name: "초기이름" + RandomGenerator.alphabets(5),
    description: "초기설명 " + RandomGenerator.paragraph()(1, 2),
    order: typia.random<number & tags.Type<"int32">>(),
    enabled: true,
  };
  const created =
    await api.functional.prefix.admin.discussionboardCategories.create(
      connection,
      { body: createBody },
    );
  typia.assert(created);
  TestValidator.equals("초기 name")(created.name)(createBody.name);
  TestValidator.equals("초기 description")(created.description)(
    createBody.description,
  );
  TestValidator.equals("초기 section-id")(created.discussionboard_section_id)(
    createBody.discussionboard_section_id,
  );
  TestValidator.equals("초기 order")(created.order)(createBody.order);
  TestValidator.equals("초기 enabled")(created.enabled)(createBody.enabled);

  // 2. 카테고리 주요 필드 업데이트(이름/설명/순서/활성화 모두 변경)
  const updateBody: IDiscussionboardCategory.IUpdate = {
    discussionboard_section_id: created.discussionboard_section_id,
    name: "수정이름" + RandomGenerator.alphabets(6),
    description: "수정설명 " + RandomGenerator.paragraph()(1, 2),
    order: created.order + 10,
    enabled: !created.enabled,
  };
  const updated =
    await api.functional.prefix.admin.discussionboardCategories.update(
      connection,
      { categoryId: created.id, body: updateBody },
    );
  typia.assert(updated);

  // 3. 응답 결과가 요청 update body 값과 완전히 일치하는지 검증
  TestValidator.equals("id 동일")(updated.id)(created.id);
  TestValidator.equals("section-id 동일")(updated.discussionboard_section_id)(
    updateBody.discussionboard_section_id,
  );
  TestValidator.equals("수정 name")(updated.name)(updateBody.name);
  TestValidator.equals("수정 description")(updated.description)(
    updateBody.description,
  );
  TestValidator.equals("수정 order")(updated.order)(updateBody.order);
  TestValidator.equals("수정 enabled")(updated.enabled)(updateBody.enabled);
  // 타입 단언 및 구조 불변성 추가 체크
  typia.assert<typeof updated>(updated);
}

