  );
  typia.assert(output);
  // 반환 스키마(필드) 및 타입 검증
  TestValidator.predicate("pagination exists")(
    "pagination" in output && typeof output.pagination === "object",
  );
  TestValidator.predicate("pagination.current is number")(
    typeof output.pagination.current === "number",
  );
  TestValidator.predicate("data exists and is array")(
    Array.isArray(output.data),
  );
  if (output.data.length > 0) {
    for (const admin of output.data) {
      TestValidator.predicate("id is uuid")(
        typeof admin.id === "string" && admin.id.length > 0,
      );
      TestValidator.predicate("created_at is datetime string")(
        typeof admin.created_at === "string" && admin.created_at.length > 0,
      );
      // 오직 id와 created_at 필드만 존재하는지 확인 (불필요 필드 포함 여부 체크)
      TestValidator.equals("no extra fields on admin record")(
        Object.keys(admin).sort(),
      )(["created_at", "id"]);
    }
  }

  // 2. 랜덤 id로 필터: 데이터 없음 검증
  const noMatchId = typia.random<string & tags.Format<"uuid">>();
  const outputNoMatch = await api.functional.prefix.admin.actors.admins.index(
    connection,
    { body: { id: noMatchId } },
  );
  typia.assert(outputNoMatch);
  TestValidator.equals("no result for random id")(outputNoMatch.data.length)(0);

  // 3. pagination.pages 초과 페이지 요청
  const overPage = output.pagination.pages + 10;
  // current/limit 옵션이 API body에 있으면 활용, 없으면 이 스텝 건너뜀
  // 본 DTO에는 current/limit 존재하지 않아 skip

  // 4. 인증 없는 connection(unauthorized): 401 또는 403 에러 확인
  await TestValidator.error("unauthorized access fails")(async () => {
    const connectionNoAuth = { ...connection, headers: {} };
    await api.functional.prefix.admin.actors.admins.index(connectionNoAuth, {
      body: {},
    });
  });
}

