 *
 * Steps:
 *
 * 1. Create multiple warning logs using moderator endpoint, with varying
 *    moderator_id and warned_member_id.
 * 2. For each created log, use the admin 'get by id' endpoint to fetch by PK.
 * 3. Assert that the fetched log matches all fields (id, moderator_id,
 *    warned_member_id, warning_reason, issued_at) of the original.
 * 4. Attempt to fetch a non-existent id and confirm that error is thrown (e.g.,
 *    404 error).
 * 5. Validate no difference in admin retrieval whether the creator/recipient is
 *    the same or different.
 *
 * Note: Admin authentication is assumed to be present via the connection
 * context, since explicit admin login endpoints are not provided in the API
 * set.
 */
export async function test_api_warningLogs_test_get_warning_log_by_id_with_admin_role(
  connection: api.IConnection,
) {
