  const createdLogs: IWarningLog[] = [];

  for (const [moderator_id, warned_member_id] of [
    [moderator1, warned_member1],
    [moderator1, warned_member2],
    [moderator2, warned_member1],
    [moderator2, warned_member2],
  ]) {
    const warning_reason = `Test warning from ${moderator_id} to ${warned_member_id}`;
    const issued_at = new Date().toISOString();
    const log = await api.functional.prefix.moderator.warningLogs.create(
      connection,
      {
        body: {
          moderator_id,
          warned_member_id,
          warning_reason,
          issued_at,
        } satisfies IWarningLog.ICreate,
      },
    );
    typia.assert(log);
    createdLogs.push(log);
    // Field-by-field check
    TestValidator.equals("moderator_id matches")(log.moderator_id)(
      moderator_id,
    );
    TestValidator.equals("warned_member_id matches")(log.warned_member_id)(
      warned_member_id,
    );
    TestValidator.equals("warning_reason matches")(log.warning_reason)(
      warning_reason,
    );
    TestValidator.equals("issued_at matches")(log.issued_at)(issued_at);
  }

  // 2. For each log, retrieve as admin by id and check for fidelity
  for (const log of createdLogs) {
    const result = await api.functional.prefix.admin.warningLogs.at(
      connection,
      {
        id: log.id,
      },
    );
    typia.assert(result);
    TestValidator.equals("id matches")(result.id)(log.id);
    TestValidator.equals("moderator_id matches")(result.moderator_id)(
      log.moderator_id,
    );
    TestValidator.equals("warned_member_id matches")(result.warned_member_id)(
      log.warned_member_id,
    );
    TestValidator.equals("warning_reason matches")(result.warning_reason)(
      log.warning_reason,
    );
    TestValidator.equals("issued_at matches")(result.issued_at)(log.issued_at);
  }

  // 3. Attempt to fetch a non-existent warning log id (should throw error)
  await TestValidator.error("fetching non-existent id throws error")(
    async () => {
      await api.functional.prefix.admin.warningLogs.at(connection, {
        id: typia.random<string & tags.Format<"uuid">>(),
      });
    },
  );
}

