/**
 * Validate that an admin can create a warning log for any targeted member,
 * respecting business and schema rules.
 *
 * - Attempts warning log creation with a valid moderator and valid warned_member,
 *   using unique (moderator_id, warned_member_id, warning_reason, issued_at).
 * - Verifies that created log is correctly stored by comparing all returned
 *   fields.
 * - Tests repeated creation with the same moderator, member, reason, and
 *   timestamp, checking whether the system rejects duplicates or creates
 *   multiple entries (business rule undefined).
 * - Attempts creation with invalid (non-existent) moderator_id and
 *   warned_member_id, expecting failures if schema/business layer validates
 *   member existence.
 * - Attempts edge cases: blank warning_reason and extremely long warning_reason.
 *
 * Steps:
 *
 * 1. Create a valid warning log (random UUIDs for moderator/member, reasonable
 *    reason, ISO date).
 * 2. Validate output fields against input.
 * 3. Attempt duplicate creation (same data).
 * 4. Attempt creation with made-up/non-existent member IDs.
 * 5. Attempt creation with blank reason.
 * 6. Attempt creation with overly long reason.
 */
export async function test_api_prefix_admin_warningLogs_create(
  connection: api.IConnection,
) {
  // 1. Prepare valid test data
  const moderatorId = typia.random<string & tags.Format<"uuid">>();
  const warnedMemberId = typia.random<string & tags.Format<"uuid">>();
  const issuedAt = new Date().toISOString();
  const warningReason = `Automoderator Test Reason - ${RandomGenerator.paragraph()(5)}`;

  // 2. Create warning log
  const log = await api.functional.prefix.admin.warningLogs.create(connection, {
    body: {
      moderator_id: moderatorId,
      warned_member_id: warnedMemberId,
      warning_reason: warningReason,
      issued_at: issuedAt,
    } satisfies IWarningLog.ICreate,
  });
  typia.assert(log);
  TestValidator.equals("field: moderator_id")(log.moderator_id)(moderatorId);
  TestValidator.equals("field: warned_member_id")(log.warned_member_id)(
    warnedMemberId,
  );
  TestValidator.equals("field: warning_reason")(log.warning_reason)(
    warningReason,
  );
  TestValidator.equals("field: issued_at")(log.issued_at)(issuedAt);

  // 3. Attempt duplicate warning log creation
  const duplicateCreate = async () => {
    await api.functional.prefix.admin.warningLogs.create(connection, {
      body: {
        moderator_id: moderatorId,
        warned_member_id: warnedMemberId,
        warning_reason: warningReason,
        issued_at: issuedAt,
      } satisfies IWarningLog.ICreate,
    });
  };
  await TestValidator.error(
    "Duplicate warning log should fail if uniqueness enforced",
  )(duplicateCreate);

  // 4. Non-existent IDs (simulate with new UUIDs)
  const fakeId = typia.random<string & tags.Format<"uuid">>();
  const badModeratorId = fakeId;
  const badWarnedId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("Invalid moderator_id should fail")(() =>
    api.functional.prefix.admin.warningLogs.create(connection, {
      body: {
        moderator_id: badModeratorId,
        warned_member_id: warnedMemberId,
        warning_reason: warningReason,
        issued_at: issuedAt,
      },
    }),
  );
  await TestValidator.error("Invalid warned_member_id should fail")(() =>
    api.functional.prefix.admin.warningLogs.create(connection, {
      body: {
        moderator_id: moderatorId,
        warned_member_id: badWarnedId,
        warning_reason: warningReason,
        issued_at: issuedAt,
      },
    }),
  );

  // 5. Blank warning_reason
  await TestValidator.error("Blank warning_reason should fail")(() =>
    api.functional.prefix.admin.warningLogs.create(connection, {
      body: {
        moderator_id: moderatorId,
        warned_member_id: warnedMemberId,
        warning_reason: "",
        issued_at: issuedAt,
      },
    }),
