 *
 * - 정상 생성 케이스: 유효한 입력(모든 필수값)으로 정지 내역 성공 생성, 반환값이 입력 데이터와 일치하는지 확인합니다.
 * - 경계/에러 케이스: 비존재 회원, 과거 종료일, 불충분 권한 등 비정상 시나리오에서 적절한 예외가 발생하는지 검증합니다.
 * - TypeScript 타입상 필수 필드 누락 케이스는 테스트하지 않습니다 (컴파일 타임에서 검출됩니다).
 *
 * 검증 흐름:
 *
 * 1. 모더레이터 권한으로 유효 입력값으로 suspension 생성 및 반환값 검증
 * 2. 존재하지 않는 회원 id로 생성 시 에러 검증
 * 3. 종료시점이 과거인(잘못된 범위) 경우 에러 검증
 * 4. 권한 없는 요청(Authorization header 누락) 시 에러 검증
 */
export async function test_api_suspensions_test_create_suspension_with_valid_data_moderator(
  connection: api.IConnection,
) {
  // 1. 정상: 모더레이터가 suspension 생성
  const now = new Date();
  const startedAt = now.toISOString();
  const endsAt = new Date(
    now.getTime() + 1000 * 60 * 60 * 24 * 7,
  ).toISOString(); // 7일 뒤

  const validInput: ISuspension.ICreate = {
    moderator_id: typia.random<string & tags.Format<"uuid">>(),
    suspended_member_id: typia.random<string & tags.Format<"uuid">>(),
    suspension_reason: "악의적 게시물 등록",
    suspension_started_at: startedAt,
    suspension_ends_at: endsAt,
  };
  const created = await api.functional.prefix.moderator.suspensions.create(
    connection,
    { body: validInput },
  );
  typia.assert(created);
  TestValidator.equals("moderator_id")(created.moderator_id)(
    validInput.moderator_id,
  );
  TestValidator.equals("suspended_member_id")(created.suspended_member_id)(
    validInput.suspended_member_id,
  );
  TestValidator.equals("suspension_reason")(created.suspension_reason)(
    validInput.suspension_reason,
  );
  TestValidator.equals("suspension_started_at")(created.suspension_started_at)(
    validInput.suspension_started_at,
  );
  TestValidator.equals("suspension_ends_at")(created.suspension_ends_at)(
    validInput.suspension_ends_at,
  );

  // 2. 존재하지 않는 member_id 입력 시 에러
  const invalidInput = {
    ...validInput,
    suspended_member_id: typia.random<string & tags.Format<"uuid">>(),
  };
  await TestValidator.error("존재하지 않는 member_id 에러")(() =>
    api.functional.prefix.moderator.suspensions.create(connection, {
      body: invalidInput,
    }),
  );

  // 3. 종료시점이 과거인 경우(시작일 이후여야 하는지 시스템 규칙에 맞게 테스트)
  const endsAtPast = new Date(
    now.getTime() - 1000 * 60 * 60 * 24,
  ).toISOString(); // 1일 전
  const pastEndInput = { ...validInput, suspension_ends_at: endsAtPast };
  await TestValidator.error("종료 시점이 과거일 때 에러")(() =>
    api.functional.prefix.moderator.suspensions.create(connection, {
      body: pastEndInput,
    }),
  );

  // 4. 권한 없는 요청(Authorization 누락)
  const nonAuthedConnection = { ...connection, headers: {} };
  await TestValidator.error("비인가자 권한 에러")(() =>
    api.functional.prefix.moderator.suspensions.create(
      nonAuthedConnection as api.IConnection,
      { body: validInput },
    ),
  );
}

