import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IPageIDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardMembers";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Discussionboard_members 목록 페이징/필터/검색 API 엔드 투 엔드 검증
 *
 * - 여러 명의 discussionboard_members를 서로 다른 created_at 값으로 가입시킵니다.
 * - 다양한 필터(id, created_at), 페이징(page, limit) 요청 조합으로 index API를 호출합니다.
 * - 각 호출 결과에 대해 필터/페이지 조건에 해당하는 멤버만 포함되는지, 페이징/전체 카운트가 올바른지 확인합니다.
 * - 인증 없이 시도 시 접근 거부(권한 부족) 오류가 발생하는 점도 검증합니다.
 *
 * 절차:
 *
 * 1. 멤버 여러 명을 가입시켜 테스트 데이터를 준비
 * 2. Created_at 값을 시간차로 분포되게 생성
 * 3. Id 필터, created_at 단일/범위 필터, 페이지/limit 조합으로 요청
 * 4. 각 결과 데이터, 페이지 정보, total count, 권한 거부 등 명시적 검증
 */
export async function test_api_prefix_member_actors_members_test_list_members_with_pagination_and_filters(
  connection: api.IConnection,
) {
  // 1. 멤버 여러 명(5명)을 시간이 다르게 생성하여 등록
  const memberInputs: IDiscussionboardMembers.ICreate[] = ArrayUtil.repeat(5)((
    i,
  ) => {
    const now = new Date();
    now.setMinutes(now.getMinutes() - i * 10); // 각 멤버 created_at 10분 간격 차이
    return {
      id: typia.random<string & tags.Format<"uuid">>(),
      created_at: now.toISOString() as string & tags.Format<"date-time">,
    };
  });
  const members: IDiscussionboardMembers[] = await ArrayUtil.asyncMap(
    memberInputs,
  )(async (input) => {
    const member = await api.functional.prefix.member.actors.members.create(
      connection,
      {
        body: input,
      },
    );
    typia.assert(member);
    return member;
  });

  // 2. id 필터: 각 멤버 id로 단일 조회, 결과 1건임을 확인
  for (const m of members) {
    const out = await api.functional.prefix.member.actors.members.index(
      connection,
      {
        body: { id: m.id },
      },
    );
    typia.assert(out);
    TestValidator.equals("id 단일 필터 시 1명 반환")(out.data.length)(1);
    TestValidator.equals("id 매치")(out.data[0].id)(m.id);
    TestValidator.equals("created_at 매치")(out.data[0].created_at)(
      m.created_at,
    );
  }

  // 3. created_at 단일값으로 필터링: 가장 최근 3명만 추출
  const recent = members.slice(0, 3);
  for (const m of recent) {
    const out = await api.functional.prefix.member.actors.members.index(
      connection,
      {
        body: { created_at: m.created_at },
      },
    );
    typia.assert(out);
    const included = out.data.some((x) => x.id === m.id);
    TestValidator.predicate("created_at 단일값 포함")(included);
  }

  // 4. 페이지네이션: 5명 전체, page 2, limit 2 → 3번째·4번째 멤버만 반환
  const outPage2 = await api.functional.prefix.member.actors.members.index(
    connection,
    {
      body: { page: 2, limit: 2 },
    },
  );
  typia.assert(outPage2);
  TestValidator.equals("페이지2, limit2 데이터 개수")(outPage2.data.length)(2);
  TestValidator.equals("페이지네이션 current")(outPage2.pagination.current)(2);
  TestValidator.equals("limit")(outPage2.pagination.limit)(2);
  TestValidator.equals("전체 개수")(outPage2.pagination.records)(5);
  TestValidator.equals("전체 페이지")(outPage2.pagination.pages)(3);

  // 5. 인증 없이 요청: 별도 connection 사용(Authorization 제거)
  const unauthConnection = {
    ...connection,
    headers: { ...connection.headers },
  };
  delete unauthConnection.headers.Authorization;
  await TestValidator.error("비인증 시 권한 오류")(async () => {
    await api.functional.prefix.member.actors.members.index(unauthConnection, {
      body: {},
    });
  });
}

