 * 2. 실제 가입된 멤버와 일치하지 않는 id 값(임의의 새 uuid), 또는 멤버의 생성시각에 맞지 않는 시점 등, 불가능한 필터로 검색 요청
 * 3. 결과 데이터가 빈 배열([])임을 검증하며, 예외 없이 정상 동작하는지 확인
 *
 * 주요 비즈니스 요구:
 *
 * - List/filter API가 요청 조건 미일치 시 빈 목록만 반환하며 에러가 발생하지 않을 것
 *
 * Step by step:
 *
 * 1. 임의의 멤버를 최소 1건 등록(post)
 * 2. 존재하지 않는 id로 검색(patch)하여 빈 목록([]) 반환 확인
 * 3. Created_at 필드에 절대 일치할 수 없는 랜덤 값으로 검색 요청 후 역시 빈 목록([]) 반환 확인
 */
export async function test_api_prefix_member_actors_members_test_list_members_returns_empty_when_no_match(
  connection: api.IConnection,
) {
  // 1. 임의의 멤버를 등록
  const created = await api.functional.prefix.member.actors.members.create(
    connection,
    {
      body: {
        id: typia.random<string & tags.Format<"uuid">>(),
        created_at: new Date().toISOString(),
      },
    },
  );
  typia.assert(created);

  // 2. 존재하지 않는 랜덤 uuid로 검색
  const impossibleId = typia.random<string & tags.Format<"uuid">>();
  const resultById = await api.functional.prefix.member.actors.members.index(
    connection,
    {
      body: {
        id: impossibleId,
        page: 1,
        limit: 100,
      },
    },
  );
  typia.assert(resultById);
  TestValidator.equals("members list by impossible id should be empty")(
    resultById.data,
  )([]);

  // 3. 존재할 수 없는 미래 시간 또는 지나치게 과거(created_at)로 검색
  const impossibleDate = new Date(
    Date.now() + 1000 * 60 * 60 * 24 * 365 * 50,
  ).toISOString(); // 50년 뒤
  const resultByDate = await api.functional.prefix.member.actors.members.index(
    connection,
    {
      body: {
        created_at: impossibleDate,
        page: 1,
        limit: 100,
      },
    },
  );
  typia.assert(resultByDate);
  TestValidator.equals("members list by impossible created_at should be empty")(
    resultByDate.data,
  )([]);
}

