  // 3. 멤버 A 세션에서 B의 id로 PUT(수정) 시도 - 시스템의 권한 거부/404 오류를 체크
  await TestValidator.error("not my member - forbidden or not found")(
    async () => {
      await api.functional.prefix.member.my.actors.members.update(connection, {
        id: memberB.id,
        body: {
          id: memberB.id,
          created_at: memberB.created_at,
        },
      });
    },
  );
