 * 3. "A" 모더레이터가 방금 생성된(본인 소유 아님) Assignment의 update API를 호출합니다.
 * 4. 시스템은 해당 요청에 대해 반드시 403 Forbidden 또는 401 Unauthorized 오류를 반환해야 하며, 성공적으로
 *    update가 되면 안 됩니다.
 * 5. API 호출 결과로 예외가 발생해야 하며, 접근 제한 결과만 검증(오류 메시지 등 상세 검증은 생략).
 *
 * [검증 포인트]
 *
 * - 본인 소유가 아닌 리소스 update에 대한 제한(소유성/권한 체크)
 * - 예외 발생만 단순 테스트, 기타 상세 Business Logic은 별도 시나리오에서 검증
 */
export async function test_api_prefix_test_update_other_moderator_assignment_is_forbidden(
  connection: api.IConnection,
) {
  // 1. 관리자가 (A가 아님) 모더레이터 Assignment를 생성
  const moderatorAssignment =
    await api.functional.prefix.admin.actors.moderators.create(connection, {
      body: {
        id: typia.random<string & tags.Format<"uuid">>(),
        created_at: new Date().toISOString(),
      },
    });
  typia.assert(moderatorAssignment);

  // 2. (전제) A 모더레이터로 인증되어 있다고 가정 (별도 인증 API 미제공 시 가정 처리)
  // 실제 인증 플로우는 별도 account API에서 처리해야 하나, 이 시나리오에서는 권한 없는 상태로 진행

  // 3. A가 본인 소유가 아닌 Assignment update 시도
  await TestValidator.error("다른 사람의 모더레이터 Assignment는 수정 불가")(
    async () => {
      await api.functional.prefix.moderator.my.actors.moderators.update(
        connection,
        {
          id: moderatorAssignment.id,
          body: {
            id: moderatorAssignment.id,
            created_at: new Date().toISOString(),
          },
        },
      );
    },
  );
}

