/**
 * Test the retrieval of an existing guest record by id.
 *
 * This test verifies that when you create a new guest record, you can
 * immediately retrieve it using its id. It checks that both the id and
 * created_at fields in the response from the GET call match what was provided
 * when the record was created. This ensures the guest record lookup
 * functionality is correct and that the database stores and returns guest
 * records accurately.
 *
 * Test Workflow:
 *
 * 1. Create a new IDiscussionboardGuests record (using POST
 *    /prefix/member//actors/guests).
 * 2. Retrieve this newly created record using GET
 *    /prefix/member//actors/guests/:id.
 * 3. Assert that the id and created_at from the GET response match the initial
 *    creation.
 */
export async function test_api_prefix_member_actors_guests_test_retrieve_existing_guest_record_by_id(
  connection: api.IConnection,
) {
  // 1. Create a new guest record
  const guestInput: IDiscussionboardGuests.ICreate = {
    id: typia.random<string & tags.Format<"uuid">>(),
    created_at: new Date().toISOString() as string & tags.Format<"date-time">,
  };
  const created: IDiscussionboardGuests =
    await api.functional.prefix.member.actors.guests.create(connection, {
      body: guestInput,
    });
  typia.assert(created);

  // 2. Retrieve the same guest record by id
  const fetched: IDiscussionboardGuests =
    await api.functional.prefix.member.actors.guests.at(connection, {
      id: guestInput.id,
    });
  typia.assert(fetched);

  // 3. Validate that id and created_at match
  TestValidator.equals("guest id matches")(fetched.id)(guestInput.id);
  TestValidator.equals("guest created_at matches")(fetched.created_at)(
    guestInput.created_at,
  );
}

