  // 3. id 불변 확인, created_at이 요청값으로 갱신 확인
  TestValidator.equals("id unchanged")(updated.id)(guest.id);
  TestValidator.equals("created_at field updated")(updated.created_at)(
    newCreatedAt,
  );

  // 4. id 불일치 PUT 시도 시 오류
  await TestValidator.error("id mismatch should fail")(async () =>
    api.functional.prefix.member.my.actors.guests.update(connection, {
      id: guest.id,
      body: {
        id: typia.random<string & tags.Format<"uuid">>(),
        created_at: newCreatedAt,
      } satisfies IDiscussionboardGuests.IUpdate,
    }),
  );
}

