/**
 * 게스트(ID: UUID)의 primary key 불변성 테스트
 *
 * Discussionboard_guests(익명 게시판 게스트 추적 레코드)에서, id(PK)는 절대 수정될 수 없음을 검증합니다. 이
 * 테스트는 다음 케이스를 점검합니다:
 *
 * 1. 신규 게스트 레코드 생성 (id1, created_at1)
 * 2. PUT /prefix/member//my/actors/guests/{id}로 id(PK)를 id2로 수정 시도 (body에 id2,
 *    path param엔 id1)
 * 3. API가 에러(불변성 위반)로 거부해야 하며, 실제 DB의 id(PK)는 변경되지 않음을 간접적으로 보장 (재조회 불가하므로 에러 반환
 *    확인에 집중)
 *
 * 프로세스:
 *
 * 1. 올바른 id, created_at로 게스트 생성
 * 2. Id만 다르게 세팅하여 PUT 요청 → 에러 발생 검증
 */
export async function test_api_prefix_member_my_actors_guests_test_attempt_update_guest_record_id_field_is_rejected(
  connection: api.IConnection,
) {
