 * - 여러 개의 스레드(thread)에 대해 여러 개의 게시물(post, reply 포함)을 생성합니다. 각 게시물은 body,
 *   is_edited 등 속성이 다르게 생성됩니다.
 * - Thread_id, body(부분일치), is_deleted 등의 필터링 옵션으로 검색 시 정확히 동작하는지 검증합니다.
 * - 페이지네이션 정보도 올바르게 반환되는지 확인합니다.
 *
 * 세부 검증:
 *
 * 1. Thread_id 별 분류 필터
 * 2. Body 내 substring 검색 필터
 * 3. Is_deleted=true/false 필터
 * 4. 페이지네이션 정보 채움 확인
 */
export async function test_api_threadsPosts_test_list_posts_with_various_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. 테스트 데이터: 두 개의 스레드를 생성합니다.
  const [threadA, threadB] = await Promise.all([
    api.functional.prefix.member.threadsPosts.threads.create(connection, {
      body: {
        discussionboard_category_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        title: "PaginationTest Thread A",
        status: "active",
        is_pinned: false,
        is_locked: false,
        archived: false,
        created_at: new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString(), // 어제
        updated_at: new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString(),
      } satisfies IDiscussionboardThreads.ICreate,
    }),
    api.functional.prefix.member.threadsPosts.threads.create(connection, {
      body: {
        discussionboard_category_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        title: "PaginationTest Thread B",
        status: "active",
        is_pinned: false,
        is_locked: false,
        archived: false,
        created_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
      } satisfies IDiscussionboardThreads.ICreate,
    }),
  ]);
  typia.assert(threadA);
  typia.assert(threadB);

  // 2. Thread A에 2개의 post, 하나는 reply(postA2에 답글) 포함 생성.
  const postA1 = await api.functional.prefix.member.threadsPosts.posts.create(
    connection,
    {
      body: {
        discussionboard_thread_id: threadA.id,
        body: "This is first post in Thread A - has keySearchWord",
        is_edited: false,
      } satisfies IDiscussionboardPosts.ICreate,
    },
  );
  typia.assert(postA1);

  const postA2 = await api.functional.prefix.member.threadsPosts.posts.create(
    connection,
    {
      body: {
        discussionboard_thread_id: threadA.id,
        body: "Second post in Thread A",
        is_edited: true,
      } satisfies IDiscussionboardPosts.ICreate,
    },
  );
  typia.assert(postA2);

  const replyA2 = await api.functional.prefix.member.threadsPosts.posts.create(
    connection,
    {
      body: {
        discussionboard_thread_id: threadA.id,
        parent_post_id: postA2.id,
        body: "Reply to second post",
        is_edited: false,
      } satisfies IDiscussionboardPosts.ICreate,
    },
  );
  typia.assert(replyA2);

  // 3. Thread B에 2개의 post 생성.
  const postB1 = await api.functional.prefix.member.threadsPosts.posts.create(
    connection,
    {
      body: {
        discussionboard_thread_id: threadB.id,
        body: "This is first post in Thread B",
        is_edited: true,
      } satisfies IDiscussionboardPosts.ICreate,
    },
  );
  typia.assert(postB1);

  const postB2 = await api.functional.prefix.member.threadsPosts.posts.create(
    connection,
    {
      body: {
        discussionboard_thread_id: threadB.id,
        body: "Second post in Thread B with keySearchWord",
        is_edited: false,
      } satisfies IDiscussionboardPosts.ICreate,
    },
  );
  typia.assert(postB2);

  // 4. 필터별 리스트 조회 및 검증
  // 4-1. thread_id별 필터(only ThreadA posts)
  const respThreadA = await api.functional.prefix.threadsPosts.posts.index(
    connection,
    {
      body: {
        discussionboard_thread_id: threadA.id,
      } satisfies IDiscussionboardPosts.IRequest,
    },
  );
  typia.assert(respThreadA);
  TestValidator.predicate("threadA만")(
    respThreadA.data.every(
      (post) => post.discussionboard_thread_id === threadA.id,
    ),
  );

  // 4-2. 본문 내 substring 포함 검색(keySearchWord)
  const respWithKeyword = await api.functional.prefix.threadsPosts.posts.index(
    connection,
    {
      body: {
        body: "keySearchWord",
      } satisfies IDiscussionboardPosts.IRequest,
    },
  );
  typia.assert(respWithKeyword);
  TestValidator.predicate("본문 키워드 포함")(
    respWithKeyword.data.every((post) => post.body.includes("keySearchWord")),
  );

  // 4-3. is_deleted=false로 검색 (생성시 모두 false로 생성되므로 결과 일관성만 체크)
  const respNotDeleted = await api.functional.prefix.threadsPosts.posts.index(
    connection,
    {
      body: {
        is_deleted: false,
      } satisfies IDiscussionboardPosts.IRequest,
    },
  );
  typia.assert(respNotDeleted);
  TestValidator.predicate("삭제=false만")(
    respNotDeleted.data.every((post) => post.is_deleted === false),
  );

  // 4-4. pagination 필드 존재 확인(실제 page/limit 파라미터는 없으나 pagination 결과 필드 체크)
  TestValidator.predicate("pagination 반환됨")(
    typeof respNotDeleted.pagination === "object",
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IDiscussionboardPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPosts";

/**
 * Test retrieval of discussionboard_post details by ID.
 *
 * This test ensures the /threadsPosts/posts/{id} endpoint correctly returns the
 * full details of a post when given a valid ID, and strictly matches the schema
 * fields.
 *
 * Steps:
 *
 * 1. Create a thread for associating test posts.
 * 2. Create a post in that thread.
 * 3. Retrieve the post by its ID and validate all fields, including strict schema
 *    match.
 * 4. Test retrieval error for a non-existent UUID (should yield 404 or API error).
 * 5. Test retrieval with a malformed UUID (should yield validation error).
 * 6. Create a post, simulate is_deleted=true, and ensure it is still retrievable
 *    (soft-deleted post).
 *
 * Covers both nominal and edge/error cases, per scenario requirements.
 */
export async function test_api_threadsPosts_test_get_post_details_success_and_not_found(
  connection: api.IConnection,
) {
  // 1. Create a thread for associating posts
  const threadCreateInput = {
    discussionboard_category_id: typia.random<string & tags.Format<"uuid">>(),
    title: "E2E Test Thread Title",
    status: "active",
    is_pinned: false,
    is_locked: false,
    archived: false,
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString(),
  } satisfies IDiscussionboardThreads.ICreate;
  const thread = await api.functional.prefix.member.threadsPosts.threads.create(
    connection,
    { body: threadCreateInput },
  );
  typia.assert(thread);

  // 2. Create a discussion post within the thread
  const bodyText = `Test post body ${typia.random<string>()}`;
  const postCreateInput = {
    discussionboard_thread_id: thread.id,
    body: bodyText,
    is_edited: false,
  } satisfies IDiscussionboardPosts.ICreate;
  const post = await api.functional.prefix.member.threadsPosts.posts.create(
    connection,
    { body: postCreateInput },
  );
  typia.assert(post);

  // 3. Retrieve the post by ID and validate all fields
  const fetched = await api.functional.prefix.threadsPosts.posts.at(
    connection,
    {
      id: post.id,
    },
  );
  typia.assert(fetched);
  TestValidator.equals("fetched.id matches")(fetched.id)(post.id);
  TestValidator.equals("fetched.thread_id matches")(
    fetched.discussionboard_thread_id,
  )(postCreateInput.discussionboard_thread_id);
  TestValidator.equals("fetched.body matches")(fetched.body)(
    postCreateInput.body,
  );
  TestValidator.equals("fetched.is_edited matches")(fetched.is_edited)(
    postCreateInput.is_edited,
  );
  TestValidator.equals("fetched.is_deleted matches")(fetched.is_deleted)(
    post.is_deleted,
  );
  TestValidator.equals("fetched.created_at matches")(fetched.created_at)(
    post.created_at,
  );
  TestValidator.equals("fetched.updated_at matches")(fetched.updated_at)(
    post.updated_at,
  );

  // Ensure no extraneous fields: keys must exactly match schema keys
  const expectedKeys = [
    "id",
    "discussionboard_thread_id",
    "discussionboard_member_id",
    "parent_post_id",
    "body",
    "is_edited",
    "is_deleted",
    "created_at",
    "updated_at",
  ];
  TestValidator.equals("response schema keys match")(
    Object.keys(fetched).sort(),
  )(expectedKeys.sort());

  // 4. Negative test: non-existent UUID
  const notFoundUuid = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("non-existent post yields error")(async () => {
    await api.functional.prefix.threadsPosts.posts.at(connection, {
      id: notFoundUuid,
    });
  });

  // 5. Malformed ID (not a UUID)
  await TestValidator.error("non-UUID id yields validation error")(async () => {
    await api.functional.prefix.threadsPosts.posts.at(connection, {
      id: "not-a-uuid" as any,
    });
  });

  // 6. Create post flagged is_deleted = true
  const deletedPostInput = {
    discussionboard_thread_id: thread.id,
    body: `deleted test body ${typia.random<string>()}`,
    is_edited: false,
  } satisfies IDiscussionboardPosts.ICreate;
  const deletedPost =
    await api.functional.prefix.member.threadsPosts.posts.create(connection, {
      body: deletedPostInput,
    });
  typia.assert(deletedPost);

  // For this test, simulate the is_deleted flag manually (since only mod may set in prod)
  // Here just check that returned is_deleted can be true and post is still retrievable
  // If not settable by API, check returned value
  // Test that fetching should still succeed
  const fetchedDeleted = await api.functional.prefix.threadsPosts.posts.at(
    connection,
    {
      id: deletedPost.id,
    },
  );
  typia.assert(fetchedDeleted);
  // Accept both true/false because we can't actually set is_deleted via API, check soft-deleted posts are retrievable
  TestValidator.equals("can fetch is_deleted=true or false post ID")(
    fetchedDeleted.id,
  )(deletedPost.id);
  TestValidator.predicate("is_deleted is boolean")(
    typeof fetchedDeleted.is_deleted === "boolean",
  );
}

