import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IDiscussionboardPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPosts";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";

/**
 * Validate that a discussion board member can update their own post's mutable
 * fields, and cannot update posts they do not own or immutable fields.
 *
 * This test covers the following business flows:
 *
 * 1. Member creation (the owner of the post)
 * 2. Thread creation for associating the post
 * 3. Post creation by the member
 * 4. Member updates their own post (happy path): edit 'body', 'is_edited',
 *    'updated_at', and confirm update is reflected in the returned object
 * 5. Attempt to update immutable fields (e.g. 'id', 'discussionboard_thread_id',
 *    'discussionboard_member_id', 'created_at', 'is_deleted'), or
 *    extra/out-of-schema fields, and verify API validation-level rejection
 *    (expect error)
 * 6. Create a second member, and attempt to update the original member's post as
 *    this new member: expect an authorization failure (not allowed to update
 *    others' posts)
 * 7. Attempt to update a non-existent post (random UUID): expect not found or
 *    error
 */
export async function test_api_threadsPosts_test_update_own_post_happy_path_and_authorization(
  connection: api.IConnection,
) {
  // 1. Create first member (owner)
  const memberId = typia.random<string & tags.Format<"uuid">>();
  const createdAt1 = new Date().toISOString() as string &
    tags.Format<"date-time">;
  const member = await api.functional.prefix.member.actors.members.create(
    connection,
    {
      body: {
        id: memberId,
        created_at: createdAt1,
      } satisfies IDiscussionboardMembers.ICreate,
    },
  );
  typia.assert(member);

  // 2. Create a thread
  const categoryId = typia.random<string & tags.Format<"uuid">>();
  const thread = await api.functional.prefix.member.threadsPosts.threads.create(
    connection,
    {
      body: {
        discussionboard_category_id: categoryId,
        title: "Sample Thread Title",
        status: "active",
        is_pinned: false,
        is_locked: false,
        archived: false,
        created_at: createdAt1,
        updated_at: createdAt1,
      } satisfies IDiscussionboardThreads.ICreate,
    },
  );
  typia.assert(thread);

  // 3. Create a post by member
  const post = await api.functional.prefix.member.threadsPosts.posts.create(
    connection,
    {
      body: {
        discussionboard_thread_id: thread.id,
        body: "Initial post body.",
        is_edited: false,
      } satisfies IDiscussionboardPosts.ICreate,
    },
  );
  typia.assert(post);

  // 4. Update own post (valid)
  const updateBody = {
    body: "Updated post body!",
    is_edited: true,
    updated_at: new Date(Date.now() + 60000).toISOString() as string &
      tags.Format<"date-time">,
  } satisfies IDiscussionboardPost.IUpdate;
  const updatedPost =
    await api.functional.prefix.member.my.threadsPosts.posts.update(
      connection,
      {
        id: post.id,
        body: updateBody,
      },
    );
  typia.assert(updatedPost);
  TestValidator.predicate("post is updated")(
    updatedPost.body === "Updated post body!" &&
      updatedPost.is_edited === true &&
      updatedPost.updated_at === updateBody.updated_at,
  );

  // 5. Attempt to update immutable or out-of-schema fields -- Should be rejected
  await TestValidator.error("should reject immutable field update async")(() =>
    api.functional.prefix.member.my.threadsPosts.posts.update(connection, {
      id: post.id,
      body: { id: typia.random<string & tags.Format<"uuid">>() } as any,
    }),
  );
  await TestValidator.error("should reject out-of-schema field async")(() =>
    api.functional.prefix.member.my.threadsPosts.posts.update(connection, {
      id: post.id,
      body: { random_field: "illegal!" } as any,
    }),
  );

  // 6. Create 2nd member; test unauthorized update attempt
  const memberId2 = typia.random<string & tags.Format<"uuid">>();
  const createdAt2 = new Date(Date.now() + 1000).toISOString() as string &
    tags.Format<"date-time">;
  const member2 = await api.functional.prefix.member.actors.members.create(
    connection,
    {
      body: {
        id: memberId2,
        created_at: createdAt2,
      } satisfies IDiscussionboardMembers.ICreate,
    },
  );
  typia.assert(member2);
  // (Assume context-swap to member2 is done via auth, but since we cannot change connection context, just attempt as is.)
  await TestValidator.error("not owner cannot update post")(() =>
    api.functional.prefix.member.my.threadsPosts.posts.update(connection, {
      id: post.id,
      body: {
        body: "Should not update!",
      } satisfies IDiscussionboardPost.IUpdate,
    }),
  );

  // 7. Attempt to update non-existent post id
  await TestValidator.error("update non-existent post")(() =>
    api.functional.prefix.member.my.threadsPosts.posts.update(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: { body: "Does not exist." } satisfies IDiscussionboardPost.IUpdate,
    }),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IDiscussionboardPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPosts";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";

/**
 * E2E test for soft-deleting one's own discussion board post and related error
 * edge cases.
 *
 * This test validates not only the soft delete (is_deleted) mechanism for
 * posts, but also confirms that error and permission boundaries are correctly
 * enforced:
 *
 * - Only the owner can soft-delete their post (access/ownership check)
 * - Double delete (idempotency) is allowed or returns an error as per business
 *   rule
 * - Attempt to delete a non-existent post id returns a suitable error
 *
 * Test procedure:
 *
 * 1. Register a primary member (as current user)
 * 2. Register a secondary member (for negative test)
 * 3. Create a thread belonging to the primary member (category random)
 * 4. Create a post in that thread, authored by the primary member
 * 5. Soft-delete the post and verify is_deleted=true and other integrity props
 * 6. Attempt to soft-delete as a non-owner (should fail)
 * 7. Attempt to soft-delete a non-existent post (should error)
 * 8. Attempt to soft-delete already deleted post (should be idempotent or error)
 */
export async function test_api_prefix_member_my_threadsPosts_posts_test_soft_delete_own_post_and_invalid_delete_cases(
  connection: api.IConnection,
) {
  // 1. Register the primary member (the default authenticated context)
  const memberId: string = typia.random<string & tags.Format<"uuid">>();
  const member: IDiscussionboardMembers =
    await api.functional.prefix.member.actors.members.create(connection, {
      body: {
        id: memberId,
        created_at: new Date().toISOString(),
      } satisfies IDiscussionboardMembers.ICreate,
    });
  typia.assert(member);
  TestValidator.equals("member id matches")(member.id)(memberId);

  // 2. Register a secondary member (to test non-owner access error)
  const otherMemberId: string = typia.random<string & tags.Format<"uuid">>();
  const otherMember: IDiscussionboardMembers =
    await api.functional.prefix.member.actors.members.create(connection, {
      body: {
        id: otherMemberId,
        created_at: new Date().toISOString(),
      } satisfies IDiscussionboardMembers.ICreate,
    });
  typia.assert(otherMember);

  // 3. Create a thread by the (primary) member
  const threadCategoryId: string = typia.random<string & tags.Format<"uuid">>();
  const threadTitle: string = `테스트 스레드 ${RandomGenerator.alphaNumeric(6)}`;
  const now = new Date().toISOString();
  const thread: IDiscussionboardThreads =
    await api.functional.prefix.member.threadsPosts.threads.create(connection, {
      body: {
        discussionboard_category_id: threadCategoryId,
        title: threadTitle,
        status: "active",
        is_pinned: false,
        is_locked: false,
        archived: false,
        created_at: now,
        updated_at: now,
      } satisfies IDiscussionboardThreads.ICreate,
    });
  typia.assert(thread);
  TestValidator.equals("thread title")(thread.title)(threadTitle);

  // 4. Create a post in the thread, owned by the primary member
  const postBody: string = `본문 내용 ${RandomGenerator.alphaNumeric(8)}`;
  const post: IDiscussionboardPosts =
    await api.functional.prefix.member.threadsPosts.posts.create(connection, {
      body: {
        discussionboard_thread_id: thread.id,
        body: postBody,
        is_edited: false,
      } satisfies IDiscussionboardPosts.ICreate,
    });
  typia.assert(post);
  TestValidator.equals("thread id for post")(post.discussionboard_thread_id)(
    thread.id,
  );
  TestValidator.equals("post is not deleted initially")(post.is_deleted)(false);

  // 5. Soft-delete the post (should set is_deleted=true, but not remove the row)
  const erased: IDiscussionboardPost =
    await api.functional.prefix.member.my.threadsPosts.posts.erase(connection, {
      id: post.id,
    });
  typia.assert(erased);
  TestValidator.equals("erased post id matches")(erased.id)(post.id);
  TestValidator.equals("is_deleted set true")(erased.is_deleted)(true);
  TestValidator.equals("ownership")(erased.discussionboard_member_id)(
    post.discussionboard_member_id,
  );

  // 6. Attempt to delete a post as another member (should fail):
  //    Simulate member switch - (assume API context requires this; otherwise, real tests would need session/user token switch)
  //    We'll simulate by making the call as if the other member was authenticated context
  connection.headers = {
    ...connection.headers,
    "X-Discussionboard-Member-Id": otherMember.id,
  };
  await TestValidator.error("access forbidden when non-owner tries to delete")(
    async () => {
      await api.functional.prefix.member.my.threadsPosts.posts.erase(
        connection,
        { id: post.id },
      );
    },
  );
  // Restore connection to primary member
  connection.headers = {
    ...connection.headers,
    "X-Discussionboard-Member-Id": member.id,
  };

  // 7. Attempt to soft-delete a non-existent post (random UUID)
  await TestValidator.error("nonexistent post delete gives not found")(
    async () => {
      await api.functional.prefix.member.my.threadsPosts.posts.erase(
        connection,
        { id: typia.random<string & tags.Format<"uuid">>() },
      );
    },
  );

  // 8. Attempt to soft-delete an already deleted post (should be idempotent or possibly error)
  await TestValidator.predicate("repeat delete is idempotent or gives error")(
    true,
    // The call below should be allowed or produce a controlled error per spec
    // If not idempotent, adjust the assertion to TestValidator.error(...)
    // For true idempotency: run and assert output.is_deleted === true as above; for error, use .error()
  );
  try {
    const reErased: IDiscussionboardPost =
      await api.functional.prefix.member.my.threadsPosts.posts.erase(
        connection,
        { id: post.id },
      );
    typia.assert(reErased);
    TestValidator.equals("repeat delete still returns is_deleted true")(
      reErased.is_deleted,
    )(true);
  } catch (err) {
    // If spec is strict, may throw error for double delete; still pass test here
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IPageIDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardThreads";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 토론 스레드 리스트의 카테고리 필터 및 페이지네이션 정상 동작을 검증합니다.
 *
 * 1. 두 개 이상의 서로 다른 discussionboard_category_id(카테고리) 값을 가진 스레드를 각각 생성합니다.
 * 2. 임의의 한 카테고리 discussionboard_category_id만을 조건으로, 목록(list) 엔드포인트에 페이지네이션 정보(예:
 *    limit, current)와 함께 요청을 보냅니다.
 * 3. 응답 data에는 해당 카테고리에 속하는 스레드만 포함되어야 하며, 다른 카테고리의 스레드는 어떤 경우에도 리턴 결과에 포함되어선 안
 *    됩니다.
 * 4. 응답의 pagination 정보(current, limit, pages, records) 역시 정상적으로 반환되는지 체크합니다.
 *
 * 모두 성공한다면, 카테고리 필터 및 페이징 컨트롤이 정상적으로 작동함을 의미합니다.
 */
export async function test_api_threadsPosts_test_list_threads_with_pagination_and_category_filter(
  connection: api.IConnection,
) {
  // 1. 테스트 준비: 두 개의 서로 다른 카테고리에 각각 하나씩 스레드를 생성합니다.
  const categoryA = typia.random<string & tags.Format<"uuid">>();
  const categoryB = typia.random<string & tags.Format<"uuid">>();
  const now = new Date().toISOString();

  // 카테고리A 스레드 생성
  const threadA =
    await api.functional.prefix.member.threadsPosts.threads.create(connection, {
      body: {
        discussionboard_category_id: categoryA,
        title: RandomGenerator.paragraph()(8),
        status: "active",
        is_pinned: false,
        is_locked: false,
        archived: false,
        created_at: now,
        updated_at: now,
      } satisfies IDiscussionboardThreads.ICreate,
    });
  typia.assert(threadA);

  // 카테고리B 스레드 생성
  const threadB =
    await api.functional.prefix.member.threadsPosts.threads.create(connection, {
      body: {
        discussionboard_category_id: categoryB,
        title: RandomGenerator.paragraph()(8),
        status: "active",
        is_pinned: false,
        is_locked: false,
        archived: false,
        created_at: now,
        updated_at: now,
      } satisfies IDiscussionboardThreads.ICreate,
    });
  typia.assert(threadB);

  // 2. 카테고리A만 필터로 주고 페이지네이션 요청(예: limit=5, current=1)
  const list = await api.functional.prefix.threadsPosts.threads.index(
    connection,
    {
      body: {
        discussionboard_category_id: categoryA,
        status: "active",
      } satisfies IDiscussionboardThreads.IRequest,
    },
  );
  typia.assert(list);

  // 3. 결과: 반환된 데이터가 카테고리A 스레드만 포함하는지, pagination 필드가 정상값인지 점검
  TestValidator.predicate("data only has threads from categoryA")(
    list.data.every((t) => t.discussionboard_category_id === categoryA),
  );
  TestValidator.predicate("threadA는 반드시 존재해야 한다")(
    list.data.some((t) => t.id === threadA.id),
  );
  TestValidator.predicate("threadB는 포함되지 않는다")(
    list.data.every((t) => t.id !== threadB.id),
  );
  TestValidator.equals("pagination 타입 체크")(typeof list.pagination.current)(
    "number",
  );
  TestValidator.equals("pagination limit 타입 체크")(
    typeof list.pagination.limit,
  )("number");
  TestValidator.equals("반환 데이터 limit은 기본값 10 또는 1 이상")(
    list.pagination.limit >= 1,
  )(true);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IPageIDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardThreads";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 토론 스레드를 제목 키워드로 검색하는 기능 검증
 *
 * 이 테스트는 사용자가 입력한 고유 키워드를 포함한 제목으로 스레드를 생성한 후, 해당 키워드로 검색 옵션을 적용하여 목록을 페이징 조회했을
 * 때:
 *
 * 1. 생성한 스레드가 반드시 포함되어야 하며,
 * 2. 관련 없는 스레드는 포함되지 않아야 하며,
 * 3. 페이지네이션 정보(페이지 번호, 한 페이지당 개수, 전체 개수, 전체 페이지)가 정상적으로 포함되어야 함을 검증한다.
 *
 * 단계별 테스트 흐름:
 *
 * 1. 식별 가능한(충분히 희귀한) 키워드로 Thread 제목을 지정하여 스레드 생성(POST)
 * 2. 동일한 카테고리 또는 다른 카테고리에 연관 없는(키워드 없는) 스레드 1~2개를 추가 생성(잡음 데이터)
 * 3. PATCH /prefix//threadsPosts/threads API를 통해 body.title에 키워드 세팅 후 페이징 검색
 *
 *    - 반환 데이터(data 배열) 내에 1번에서 생성한 스레드가 반드시 등장
 *    - 잡음 데이터(키워드가 제목에 미포함된 타 스레드)는 등장하지 않아야 함(TestValidator 활용)
 *    - Pagination 오브젝트도 정상 반환되어야 함
 */
export async function test_api_threadsPosts_test_search_threads_by_title_keyword(
  connection: api.IConnection,
) {
  // 1. 고유 키워드 지정
  const uniqueKeyword = `keyword_${RandomGenerator.alphaNumeric(10)}`;

  // 2. 스레드 생성(검색 키워드 포함 제목)
  const categoryId = typia.random<string & tags.Format<"uuid">>();
  const createdThread =
    await api.functional.prefix.member.threadsPosts.threads.create(connection, {
      body: {
        discussionboard_category_id: categoryId,
        title: `테스트 스레드 ${uniqueKeyword}`,
        status: "active",
        is_pinned: false,
        is_locked: false,
        archived: false,
        created_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
      } satisfies IDiscussionboardThreads.ICreate,
    });
  typia.assert(createdThread);

  // 3. 잡음 데이터 1~2건 생성(키워드 미포함)
  const noiseThreads = await ArrayUtil.asyncRepeat(2)(async () => {
    return await api.functional.prefix.member.threadsPosts.threads.create(
      connection,
      {
        body: {
          discussionboard_category_id: categoryId,
          title: RandomGenerator.paragraph()(1),
          status: "active",
          is_pinned: false,
          is_locked: false,
          archived: false,
          created_at: new Date().toISOString(),
          updated_at: new Date().toISOString(),
        } satisfies IDiscussionboardThreads.ICreate,
      },
    );
  });
  noiseThreads.forEach((thread) => typia.assert(thread));

  // 4. 키워드로 검색
  const page = await api.functional.prefix.threadsPosts.threads.index(
    connection,
    {
      body: {
        title: uniqueKeyword,
      },
    },
  );
  typia.assert(page);

  // 5. 결과 검증: 1) 키워드 포함 스레드만 등장 2) 잡음 데이터 없음 3) 페이지네이션 객체 정상
  TestValidator.predicate("리스트 내에 생성한 스레드가 반드시 포함됨")(
    page.data.some((t) => t.id === createdThread.id),
  );
  noiseThreads.forEach((noise) => {
    TestValidator.predicate("잡음 스레드는 등장 X")(
      !page.data.some((t) => t.id === noise.id),
    );
  });
  TestValidator.equals("pagination에 필수 필드 존재 확인")(
    Object.keys(page.pagination).sort(),
  )(["current", "limit", "pages", "records"].sort());
}

