 *
 * 이 테스트는 인증된 회원이 직접 자신의 토론 스레드를 생성한 뒤, 해당 스레드의 mutable 필드(예: title, status 등)를
 * update API를 통해 변경한 후, 변경사항이 정상적으로 반영되는지 검증합니다.
 *
 * [테스트 시나리오]
 *
 * 1. 인증된 사용자 계정으로 토론 스레드를 생성한다
 * 2. 생성된 스레드의 id로 update API를 호출하여 title과 status를 수정한다
 * 3. 응답 데이터에서 새 값이 반영되었는지, 소유권 및 식별자(id) 등 불변필드는 유지됐는지 확인한다
 */
export async function test_api_discussionboard_threads_test_update_own_thread_success(
  connection: api.IConnection,
) {
  // 1. 인증된 회원 계정으로 토론 스레드를 생성한다.
  const now = new Date().toISOString();
  const createBody: IDiscussionboardThreads.ICreate = {
    discussionboard_category_id: typia.random<string & tags.Format<"uuid">>(),
    title: "원본 타이틀",
    status: "active",
    is_pinned: false,
    is_locked: false,
    archived: false,
    created_at: now,
    updated_at: now,
  };
  const thread = await api.functional.prefix.member.threadsPosts.threads.create(
    connection,
    { body: createBody },
  );
  typia.assert(thread);

  // 2. 해당 스레드의 id로 update API를 사용해 title, status를 수정한다.
  const updateBody: IDiscussionboardThreads.IUpdate = {
    title: "수정된 타이틀",
    status: "archived",
    updated_at: new Date().toISOString(),
  };
  const updated =
    await api.functional.prefix.member.my.threadsPosts.threads.update(
      connection,
      {
        id: thread.id,
        body: updateBody,
      },
    );
  typia.assert(updated);

  // 3. 응답에서 변동 사항과 불변 값(식별자, 소유자 UUID 등)을 확인한다.
  TestValidator.equals("수정된 타이틀 반영됨")(updated.title)(updateBody.title);
  TestValidator.equals("수정된 상태 반영됨")(updated.status)(updateBody.status);
  TestValidator.equals("ID 불변성 유지")(updated.id)(thread.id);
  TestValidator.equals("작성자(회원) 불변")(updated.discussionboard_member_id)(
    thread.discussionboard_member_id,
  );
}

