    is_pinned: false,
    is_locked: false,
    archived: false,
    created_at: now,
    updated_at: now,
  } satisfies IDiscussionboardThreads.ICreate;

  const thread = await api.functional.prefix.member.threadsPosts.threads.create(
    connection,
    { body: createInput },
  );
  typia.assert(thread);
  TestValidator.equals("archived: 최초 false")(thread.archived)(false);

  // 2. 본인 소유 스레드 soft delete(archive)
  await api.functional.prefix.member.my.threadsPosts.threads.erase(connection, {
    id: thread.id,
  });
  // 별도 검증 로직은 제공되는 조회 API 미존재로 skip
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";

/**
 * Validate that soft deletion (archiving) of a thread not owned by the
 * authenticated user is forbidden.
 *
 * Business context: This test attempts to delete (archive) a thread using a
 * UUID that is not owned by the currently authenticated user (or a
 * random/nonexistent UUID), to ensure the system enforces business logic
 * preventing deletion of threads users do not own. Per scenario description,
 * the expected behavior is either a forbidden error (user cannot modify another
 * user's data) or a not found error (thread does not exist or is not
 * accessible).
 *
 * Limitations: Due to lack of API support for user registration, login, and
 * thread creation, this test can only simulate the deletion attempt with a
 * random UUID, and cannot control or verify actual user/thread state.
 *
 * Steps:
 *
 * 1. Attempt to delete (archive) a thread using a random UUID.
