/**
 * 인증 세션 ID로 단일 인증 세션 정보를 조회하여 반환 필드 스키마 일치 여부 검증.
 *
 * 테스트 흐름:
 *
 * 1. IDiscussionboardAuthSessions.ICreate 입력으로 세션을 생성하여 id를 획득
 * 2. 해당 id로 인증 세션 단건 조회 수행
 * 3. 조회 결과 모든 필드가 생성값과 일치하는지 확인 및 스키마 일치성/존재성 체크
 *
 * 주요 검증 항목:
 *
 * - 필수: id, actor_type, actor_id, issued_at, expires_at, ip_address, user_agent
 * - 선택(last_activity_at, revoked_at): null 또는 string, 존재성/type만 검증
 */
export async function test_api_prefix_auth_sessions_test_get_auth_session_by_id_with_valid_id(
  connection: api.IConnection,
) {
  // 1. 인증 세션 생성
  const input: IDiscussionboardAuthSessions.ICreate = {
    actor_type: RandomGenerator.alphabets(8),
    actor_id: typia.random<string & tags.Format<"uuid">>(),
    issued_at: new Date().toISOString(),
    expires_at: new Date(Date.now() + 1000 * 60 * 60).toISOString(), // 1시간 후 만료
    ip_address: RandomGenerator.alphaNumeric(10),
    user_agent: RandomGenerator.alphabets(6),
  };
  const created = await api.functional.prefix.auth.sessions.create(connection, {
    body: input,
  });
  typia.assert(created);

  // 2. 반환된 id로 단일 인증 세션 조회
  const found = await api.functional.prefix.auth.sessions.at(connection, {
    id: created.id,
  });
  typia.assert(found);

  // 3. 반환 필드 검증
  TestValidator.equals("id")(found.id)(created.id);
  TestValidator.equals("actor_type")(found.actor_type)(input.actor_type);
  TestValidator.equals("actor_id")(found.actor_id)(input.actor_id);
  TestValidator.equals("issued_at")(found.issued_at)(input.issued_at);
  TestValidator.equals("expires_at")(found.expires_at)(input.expires_at);
  TestValidator.equals("ip_address")(found.ip_address)(input.ip_address);
  TestValidator.equals("user_agent")(found.user_agent)(input.user_agent);

  // 선택 필드: 타입/존재성만 검증
  if ("last_activity_at" in found)
    TestValidator.predicate("last_activity_at 타입 또는 null")(
      typeof found.last_activity_at === "string" ||
        found.last_activity_at === null ||
        typeof found.last_activity_at === "undefined",
    );
  if ("revoked_at" in found)
    TestValidator.predicate("revoked_at 타입 또는 null")(
      typeof found.revoked_at === "string" ||
        found.revoked_at === null ||
        typeof found.revoked_at === "undefined",
    );
}

