import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardAuthSessions } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardAuthSessions";

/**
 * Validate permanent deletion (hard delete) of a member's own authentication
 * session by ID.
 *
 * This test ensures that a member can delete their own authentication session
 * via ID and that:
 *
 * - The session is permanently removed from the database (no soft-delete or
 *   deleted flag)
 * - The session cannot be deleted (or acted upon) again
 *
 * Steps:
 *
 * 1. Create a new authentication session (acting as a member)
 * 2. Delete the session by ID, authenticated as the owner
 * 3. Attempt to delete the same session again and confirm an error is thrown
 *    (ensuring idempotency and absence)
 *
 * Note: No retrieval endpoint exists in the provided SDK, so direct existence
 * check is not possible. In production, database or privileged admin checks
 * would be used for full verification.
 */
export async function test_api_member_test_hard_delete_own_auth_session(
  connection: api.IConnection,
) {
  // 1. Create a new authentication session for a member
  const now = new Date();
  const session = await api.functional.prefix.auth.sessions.create(connection, {
    body: {
      actor_type: "member",
      actor_id: typia.random<string & tags.Format<"uuid">>(),
      issued_at: now.toISOString(),
      expires_at: new Date(now.getTime() + 60 * 60 * 1000).toISOString(), // Expires in 1h
      ip_address: "127.0.0.1",
      user_agent: "jest-e2e-testing",
    } satisfies IDiscussionboardAuthSessions.ICreate,
  });
  typia.assert(session);

  // 2. Permanently delete (hard delete) the session by ID
  await api.functional.prefix.member.my.auth.sessions.erase(connection, {
    id: session.id,
  });

  // 3. Attempting to delete again should fail (session already gone)
  await TestValidator.error("cannot delete already removed session")(() =>
    api.functional.prefix.member.my.auth.sessions.erase(connection, {
      id: session.id,
    }),
  );
}

