import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPoll } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoll";
import type { IPollVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IPollVote";

/**
 * 관리자(Admin) 권한으로 poll vote(투표 기록) 상세 조회 API (GET
 * /prefix/admin//pollVotes/{id})의 정상 동작 및 오류 핸들링 검증
 *
 * - 관리자는 모든 poll vote의 상세 정보를 감사/모니터링 목적으로 조회할 수 있다.
 * - 응답에는 schema에 정의된 모든 필드(id, discussionboard_poll_id, voting_member_id,
 *   selected_option, created_at)가 정확히 포함되어야 한다.
 * - 잘못된 id, 존재하지 않는 id, 잘못된 권한에 대해 적절한 오류가 발생해야 한다.
 *
 * **비즈니스 시나리오**
 *
 * 1. 사전 데이터 생성 (member 권한): (1) poll 생성, (2) poll에 투표해서 vote 데이터 생성
 * 2. 관리자 권한으로 poll vote를 id로 상세 조회 (정상)
 * 3. 존재하지 않는 uuid, 잘못된 uuid 형식(id)으로 상세 조회 시 오류 발생 확인
 * 4. (선택) 일반 member 권한 계정에서 admin 전용 상세조회 API 접근 시 권한 오류 발생 확인 (미지원 시 생략)
 */
export async function test_api_pollVotes_test_get_poll_vote_detail_as_admin_with_success_and_error_handling(
  connection: api.IConnection,
) {
  // 1. Poll 생성 (member 권한 API)
  const poll = await api.functional.prefix.member.polls.create(connection, {
    body: {
      discussionboard_thread_id: typia.random<string & tags.Format<"uuid">>(),
      prompt: "테스트 투표 질문: 선호하는 옵션은?",
      allow_multiple_choices: false,
      is_anonymous: false,
      expires_at: undefined,
    } satisfies IPoll.ICreate,
  });
  typia.assert(poll);

  // 2. Poll에 투표하여 poll vote 데이터 생성 (member 권한 API)
  // selected_option은 예시값 "optionA" 사용
  const pollVote = await api.functional.prefix.member.pollVotes.create(
    connection,
    {
      body: {
        discussionboard_poll_id: poll.id,
        selected_option: "optionA",
      },
    },
  );
  typia.assert(pollVote);

  // 3. 관리자 권한 세션 (별도 login API 미제공 시 connection 유지)
  // (추후 관리자 인증/토큰 필요 시 연결)

  // 4. 정상적인 id로 상세 조회 (admin 권한 API)
  const byAdmin = await api.functional.prefix.admin.pollVotes.at(connection, {
    id: pollVote.id,
  });
  typia.assert(byAdmin);
  // 조회된 값이 pollVote 객체와 일치하는 필드값을 반환하는지 검사
  TestValidator.equals("id 일치")(byAdmin.id)(pollVote.id);
  TestValidator.equals("poll id 일치")(byAdmin.discussionboard_poll_id)(
    poll.id,
  );
  TestValidator.equals("selected_option 일치")(byAdmin.selected_option)(
    "optionA",
  );
  TestValidator.equals("voting_member_id")(byAdmin.voting_member_id)(
    pollVote.voting_member_id,
  );
  TestValidator.equals("created_at 존재 여부")(
    typeof byAdmin.created_at === "string",
  )(true);

  // 5. 존재하지 않는 uuid로 상세 조회 요청 - 오류 검증
  await TestValidator.error(
    "존재하지 않는 uuid로 상세 조회 시 404 또는 적절한 오류",
  )(async () => {
    await api.functional.prefix.admin.pollVotes.at(connection, {
      id: typia.random<string & tags.Format<"uuid">>(), // 충돌 방지용 랜덤 uuid 사용
    });
  });

  // 6. 유효하지 않은 id (uuid 형식 아님)로 상세 조회 시 오류 검증
