/**
 * E2E test for creating a poll vote as an authenticated member, verifying
 * business and schema rules, error conditions, and proper authentication.
 *
 * Validates the poll voting workflow and error scenarios:
 *
 * 1. Create an active poll (dependency)
 * 2. Vote on the poll as authenticated member (success)
 * 3. Attempt to vote again (duplicate error)
 * 4. Vote on an expired poll (error)
 * 5. Vote on a nonexistent poll (error)
 * 6. Vote with invalid option (error)
 * 7. Attempt vote while unauthenticated (error)
 *
 * Due to API/DTO limitations, poll options are assumed as open input; in
 * production, these would be managed via additional domain/model logic.
 */
export async function test_api_prefix_member_pollvotes_test_create_poll_vote_with_valid_and_invalid_conditions(
  connection: api.IConnection,
) {
  // 1. Create active poll as dependency
  const pollCreateInput: IPoll.ICreate = {
    discussionboard_thread_id: typia.random<string & tags.Format<"uuid">>(),
    prompt: "Sample prompt for poll",
    allow_multiple_choices: false,
    is_anonymous: false,
    expires_at: new Date(Date.now() + 86400000).toISOString(), // expires in 1 day
  };
  const poll = await api.functional.prefix.member.polls.create(connection, {
    body: pollCreateInput,
  });
  typia.assert(poll);

  // 2. Vote on the poll (success)
  const selected_option = "Option A";
  const voteInput = {
    discussionboard_poll_id: poll.id,
    selected_option,
  } satisfies IPollVote.ICreate;
  const vote = await api.functional.prefix.member.pollVotes.create(connection, {
    body: voteInput,
  });
  typia.assert(vote);
  TestValidator.equals("poll id matches")(vote.discussionboard_poll_id)(
    poll.id,
  );
  TestValidator.equals("selected_option matches")(vote.selected_option)(
    selected_option,
  );

  // 3. Attempt duplicate vote (should fail)
  await TestValidator.error("duplicate vote fails")(async () => {
    await api.functional.prefix.member.pollVotes.create(connection, {
      body: voteInput,
    });
  });

  // 4. Create a closed poll (expires in past)
  const closedPollInput: IPoll.ICreate = {
    ...pollCreateInput,
    prompt: "Closed poll for error test",
    expires_at: new Date(Date.now() - 3600000).toISOString(), // expired 1h ago
  };
  const closedPoll = await api.functional.prefix.member.polls.create(
    connection,
    {
      body: closedPollInput,
    },
  );
  typia.assert(closedPoll);
  await TestValidator.error("vote fails on closed/expired poll")(async () => {
    await api.functional.prefix.member.pollVotes.create(connection, {
      body: {
        discussionboard_poll_id: closedPoll.id,
        selected_option,
      } satisfies IPollVote.ICreate,
    });
  });

  // 5. Attempt to vote on a random invalid poll id
  await TestValidator.error("vote fails for nonexistent poll id")(async () => {
    await api.functional.prefix.member.pollVotes.create(connection, {
      body: {
        discussionboard_poll_id: typia.random<string & tags.Format<"uuid">>(),
        selected_option,
      } satisfies IPollVote.ICreate,
    });
  });

  // 6. Attempt to vote with invalid option
  await TestValidator.error("invalid selected_option fails")(async () => {
    await api.functional.prefix.member.pollVotes.create(connection, {
      body: {
        discussionboard_poll_id: poll.id,
        selected_option: "INVALID_OPTION_DOES_NOT_EXIST",
      } satisfies IPollVote.ICreate,
    });
  });

  // 7. Attempt unauthenticated vote (simulate by omitting Authorization header)
  const headers = { ...(connection.headers ?? {}) };
  // Remove Authorization if present
  if ("Authorization" in headers) delete headers.Authorization;
  const unauthConnection: api.IConnection = {
    ...connection,
    headers,
  };
  await TestValidator.error("unauthenticated vote fails")(async () => {
    await api.functional.prefix.member.pollVotes.create(unauthConnection, {
      body: voteInput,
    });
  });
}

