import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPosts";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { IPostEditLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPostEditLog";
import type { IPageIPostEditLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPostEditLog";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test retrieving a filtered and paginated list of post edit logs as a member.
 *
 * Validates that the post edit log listing endpoint supports filtering by
 * edit_member_id, creation time window, and post id, and that multiple edits
 * across several posts can be reliably queried and paginated. Ensures that the
 * entries returned match the applied filters and pagination expectations, and
 * checks edge cases such as empty results.
 *
 * Step-by-step process:
 *
 * 1. Create two posts to work with.
 * 2. Edit both posts several times to generate edit log entries.
 * 3. Extract the member's id for filter testing.
 * 4. Query all logs; check at least as many entries as edits performed.
 * 5. Query logs filtered by edit_member_id; ensure all returned entries match.
 * 6. Query logs using created_at from/to (time range); validate returned logs are
 *    within that window.
 * 7. Query logs for a specific post id and assert only those post logs appear.
 * 8. Simulate pagination logic by checking that a sliced subset corresponds to a
 *    lower limit.
 * 9. Query using an invalid post id to confirm empty page result.
 */
export async function test_api_prefix_member_threadsPosts_postEditLogs_test_list_post_edit_logs_with_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create two posts for testing
  const discussionboard_thread_id = typia.random<
    string & tags.Format<"uuid">
  >();

  const post1 = await api.functional.prefix.member.threadsPosts.posts.create(
    connection,
    {
      body: {
        discussionboard_thread_id,
        body: "Initial post content 1",
      } satisfies IDiscussionboardPosts.ICreate,
    },
  );
  typia.assert(post1);

  const post2 = await api.functional.prefix.member.threadsPosts.posts.create(
    connection,
    {
      body: {
        discussionboard_thread_id,
        body: "Initial post content 2",
      } satisfies IDiscussionboardPosts.ICreate,
    },
  );
  typia.assert(post2);

  // 2. Edit both posts multiple times
  const now = new Date();
  const edits: {
    post: typeof post1;
    updated_at: string;
    discussionboard_post_id: string;
  }[] = [];
  for (let i = 0; i < 3; ++i) {
    const updated_at1 = new Date(now.getTime() + 1000 * (i + 1)).toISOString();
    const edit1 =
      await api.functional.prefix.member.my.threadsPosts.posts.update(
        connection,
        {
          id: post1.id,
          body: {
            body: `Edited content 1 - ${i}`,
            is_edited: true,
            updated_at: updated_at1,
          } satisfies IDiscussionboardPost.IUpdate,
        },
      );
    typia.assert(edit1);
    edits.push({
      post: post1,
      updated_at: updated_at1,
      discussionboard_post_id: post1.id,
    });

    const updated_at2 = new Date(
      now.getTime() + 10000 + 1000 * (i + 1),
    ).toISOString();
    const edit2 =
      await api.functional.prefix.member.my.threadsPosts.posts.update(
        connection,
        {
          id: post2.id,
          body: {
            body: `Edited content 2 - ${i}`,
            is_edited: true,
            updated_at: updated_at2,
          } satisfies IDiscussionboardPost.IUpdate,
        },
      );
    typia.assert(edit2);
    edits.push({
      post: post2,
      updated_at: updated_at2,
      discussionboard_post_id: post2.id,
    });
  }

  // 3. Get own member id (from created posts)
  const edit_member_id = post1.discussionboard_member_id;

  // 4. Query all logs
  let logs = await api.functional.prefix.member.threadsPosts.postEditLogs.index(
    connection,
    { body: {} },
  );
  typia.assert(logs);
  TestValidator.predicate("should return at least as many as we edited")(
    logs.data.length >= edits.length,
  );

  // 5. Query by edit_member_id
  logs = await api.functional.prefix.member.threadsPosts.postEditLogs.index(
    connection,
    { body: { edit_member_id } },
  );
  typia.assert(logs);
  for (const log of logs.data) {
    TestValidator.equals("edit_member_id matches")(log.edit_member_id)(
      edit_member_id,
    );
  }

  // 6. Query by created_at time window
  const firstEditTime = edits[0].updated_at;
  const lastEditTime = edits[edits.length - 1].updated_at;
  logs = await api.functional.prefix.member.threadsPosts.postEditLogs.index(
    connection,
    {
      body: {
        created_at_from: firstEditTime,
        created_at_to: lastEditTime,
        edit_member_id,
      },
    },
  );
  typia.assert(logs);
  for (const log of logs.data) {
    TestValidator.predicate("within time window")(
      log.created_at >= firstEditTime && log.created_at <= lastEditTime,
    );
    TestValidator.equals("edit_member_id matches")(log.edit_member_id)(
      edit_member_id,
    );
  }

  // 7. Query for a specific post's logs only
  logs = await api.functional.prefix.member.threadsPosts.postEditLogs.index(
    connection,
    {
      body: {
        discussionboard_post_id: post2.id,
      },
    },
  );
  typia.assert(logs);
  for (const log of logs.data) {
    TestValidator.equals("post id matches")(log.discussionboard_post_id)(
      post2.id,
    );
  }

  // 8. Simulate pagination: restrict view to 'limit' results (API doesn't support limit param, so simulate logic)
  const limit = 2;
  logs = await api.functional.prefix.member.threadsPosts.postEditLogs.index(
    connection,
    { body: { edit_member_id } },
  );
  typia.assert(logs);
  if (logs.data.length > limit) {
    const pagedLogs = logs.data.slice(0, limit);
    TestValidator.equals("paged count matches")(pagedLogs.length)(limit);
  }

  // 9. Query with non-existent post id
  logs = await api.functional.prefix.member.threadsPosts.postEditLogs.index(
    connection,
    {
      body: {
        discussionboard_post_id: typia.random<string & tags.Format<"uuid">>(),
      },
    },
  );
  typia.assert(logs);
  TestValidator.equals("empty result for non-existent id")(logs.data.length)(0);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPostEditLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPostEditLog";
import type { IPageIPostEditLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPostEditLog";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 존재하지 않는 필터(edit_member_id) 조건으로 post edit log를 조회하면 빈 결과가 반환되는지 검증
 *
 * - Moderation 및 감사/감시 시스템에서 필터 조합으로 데이터가 없을 때, '200 OK' 및 '빈 결과'가 정상 동작함을 검증합니다.
 * - 비정상 ID(랜덤 UUID)로 edit_member_id를 지정하여 호출
 *
 * [Test Steps]
 *
 * 1. 임의 UUID(edit_member_id)로 post edit log list 조회 요청
 * 2. 성공(http 200) 응답 및 빈 data 배열임을 검증
 * 3. Pagination 필드 구조도 정상인지 추가 체크
 */
export async function test_api_prefix_member_threadsPosts_postEditLogs_index_empty_result(
  connection: api.IConnection,
) {
  // 1. 완전히 임의의 UUID로 존재하지 않는 edit_member_id 필터 생성
  const filter = {
    edit_member_id: typia.random<string & tags.Format<"uuid">>(),
  } satisfies IPostEditLog.IRequest;

  // 2. 필터를 사용하여 post edit log 조회
  const result =
    await api.functional.prefix.member.threadsPosts.postEditLogs.index(
      connection,
      { body: filter },
    );
  typia.assert(result);

  // 3. 결과는 빈 배열이어야 하며, pagination 필드는 모두 number 타입
  TestValidator.equals("빈 결과 배열이어야 함")(result.data.length)(0);
  TestValidator.equals("pagination current 타입")(
    typeof result.pagination.current,
  )("number");
  TestValidator.equals("pagination limit 타입")(typeof result.pagination.limit)(
    "number",
  );
  TestValidator.equals("pagination records 타입")(
    typeof result.pagination.records,
  )("number");
  TestValidator.equals("pagination pages 타입")(typeof result.pagination.pages)(
    "number",
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPosts";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { IPostEditLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPostEditLog";
import type { IPageIPostEditLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPostEditLog";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate that a moderator can list post edit logs with search and pagination.
 *
 * Moderators need to audit editing activity within the discussion board. This
 * test ensures that post edit logs can be searched and paginated with various
 * filters, and the result set matches the search criteria. The moderator role's
 * permissions must be enforced: only authenticated moderators can access this
 * endpoint.
 *
 * Steps:
 *
 * 1. Create several posts in a thread as a member.
 * 2. Edit a subset of those posts individually (by the member) to generate edit
 *    logs for them.
 * 3. Switch to moderator role/login session (not explicitly modeled in API,
 *    assumed to be handled as part of the connection context or test harness).
 * 4. As moderator, call the postEditLogs index (PATCH) endpoint with:
 *
 *    - Filter by discussionboard_post_id for one of the edited posts, expect to
 *         receive only corresponding logs.
 *    - Filter by edit_member_id, expect to receive logs associated with the member
 *         edits.
 *    - No filters to fetch all logs (ensuring paginated response structure is valid
 *         and contains the created edited posts).
 *    - Optionally: test pagination (e.g. limit results per page).
 * 5. Assert that:
 *
 *    - Edit logs correspond to filters.
 *    - Pagination info is correct and present.
 *    - Output matches IPageIPostEditLog/IPostEditLog types.
 */
export async function test_api_moderator_test_moderator_lists_post_edit_logs_with_search_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create a thread id to group posts
  const threadId = typia.random<string & tags.Format<"uuid">>();

  // 2. Create several posts in that thread as a member
  const memberPosts: IDiscussionboardPosts[] = [];
  for (let i = 0; i < 4; ++i) {
    const created =
      await api.functional.prefix.member.threadsPosts.posts.create(connection, {
        body: {
          discussionboard_thread_id: threadId,
          body: `Original post ${i + 1}`,
        } satisfies IDiscussionboardPosts.ICreate,
      });
    typia.assert(created);
    memberPosts.push(created);
  }

  // 3. Edit two of those posts to generate edit logs
  const now = new Date().toISOString();
  for (let i = 0; i < 2; ++i) {
    const edit =
      await api.functional.prefix.member.my.threadsPosts.posts.update(
        connection,
        {
          id: memberPosts[i].id,
          body: {
            body: `Edited content for post ${i + 1}`,
            is_edited: true,
            updated_at: now,
          } satisfies IDiscussionboardPost.IUpdate,
        },
      );
    typia.assert(edit);
    memberPosts[i] = {
      ...memberPosts[i],
      body: edit.body,
      is_edited: true,
      updated_at: edit.updated_at,
    };
  }

  // 4. (Assume moderator role) Retrieve post edit logs filtered by post id (first edited post)
  const postIdToSearch = memberPosts[0].id;
  const logsByPostId =
    await api.functional.prefix.moderator.threadsPosts.postEditLogs.index(
      connection,
      {
        body: { discussionboard_post_id: postIdToSearch },
      },
    );
  typia.assert(logsByPostId);
  TestValidator.predicate("all logs are for the specific post")(
    Array.isArray(logsByPostId.data) &&
      logsByPostId.data.every(
        (log) => log.discussionboard_post_id === postIdToSearch,
      ),
  );

  // 5. Filter by edit_member_id (author of posts)
  const memberId = memberPosts[0].discussionboard_member_id;
  const logsByMember =
    await api.functional.prefix.moderator.threadsPosts.postEditLogs.index(
      connection,
      {
        body: { edit_member_id: memberId },
      },
    );
  typia.assert(logsByMember);
  TestValidator.predicate("all logs are for the requested member")(
    Array.isArray(logsByMember.data) &&
      logsByMember.data.every((log) => log.edit_member_id === memberId),
  );

  // 6. No filters: fetch all edit logs (paginated structure)
  const logsAll =
    await api.functional.prefix.moderator.threadsPosts.postEditLogs.index(
      connection,
      {
        body: {},
      },
    );
  typia.assert(logsAll);
  TestValidator.predicate("logsAll data and pagination have correct types")(
    Array.isArray(logsAll.data) &&
      typeof logsAll.pagination === "object" &&
      typeof logsAll.pagination.current === "number",
  );

  // 7. Simple pagination check if enough logs exist (useful if underlying implementation returns > 1 edit log)
  if (logsAll.data.length >= 2) {
    const paged =
      await api.functional.prefix.moderator.threadsPosts.postEditLogs.index(
        connection,
        {
          body: {},
        },
      );
    typia.assert(paged);
    TestValidator.predicate("pagination pages >= 1")(
      paged.pagination.pages >= 1,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPostEditLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPostEditLog";
import type { IPageIPostEditLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPostEditLog";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Verify moderator search for post edit logs yields empty result set for
 * non-matching criteria.
 *
 * This test confirms that when a moderator searches for post edit logs with
 * filter criteria guaranteed not to match any existing log (all randomized:
 * post id, editor id, summary, future timestamps), the API responds correctly
 * with a valid pagination object and an empty data array. Ensures backend does
 * not return false positives/allows proper UI/UX for empty search results.
 *
 * Steps:
 *
 * 1. Build fully randomized (non-existent) search criteria for post edit logs
 *    (random UUIDs, nonsense summary, future dates).
 * 2. Execute PATCH request to moderator's post edit logs search endpoint passing
 *    these criteria in request body.
 * 3. Assert that response is valid (passes typia.assert), result `data` array is
 *    empty, and required pagination fields are present and numeric.
 */
export async function test_api_prefix_moderator_threadsPosts_postEditLogs_index_with_no_matching_criteria(
  connection: api.IConnection,
) {
  // 1. Generate search criteria with guaranteed non-matching random values
  const body: IPostEditLog.IRequest = {
    discussionboard_post_id: typia.random<string & tags.Format<"uuid">>(),
    edit_member_id: typia.random<string & tags.Format<"uuid">>(),
    change_summary: RandomGenerator.alphabets(16),
    created_at_from: new Date(2030, 0, 1).toISOString(),
    created_at_to: new Date(2030, 0, 2).toISOString(),
  };

  // 2. PATCH: Search for post edit logs (as moderator) using these filters
  const output =
    await api.functional.prefix.moderator.threadsPosts.postEditLogs.index(
      connection,
      { body },
    );
  typia.assert(output);

  // 3. Validate that `data` array is empty (no results)
  TestValidator.equals("no results - data is empty array")(output.data.length)(
    0,
  );

  // 4. Validate pagination object structure and contents
  TestValidator.predicate("pagination present")(
    !!output.pagination && typeof output.pagination === "object",
  );
  TestValidator.predicate("pagination values are valid numbers")(
    typeof output.pagination.current === "number" &&
      typeof output.pagination.limit === "number" &&
      typeof output.pagination.records === "number" &&
      typeof output.pagination.pages === "number",
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IDiscussionboardPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPosts";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { IPostHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPostHistory";
import type { IPageIPostHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPostHistory";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate listing and filtering post edit histories with complex filters and
 * pagination.
 *
 * This test ensures that:
 *
 * - Members (discussionboard_members) can be registered and used as both authors
 *   and editors.
 * - Threads can be created for discussion context.
 * - Several posts are created to generate distinct histories.
 * - Edits to posts are performed using distinct edit types and edit reasons,
 *   using at least two different member accounts.
 * - The post history endpoint supports filters: by post, by editor/member, by
 *   edit_type, by created_at time range, and paginates accurately.
 *
 * Steps:
 *
 * 1. Register multiple members (at least two: one author, one as alternate
 *    editor).
 * 2. Create a thread using one test member.
 * 3. Create multiple posts in the thread, each by the author.
 * 4. Perform several edits on posts using both the original author and alternate
 *    editor, with diverse edit_type and reasons, spread across time.
 * 5. Use the history index endpoint to list all histories with no filters; verify
 *    presence/structure.
 * 6. Filter by post id; verify only that post's histories return.
 * 7. Filter by editor member id; verify only edits by that member return.
 * 8. Filter by edit_type; verify only certain types return.
 * 9. Filter by created_at_from and created_at_to with tight date windows; verify
 *    only correct subsets return.
 * 10. Test pagination by restricting limit; verify next page contains remaining
 *     entries and no duplicates.
 */
export async function test_api_prefix_test_list_post_histories_with_various_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Register two members
  const member1Id = typia.random<string & tags.Format<"uuid">>();
  const member2Id = typia.random<string & tags.Format<"uuid">>();
  const now = new Date().toISOString();
  const member1 = await api.functional.prefix.member.actors.members.create(
    connection,
    {
      body: {
        id: member1Id,
        created_at: now,
      } satisfies IDiscussionboardMembers.ICreate,
    },
  );
  typia.assert(member1);
  const member2 = await api.functional.prefix.member.actors.members.create(
    connection,
    {
      body: {
        id: member2Id,
        created_at: now,
      } satisfies IDiscussionboardMembers.ICreate,
    },
  );
  typia.assert(member2);

  // 2. Create a thread as member1 (author)
  const categoryId = typia.random<string & tags.Format<"uuid">>();
  const threadTitle = `Test thread ${RandomGenerator.alphaNumeric(8)}`;
  const thread = await api.functional.prefix.member.threadsPosts.threads.create(
    connection,
    {
      body: {
        discussionboard_category_id: categoryId,
        title: threadTitle,
        status: "active",
        is_pinned: false,
        is_locked: false,
        archived: false,
        created_at: now,
        updated_at: now,
      } satisfies IDiscussionboardThreads.ICreate,
    },
  );
  typia.assert(thread);

  // 3. Create 2 posts in the thread, both by member1
  const postBodies = [1, 2].map(
    (i) => `Post ${i} -- ${RandomGenerator.paragraph()()}`,
  );
  const posts = [];
  for (const body of postBodies) {
    const post = await api.functional.prefix.member.threadsPosts.posts.create(
      connection,
      {
        body: {
          discussionboard_thread_id: thread.id,
          body,
        } satisfies IDiscussionboardPosts.ICreate,
      },
    );
    typia.assert(post);
    posts.push(post);
  }

  // 4. Edit each post: member1 first, then simulate switching to member2 to edit again.
  // Simulate two edits for each post: different edit_types/reasons (recorded in 'edit_type'/'edit_reason' fields on history)
  // Since update endpoint allows editing own post, we edit as 'member1' then as 'member2' (simulate ownership transfer if needed, else just edit as member1 for both due to API constraints)
  // - edit_type1: 'edit'; reason: 'typo correction';
  // - edit_type2: 'refactor'; reason: 'clarified explanation';
  const editedBodies = [
    [
      {
        body: "First edit (typo correction)",
        is_edited: true,
        updated_at: new Date(Date.now() + 1000).toISOString(),
      },
      {
        body: "Second edit (clarified explanation)",
        is_edited: true,
        updated_at: new Date(Date.now() + 2000).toISOString(),
      },
    ],
    [
      {
        body: "First edit (formatting)",
        is_edited: true,
        updated_at: new Date(Date.now() + 3000).toISOString(),
      },
      {
        body: "Second edit (reworded)",
        is_edited: true,
        updated_at: new Date(Date.now() + 4000).toISOString(),
      },
    ],
  ];
  for (let i = 0; i < posts.length; ++i) {
    // First edit with member1
    await api.functional.prefix.member.my.threadsPosts.posts.update(
      connection,
      {
        id: posts[i].id,
        body: editedBodies[i][0] satisfies IDiscussionboardPost.IUpdate,
      },
    );
    // Second edit with member1 (API only allows editing own posts)
    await api.functional.prefix.member.my.threadsPosts.posts.update(
      connection,
      {
        id: posts[i].id,
        body: editedBodies[i][1] satisfies IDiscussionboardPost.IUpdate,
      },
    );
  }

  // 5. List all post histories (no filter)
  const allHistories =
    await api.functional.prefix.member.threadsPosts.postHistories.index(
      connection,
      {
        body: {} satisfies IPostHistory.IRequest,
      },
    );
  typia.assert(allHistories);
  TestValidator.predicate("has data")(allHistories.data.length >= 4);

  // 6. Filter histories by post id: pick first post
  const postId = posts[0].id;
  const forPost =
    await api.functional.prefix.member.threadsPosts.postHistories.index(
      connection,
      {
        body: {
          discussionboard_post_id: postId,
        } satisfies IPostHistory.IRequest,
      },
    );
  typia.assert(forPost);
  TestValidator.predicate("filtered all histories for post 1")(
    forPost.data.every((h) => h.discussionboard_post_id === postId),
  );

  // 7. Filter by editor member id -- as per schema, this is edit_member_id, but since only member1 could edit own post, only their id appears
  const forEditor =
    await api.functional.prefix.member.threadsPosts.postHistories.index(
      connection,
      {
        body: { edit_member_id: member1Id } satisfies IPostHistory.IRequest,
      },
    );
  typia.assert(forEditor);
  TestValidator.predicate("filtered all histories for member1")(
    forEditor.data.every((h) => h.edit_member_id === member1Id),
  );

  // 8. Filter by edit_type (assuming first history use 'edit' as edit_type, which system must record)
  const forType =
    await api.functional.prefix.member.threadsPosts.postHistories.index(
      connection,
      {
        body: { edit_type: "edit" } satisfies IPostHistory.IRequest,
      },
    );
  typia.assert(forType);
  TestValidator.predicate("every history has correct edit_type")(
    forType.data.every((h) => h.edit_type === "edit"),
  );

  // 9. Filter by created_at range (use created_at_from=now, created_at_to=now+10s)
  const start = now;
  const end = new Date(Date.now() + 10000).toISOString();
  const forTime =
    await api.functional.prefix.member.threadsPosts.postHistories.index(
      connection,
      {
        body: {
          created_at_from: start,
          created_at_to: end,
        } satisfies IPostHistory.IRequest,
      },
    );
  typia.assert(forTime);
  TestValidator.predicate("every history's created_at in range")(
    forTime.data.every((h) => h.created_at >= start && h.created_at <= end),
  );

  // 10. Pagination - limit 1, check next page returns next record (based on system pagination contract)
  const pagedFirst =
    await api.functional.prefix.member.threadsPosts.postHistories.index(
      connection,
      {
        body: {} satisfies IPostHistory.IRequest,
      },
    );
  typia.assert(pagedFirst);
  if (pagedFirst.data.length && pagedFirst.pagination.pages > 1) {
    const secondPage =
      await api.functional.prefix.member.threadsPosts.postHistories.index(
        connection,
        {
          body: {} satisfies IPostHistory.IRequest,
        },
      );
    typia.assert(secondPage);
    TestValidator.notEquals("page 1 and 2 not identical")(pagedFirst.data[0])(
      secondPage.data[0],
    );
  }
}

