import type { IDiscussionboardPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPosts";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { IPostHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPostHistory";

/**
 * Verify that a moderator can access the full audit snapshot of any post by its
 * history id.
 *
 * This test simulates a moderation scenario:
 *
 * 1. Register two users (member, moderator) as separate members.
 * 2. The member creates a thread.
 * 3. The member creates a post in the thread.
 * 4. The member edits the post to generate an edit history record.
 * 5. The moderator attempts to fetch a post-edit history detail by id for review.
 *
 * This validates:
 *
 * - Field-level access for moderators to post history entries.
 * - End-to-end post/audit traceability.
 * - Presence of all audit and content fields in the post history model.
 *
 * Note: Since there is no API for listing all histories or directly retrieving
 * a post history id generated by an edit for this test, we simulate with a
 * randomly-generated id (in actual integrated tests the id would be captured
 * from post edit response or a history list API).
 */
export async function test_api_moderator_test_moderator_get_any_post_history_by_id_for_review(
  connection: api.IConnection,
) {
  // 1. Register two users: regular member and moderator (both as members, since no schema role distinction)
  const memberId: string = typia.random<string & tags.Format<"uuid">>();
  const moderatorId: string = typia.random<string & tags.Format<"uuid">>();
  const now: string = new Date().toISOString();

  // Register member
  const member = await api.functional.prefix.member.actors.members.create(
    connection,
    {
      body: {
        id: memberId,
        created_at: now,
      } satisfies IDiscussionboardMembers.ICreate,
    },
  );
  typia.assert(member);

  // Register moderator (as member record for test purposes)
  const moderator = await api.functional.prefix.member.actors.members.create(
    connection,
    {
      body: {
        id: moderatorId,
        created_at: now,
      } satisfies IDiscussionboardMembers.ICreate,
    },
  );
  typia.assert(moderator);

  // 2. Member creates a thread
  const thread = await api.functional.prefix.member.threadsPosts.threads.create(
    connection,
    {
      body: {
        discussionboard_member_id: memberId,
        discussionboard_category_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        title: "Test thread for moderation scenario",
        status: "active",
        is_pinned: false,
        is_locked: false,
        archived: false,
        created_at: now,
        updated_at: now,
      } satisfies IDiscussionboardThreads.ICreate,
    },
  );
  typia.assert(thread);

  // 3. Member creates a post in the thread
  const post = await api.functional.prefix.member.threadsPosts.posts.create(
    connection,
    {
      body: {
        discussionboard_thread_id: thread.id,
        body: "Original post content.",
      } satisfies IDiscussionboardPosts.ICreate,
    },
  );
  typia.assert(post);

  // 4. Member edits the post to generate a new history record
  const updatedContent = "Edited post content.";
  const updateTime = new Date(Date.now() + 60000).toISOString(); // +1min
  const updatedPost =
    await api.functional.prefix.member.my.threadsPosts.posts.update(
      connection,
      {
        id: post.id,
        body: {
          body: updatedContent,
          is_edited: true,
          updated_at: updateTime,
        } satisfies IDiscussionboardPost.IUpdate,
      },
    );
  typia.assert(updatedPost);

  // 5. Moderator fetches a post history by id.
  // NOTE: Because there is no list/history-id-from-post API, we simulate an id.
  // In integration, this would use a returned/captured id from post edit or post history list.
  const arbitraryHistoryId: string = typia.random<
    string & tags.Format<"uuid">
  >();
  const history =
    await api.functional.prefix.moderator.threadsPosts.postHistories.at(
      connection,
      {
        id: arbitraryHistoryId,
      },
    );
  typia.assert(history);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPoll } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoll";
import type { IPageIPoll } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPoll";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validates paginated and filtered poll listing by a moderator.
 *
 * This test ensures a moderator can retrieve polls under various filter and
 * pagination conditions, including:
 *
 * - Pagination (first and subsequent pages)
 * - Filtering by thread association, creator, anonymity, expiration status
 * - Polls that are both anonymous and non-anonymous, expired and active
 * - Polls created by the moderator and by other members
 * - Multiple thread associations
 *
 * Steps:
 *
 * 1. Create threads (simulate with random UUIDs)
 * 2. Create a set of polls with varying attributes:
 *
 *    - Different thread attachments
 *    - Both anonymous and non-anonymous
 *    - Some expired, some active
 *    - Created by two different users (simulate as 'me' and 'other')
 * 3. As a moderator, retrieve paginated list (first and second page)
 * 4. Filter by specific thread, by creator, by anonymity
 * 5. Filter by expired vs. active polls (via expires_before & expires_after)
 * 6. Validate that all returned poll records satisfy the intended filter and
 *    pagination conditions
 */
export async function test_api_prefix_test_list_polls_with_various_filters_and_roles(
  connection: api.IConnection,
) {
  // 1. Create threads (simulate with random UUIDs)
  const threadA = typia.random<string & tags.Format<"uuid">>();
  const threadB = typia.random<string & tags.Format<"uuid">>();

  // 2. Create two users (moderator, other member)
  // For this test, just simulate two logical creators with unique IDs
  // Hard-code the 'moderator' ID so we can filter by it
  const moderatorId = typia.random<string & tags.Format<"uuid">>();
  const otherMemberId = typia.random<string & tags.Format<"uuid">>();

  // Simulate: Join as member with moderatorId, create polls
  // Poll variations for full test matrix
  const now = new Date();
  const expiredDate = new Date(now.getTime() - 1000 * 60 * 60).toISOString(); // expired
  const futureDate = new Date(now.getTime() + 1000 * 60 * 60).toISOString(); // active

  // Create polls: moderator in threadA (anon/non-anon, expired/active)
  const poll_mod_threadA_active_anon =
    await api.functional.prefix.member.polls.create(connection, {
      body: {
        discussionboard_thread_id: threadA,
        prompt: "Active anon poll by moderator A",
        allow_multiple_choices: false,
        is_anonymous: true,
        expires_at: futureDate,
      },
    });
  typia.assert(poll_mod_threadA_active_anon);

  const poll_mod_threadA_expired_nonanon =
    await api.functional.prefix.member.polls.create(connection, {
      body: {
        discussionboard_thread_id: threadA,
        prompt: "Expired non-anon poll by moderator A",
        allow_multiple_choices: false,
        is_anonymous: false,
        expires_at: expiredDate,
      },
    });
  typia.assert(poll_mod_threadA_expired_nonanon);

  // Create polls: moderator in threadB
  const poll_mod_threadB_active_nonanon =
    await api.functional.prefix.member.polls.create(connection, {
      body: {
        discussionboard_thread_id: threadB,
        prompt: "Active non-anon poll by moderator B",
        allow_multiple_choices: true,
        is_anonymous: false,
        expires_at: futureDate,
      },
    });
  typia.assert(poll_mod_threadB_active_nonanon);

  // Simulate: Join as member with otherMemberId, create polls
  // For this test, assume connection now refers to this user
  const poll_other_threadA_active_anon =
    await api.functional.prefix.member.polls.create(connection, {
      body: {
        discussionboard_thread_id: threadA,
        prompt: "Active anon poll by other A",
        allow_multiple_choices: false,
        is_anonymous: true,
        expires_at: futureDate,
      },
    });
  typia.assert(poll_other_threadA_active_anon);

  // 3. Moderator retrieves first page (default limit, no filter)
  let page1 = await api.functional.prefix.moderator.polls.index(connection, {
    body: {},
  });
  typia.assert(page1);

  // (Could create more polls to test second page)
  // 4. Filtering: by thread
  let threadAResult = await api.functional.prefix.moderator.polls.index(
    connection,
    {
      body: { discussionboard_thread_id: threadA },
    },
  );
  typia.assert(threadAResult);
  for (const p of threadAResult.data)
    TestValidator.equals("thread matches")(p.discussionboard_thread_id)(
      threadA,
    );

  // Filtering: by creator (moderatorId)
  let creatorResult = await api.functional.prefix.moderator.polls.index(
    connection,
    {
      body: { created_by_member_id: moderatorId },
    },
  );
  typia.assert(creatorResult);
  for (const p of creatorResult.data)
    TestValidator.equals("created by moderator")(p.created_by_member_id)(
      moderatorId,
    );

  // Filtering: by is_anonymous true
  let anonResult = await api.functional.prefix.moderator.polls.index(
    connection,
    {
      body: { is_anonymous: true },
    },
  );
  typia.assert(anonResult);
  for (const p of anonResult.data)
    TestValidator.equals("anonymity")(p.is_anonymous)(true);

  // Filtering: by expires_before (expired)
  let expiredResult = await api.functional.prefix.moderator.polls.index(
    connection,
    {
      body: { expires_before: now.toISOString() },
    },
  );
  typia.assert(expiredResult);
  for (const p of expiredResult.data)
    TestValidator.predicate("expired poll")(
      !!p.expires_at && p.expires_at < now.toISOString(),
    );

  // Filtering: by expires_after (active)
  let activeResult = await api.functional.prefix.moderator.polls.index(
    connection,
    {
      body: { expires_after: now.toISOString() },
    },
  );
  typia.assert(activeResult);
  for (const p of activeResult.data)
    TestValidator.predicate("active poll")(
      !!p.expires_at && p.expires_at > now.toISOString(),
    );

  // (Additional combinations can be created for full coverage)
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPoll } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoll";
import type { IPageIPoll } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPoll";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate admin poll listing, filtering, and pagination across all members and
 * threads
 *
 * This test ensures that an admin can:
 *
 * - Retrieve all polls regardless of the creator or thread context
 * - Filter for expired (non-active) and active polls based on expires_at value
 * - Search by prompt substring
 * - Paginate over large result sets
 *
 * Steps:
 *
 * 1. Prepare a pool of polls, created by simulated different members, spanning
 *    multiple threads, with varied
 *    prompt/expiration/allow_multiple_choices/is_anonymous
 * 2. As admin, fetch all polls without filters and check all created polls are
 *    included; check pagination metadata
 * 3. Filter by expired (expires_at < now), verify only those are returned
 * 4. Filter by active (expires_at > now or expires_at is null), verify only those
 *    are returned
 * 5. Filter by prompt substring (match known substring)
 * 6. Paginate with high limit per page (performance)
 */
export async function test_api_polls_test_list_polls_with_admin_privileges_and_filters(
  connection: api.IConnection,
) {
  // 1. Data preparation: Create test polls for 3 fake members and 2 threads with varied attributes
  const now = new Date();
  const threads = [
    typia.random<string & tags.Format<"uuid">>(),
    typia.random<string & tags.Format<"uuid">>(),
  ];
  const memberIds = [
    typia.random<string & tags.Format<"uuid">>(),
    typia.random<string & tags.Format<"uuid">>(),
    typia.random<string & tags.Format<"uuid">>(),
  ];

  // Helper to create polls with varying properties
  const createdPolls: IPoll[] = [];
  // Diverse prompts for substring test
  const prompts = [
    "Special Event Poll",
    "Annual Survey",
    "Special Offer Vote",
    "Feedback Poll",
    "Announcement QnA",
    "Bug Bash Poll",
    "Release Vote",
    "Roadmap Poll",
    "Testers Survey",
    "Special Beta Survey",
  ];

  for (let i = 0; i < prompts.length; ++i) {
    // Distribute thread and member associations
    const thread_id = threads[i % threads.length];
    const member_id = memberIds[i % memberIds.length];
    // Vary allow_multiple_choices and is_anonymous
    const allow_multiple_choices = i % 2 === 0;
    const is_anonymous = i % 3 === 0;
    // Alternate expiration: some expired, some active, some perpetual
    let expires_at: string | undefined = undefined;
    if (i % 3 === 0)
      expires_at = new Date(now.getTime() - 24 * 3600 * 1000).toISOString(); // expired
    else if (i % 3 === 1)
      expires_at = new Date(now.getTime() + 7 * 24 * 3600 * 1000).toISOString(); // future
    // i%3 === 2 → perpetual (expires_at omitted)

    // ---
    // Switch to 'member_id' context as needed (simulate login if test infra allows)
    // Here we'll assume the connection uses correct member when posting the poll
    // ---
    const poll = await api.functional.prefix.member.polls.create(connection, {
      body: {
        discussionboard_thread_id: thread_id,
        prompt: prompts[i],
        allow_multiple_choices,
        is_anonymous,
        ...(expires_at ? { expires_at } : {}),
      } satisfies IPoll.ICreate,
    });
    typia.assert(poll);
    createdPolls.push(poll);
  }
  // For downstream checks
  const allPollIds = new Set(createdPolls.map((p) => p.id));

  // 2. As admin: fetch all polls, no filters
  const page_all = await api.functional.prefix.admin.polls.index(connection, {
    body: {},
  });
  typia.assert(page_all);
  // Confirm all created polls are included in results
  const returnedIds = page_all.data.map((p) => p.id);
  for (const pollId of allPollIds) {
    TestValidator.predicate("admin can see poll: " + pollId)(
      returnedIds.includes(pollId),
    );
  }
  // Check pagination metadata (page structure, not deep assert here)
  TestValidator.predicate("pagination info present")(
    typeof page_all.pagination.current === "number" &&
      typeof page_all.pagination.limit === "number",
  );

  // 3. Filter: expired (expires_at < now)
  const expiredPage = await api.functional.prefix.admin.polls.index(
    connection,
    {
      body: {
        expires_before: now.toISOString(),
      },
    },
  );
  typia.assert(expiredPage);
  for (const poll of expiredPage.data) {
    TestValidator.predicate("poll expired")(
      !!poll.expires_at && poll.expires_at < now.toISOString(),
    );
  }

  // 4. Filter: active (expires_after: now)
  const activePage = await api.functional.prefix.admin.polls.index(connection, {
    body: {
      expires_after: now.toISOString(),
    },
  });
  typia.assert(activePage);
  for (const poll of activePage.data) {
    TestValidator.predicate("poll active")(
      !poll.expires_at || poll.expires_at > now.toISOString(),
    );
  }

  // 5. Filter by prompt substring
  const promptFilter = "Special";
  const promptPage = await api.functional.prefix.admin.polls.index(connection, {
    body: {
      prompt: promptFilter,
    },
  });
  typia.assert(promptPage);
  for (const poll of promptPage.data) {
    TestValidator.predicate("prompt contains substring")(
      poll.prompt.toLowerCase().includes(promptFilter.toLowerCase()),
    );
  }

  // 6. Pagination test with high page size
  const largeLimit = 100;
  const pagedResult = await api.functional.prefix.admin.polls.index(
    connection,
    {
      body: {
        // No filter, just ask for big page size if supported
        // Field names match IPoll.IRequest (no limit param in DTO but if supported add here)
        // Because DTO does not have explicit pagination fields, we validate at least default paging returns >= allPollIds
      },
    },
  );
  typia.assert(pagedResult);
  // All created polls should be found in combined page(s)
  const pagedIds = pagedResult.data.map((p) => p.id);
  for (const pollId of allPollIds) {
    TestValidator.predicate("paged poll found: " + pollId)(
      pagedIds.includes(pollId),
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPoll } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoll";

/**
 * E2E test for member viewing poll details (success and error cases).
 *
 * Business context: Members may view full poll detail by its unique poll ID,
 * provided the poll exists and is accessible. Poll detail includes prompt,
 * configuration, expiration, and its discussion thread linkage. Members should
 * receive an error if poll does not exist (404), or if (per business rule) they
 * are not permitted to see a poll.
 *
 * Test design:
 *
 * 1. Create several new polls as a member (dependency: poll creation)
 * 2. For each created poll, retrieve detail by its ID and verify returned detail
 *    (prompt, thread linkage, config fields)
 * 3. Attempt to access a non-existent poll ID (expect error)
 * 4. If supported, attempt to access a poll a member is not authorized to see (if
 *    business logic distinguishes access)
 *
 * Steps:
 *
 * - Use the API to create at least one poll. Store the ID(s).
 * - Use the poll detail endpoint to fetch the poll by ID. Verify all actual
 *   fields match what was submitted/created.
 * - Attempt to retrieve a poll by a random (non-existent) UUID. Expect 404 error.
 * - (If supported) Attempt to retrieve a poll owned by another member or
 *   inaccessible per business rule. Expect Forbidden/404 error. (If there are
 *   no such rules, skip this step)
 */
export async function test_api_prefix_member_polls_test_view_poll_details_as_member_success_and_error_cases(
  connection: api.IConnection,
) {
  // 1. Create two distinct polls
  const threadIdA = typia.random<string & tags.Format<"uuid">>();
  const threadIdB = typia.random<string & tags.Format<"uuid">>();
  const pollA_create = {
    discussionboard_thread_id: threadIdA,
    prompt: "What is your favorite color?",
    allow_multiple_choices: false,
    is_anonymous: false,
    expires_at: typia.random<string & tags.Format<"date-time">>(),
  } satisfies IPoll.ICreate;
  const pollB_create = {
    discussionboard_thread_id: threadIdB,
    prompt: "Choose your preferred working style.",
    allow_multiple_choices: true,
    is_anonymous: true,
    expires_at: undefined,
  } satisfies IPoll.ICreate;
  const pollA: IPoll = await api.functional.prefix.member.polls.create(
    connection,
    { body: pollA_create },
  );
  typia.assert(pollA);
  const pollB: IPoll = await api.functional.prefix.member.polls.create(
    connection,
    { body: pollB_create },
  );
  typia.assert(pollB);

  // 2. Retrieve and assert pollA detail
  const outputA: IPoll = await api.functional.prefix.member.polls.at(
    connection,
    { id: pollA.id },
  );
  typia.assert(outputA);
  TestValidator.equals("pollA.id matches")(outputA.id)(pollA.id);
  TestValidator.equals("pollA thread association")(
    outputA.discussionboard_thread_id,
  )(pollA_create.discussionboard_thread_id);
  TestValidator.equals("pollA prompt")(outputA.prompt)(pollA_create.prompt);
  TestValidator.equals("pollA multiple choice flag")(
    outputA.allow_multiple_choices,
  )(pollA_create.allow_multiple_choices);
  TestValidator.equals("pollA anonymous flag")(outputA.is_anonymous)(
    pollA_create.is_anonymous,
  );
  TestValidator.equals("pollA expires_at")(outputA.expires_at)(
    pollA_create.expires_at,
  );

  // 3. Retrieve and assert pollB detail
  const outputB: IPoll = await api.functional.prefix.member.polls.at(
    connection,
    { id: pollB.id },
  );
  typia.assert(outputB);
  TestValidator.equals("pollB.id matches")(outputB.id)(pollB.id);
  TestValidator.equals("pollB thread association")(
    outputB.discussionboard_thread_id,
  )(pollB_create.discussionboard_thread_id);
  TestValidator.equals("pollB prompt")(outputB.prompt)(pollB_create.prompt);
  TestValidator.equals("pollB multiple choice flag")(
    outputB.allow_multiple_choices,
  )(pollB_create.allow_multiple_choices);
  TestValidator.equals("pollB anonymous flag")(outputB.is_anonymous)(
    pollB_create.is_anonymous,
  );
  TestValidator.equals("pollB expires_at")(outputB.expires_at)(
    pollB_create.expires_at,
  );

  // 4. Error: Try getting a non-existent poll  (should get 404 error)
  await TestValidator.error("non-existent poll should 404")(() =>
    api.functional.prefix.member.polls.at(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    }),
  );
  // 5. (Optional) If business logic restricts, try unauthorized poll access (skipped, not enough context)
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPoll } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoll";

/**
 * Validate moderator's ability to view poll details for polls with diverse
 * visibility and creators, including error scenarios.
 *
 * This test ensures that a moderator can retrieve any poll's full details
 * (prompt, anonymity, expiration, voting configuration, and creator) regardless
 * of which member originally created the poll. It validates access breadth,
 * correct data exposure, and proper error handling for invalid IDs. The test
 * covers both normal retrieval and attempting to access a non-existent poll
 * (404 scenario).
 *
 * Steps:
 *
 * 1. Create several polls (at least two), each with different configuration for
 *    prompt, allow_multiple_choices, is_anonymous, and expiration.
 * 2. As moderator, retrieve each poll using the moderator poll details endpoint,
 *    and assert all fields match expectations.
 * 3. Attempt to retrieve a poll by a random/non-existent UUID as id, expecting an
 *    error (e.g. 404) is thrown.
 */
export async function test_api_polls_test_view_poll_details_as_moderator_various_visibility(
  connection: api.IConnection,
) {
  // 1. Create diverse polls via the member API
  const createdPolls: IPoll[] = [];
  for (let i = 0; i < 2; ++i) {
    const createBody: IPoll.ICreate = {
      discussionboard_thread_id: typia.random<string & tags.Format<"uuid">>(),
      prompt: `Prompt ${i} - ${RandomGenerator.paragraph()()}`,
      allow_multiple_choices: i % 2 === 0,
      is_anonymous: i % 2 === 1,
      expires_at:
        i === 0
          ? (new Date(Date.now() + 86400000).toISOString() as string &
              tags.Format<"date-time">)
          : undefined,
    };
    const poll = await api.functional.prefix.member.polls.create(connection, {
      body: createBody,
    });
    typia.assert(poll);
    createdPolls.push(poll);
  }

  // 2. As moderator, retrieve each created poll by id
  for (const poll of createdPolls) {
    const retrieved = await api.functional.prefix.moderator.polls.at(
      connection,
      { id: poll.id },
    );
    typia.assert(retrieved);
    // 3. Validate all major fields
    TestValidator.equals("poll id")(retrieved.id)(poll.id);
    TestValidator.equals("discussionboard_thread_id")(
      retrieved.discussionboard_thread_id,
    )(poll.discussionboard_thread_id);
    TestValidator.equals("created_by_member_id")(
      retrieved.created_by_member_id,
    )(poll.created_by_member_id);
    TestValidator.equals("prompt")(retrieved.prompt)(poll.prompt);
    TestValidator.equals("allow_multiple_choices")(
      retrieved.allow_multiple_choices,
    )(poll.allow_multiple_choices);
    TestValidator.equals("is_anonymous")(retrieved.is_anonymous)(
      poll.is_anonymous,
    );
    TestValidator.equals("expires_at")(retrieved.expires_at ?? null)(
      poll.expires_at ?? null,
    );
    TestValidator.equals("created_at")(retrieved.created_at)(poll.created_at);
  }

  // 4. Error scenario: Retrieve non-existent poll id
  await TestValidator.error(
    "moderator should receive error for non-existent poll",
  )(async () => {
    await api.functional.prefix.moderator.polls.at(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBan } from "@ORGANIZATION/PROJECT-api/lib/structures/IBan";
import type { IDiscussionboardBan } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardBan";

/**
 * Validate retrieval of an existing ban record by its ID.
 *
 * This test scenario ensures that when an admin creates a ban record (for
 * either a member or guest), the ban details can subsequently be retrieved
 * correctly by its unique ID. It verifies accurate field mapping between the
 * creation and retrieval APIs.
 *
 * Test Steps:
 *
 * 1. Create a ban record via POST /prefix/admin//bans, supplying all necessary
 *    fields (targeting either a member or guest, but not both).
 * 2. Retrieve the ban record just created using GET /prefix/admin//bans/{id} with
 *    the ID returned from step 1.
 * 3. Validate that all returned fields from the GET endpoint match those of the
 *    created record and satisfy expected schema.
 */
export async function test_api_prefix_admin_bans_test_get_ban_by_id_with_existing_record(
  connection: api.IConnection,
) {
  // 1. Create a ban record (testing with member ban; set banned_guest_id to null)
  const banCreateInput = {
    banned_member_id: typia.random<string & tags.Format<"uuid">>(),
    banned_guest_id: null,
    admin_id: typia.random<string & tags.Format<"uuid">>(),
    ban_reason: "Violation of forum rules - spam posting",
    banned_at: new Date().toISOString(),
    notes: "First offense, aggressive self-promotion as member.",
  } satisfies IDiscussionboardBan.ICreate;
  const created = await api.functional.prefix.admin.bans.create(connection, {
    body: banCreateInput,
  });
  typia.assert(created);

  // 2. Retrieve the ban by its ID with the GET endpoint
  const retrieved = await api.functional.prefix.admin.bans.at(connection, {
    id: created.id,
  });
  typia.assert(retrieved);

  // 3. Validate data mapping and correctness
  TestValidator.equals("ban id")(retrieved.id)(created.id);
  TestValidator.equals("admin id")(retrieved.admin_id)(banCreateInput.admin_id);
  TestValidator.equals("banned member")(retrieved.banned_member_id)(
    banCreateInput.banned_member_id,
  );
  TestValidator.equals("banned guest")(retrieved.banned_guest_id)(
    banCreateInput.banned_guest_id,
  );
  TestValidator.equals("ban reason")(retrieved.ban_reason)(
    banCreateInput.ban_reason,
  );
  TestValidator.equals("banned at")(retrieved.banned_at)(
    banCreateInput.banned_at,
  );
  TestValidator.equals("notes")(retrieved.notes)(banCreateInput.notes);
}

