 *   성공적으로 DB에 반영되고, 응답 데이터가 입력값과 정확히 일치해야 한다. 실제 밴 집행(조회/재확인)은 후속 retrieval
 *   endpoint 없으므로 불가하며, 응답 데이터로만 검증한다.
 *
 * 1. 테스트용 영구 BAN 생성 입력 데이터를 생성한다.
 * 2. 관리자로서 ban 등록 API를 호출하고, 정상적으로 생성되는지 확인한다.
 * 3. 응답값의 각 필드가 입력값과 정확히 일치하는지 검증한다.
 */
export async function test_api_prefix_test_create_ban_for_member_with_valid_data(
  connection: api.IConnection,
) {
