  const banInput: IDiscussionboardBan.ICreate = {
    banned_member_id: typia.random<string & tags.Format<"uuid">>(),
    admin_id: typia.random<string & tags.Format<"uuid">>(),
    ban_reason: RandomGenerator.paragraph()(),
    banned_at: new Date().toISOString() as string & tags.Format<"date-time">,
    notes: RandomGenerator.paragraph()(),
  };

  // 2. 관리자가 밴 등록 API 호출
  const createdBan: IDiscussionboardBan =
    await api.functional.prefix.admin.bans.create(connection, {
