  TestValidator.equals("admin_id")(createdBan.admin_id)(banInput.admin_id);
  TestValidator.equals("ban_reason")(createdBan.ban_reason)(
    banInput.ban_reason,
  );
  TestValidator.equals("banned_at")(createdBan.banned_at)(banInput.banned_at);
  TestValidator.equals("notes")(createdBan.notes)(banInput.notes);
