/**
 * Test the creation of a permanent ban record for a guest via the admin bans
 * creation endpoint.
 *
 * This test ensures that when only a guest-specific field (banned_guest_id) is
 * provided—without member fields—a valid ban is successfully created. It also
 * checks that no member fields exist, compliance with admin assignment, and
 * validates all required fields such as reason and timestamps. The test further
 * asserts that the returned ban record contains the correct guest-based
 * identifiers and no member-based identifiers.
 *
 * Step-by-step process:
 *
 * 1. Prepare random UUIDs for admin and guest.
 * 2. Call the ban creation API, supplying only banned_guest_id (not
 *    banned_member_id).
 * 3. Confirm the returned ban record:
 *
 *    - Has the supplied guest_id,
 *    - Has null/undefined member_id,
 *    - Admin_id matches,
 *    - Ban reason and timestamp are correct.
 * 4. Confirm output validates the schema and all required fields are present.
 */
export async function test_api_prefix_admin_bans_test_create_ban_for_guest_with_valid_data(
  connection: api.IConnection,
) {
  // 1. Prepare sample admin and guest IDs
  const adminId = typia.random<string & tags.Format<"uuid">>();
  const guestId = typia.random<string & tags.Format<"uuid">>();
  const now = new Date().toISOString();
  const reason = "Violation of rules (guest test)";

  // 2. Make the ban creation request, providing only guest ID
  const result = await api.functional.prefix.admin.bans.create(connection, {
    body: {
      banned_guest_id: guestId,
      banned_member_id: null, // Explicitly null to indicate guest ban
      admin_id: adminId,
      ban_reason: reason,
      banned_at: now,
      notes: null,
    } satisfies IDiscussionboardBan.ICreate,
  });
  typia.assert(result);

  // 3. Validate output fields
  TestValidator.equals("banned_guest_id matches")(result.banned_guest_id)(
    guestId,
  );
  TestValidator.equals("banned_member_id is null")(result.banned_member_id)(
    null,
  );
  TestValidator.equals("admin_id matches")(result.admin_id)(adminId);
  TestValidator.equals("ban reason matches")(result.ban_reason)(reason);
  TestValidator.equals("banned_at matches")(result.banned_at)(now);
  TestValidator.equals("notes is null")(result.notes)(null);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardBan } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardBan";

/**
 * Test creation of a ban with missing required fields using the admin bans
 * endpoint.
 *
 * This test validates the API's enforcement of required field presence when
 * attempting to create a ban as an admin. According to the DTO:
 *
 * - "banned_member_id" OR "banned_guest_id" must be provided (but not both; at
 *   least one is required).
 * - "ban_reason" (string), "admin_id" (uuid), and "banned_at" (date-time) are all
 *   required. This test attempts to create a ban in scenarios where essential
 *   fields are missing, ensuring the API properly rejects invalid requests.
 *
 * Steps:
 *
 * 1. Attempt to create a ban missing BOTH banned_member_id and banned_guest_id
 *    (violating "at least one" requirement).
 * 2. Attempt to create a ban missing the reason (ban_reason).
 * 3. Attempt to create a ban missing banned_at.
 * 4. Attempt to create a ban with both banned_member_id and banned_guest_id
 *    present (violating mutual exclusivity).
 * 5. Attempt to create a ban omitting the required admin_id. For each case, expect
 *    the API to throw a validation error and not accept the creation.
 */
export async function test_api_prefix_admin_bans_test_create_ban_with_missing_required_fields(
  connection: api.IConnection,
) {
  // 1. Missing both banned_member_id and banned_guest_id
  await TestValidator.error(
    "Missing both banned_member_id and banned_guest_id should fail",
  )(() =>
    api.functional.prefix.admin.bans.create(connection, {
      body: {
        // Both fields omitted
        admin_id: typia.random<string & tags.Format<"uuid">>(),
        ban_reason: "Violation of rules.",
        banned_at: new Date().toISOString(),
      } satisfies IDiscussionboardBan.ICreate,
    }),
  );

  // 2. Missing ban_reason (required)
  await TestValidator.error("Missing ban_reason should fail")(() =>
    api.functional.prefix.admin.bans.create(connection, {
      body: {
        banned_member_id: typia.random<string & tags.Format<"uuid">>(),
        admin_id: typia.random<string & tags.Format<"uuid">>(),
        // ban_reason omitted
        banned_at: new Date().toISOString(),
      } as any,
    }),
  );

  // 3. Missing banned_at (required)
  await TestValidator.error("Missing banned_at should fail")(() =>
    api.functional.prefix.admin.bans.create(connection, {
      body: {
        banned_member_id: typia.random<string & tags.Format<"uuid">>(),
        admin_id: typia.random<string & tags.Format<"uuid">>(),
        ban_reason: "Spam detected.",
        // banned_at omitted
      } as any,
    }),
  );

  // 4. Both banned_member_id and banned_guest_id present (should not both be set)
  await TestValidator.error(
    "Both banned_member_id and banned_guest_id should fail",
  )(() =>
    api.functional.prefix.admin.bans.create(connection, {
      body: {
        banned_member_id: typia.random<string & tags.Format<"uuid">>(),
        banned_guest_id: typia.random<string & tags.Format<"uuid">>(),
        admin_id: typia.random<string & tags.Format<"uuid">>(),
        ban_reason: "Testing mutual exclusivity.",
        banned_at: new Date().toISOString(),
      } satisfies IDiscussionboardBan.ICreate,
    }),
  );

  // 5. Omit admin_id (required)
  await TestValidator.error("Omitting admin_id should fail")(() =>
    api.functional.prefix.admin.bans.create(connection, {
      body: {
        banned_member_id: typia.random<string & tags.Format<"uuid">>(),
        ban_reason: "Test missing admin.",
        banned_at: new Date().toISOString(),
      } as any,
    }),
  );
}

