import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardBan } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardBan";

/**
 * Test: Prevent creating duplicate bans for the same member
 *
 * This test validates that the system prevents the creation of a duplicate ban
 * for a member who is already banned.
 *
 * Business context: Banning the same member multiple times should not be
 * allowed unless previous bans have been lifted. This constraint is enforced to
 * prevent administrative errors and inconsistent state.
 *
 * Workflow:
 *
 * 1. Prepare a unique admin_id and banned_member_id.
 * 2. Successfully create a ban for the chosen member by the admin.
 * 3. Attempt to create another ban for the same member (with a different
 *    ban_reason and banned_at).
 * 4. Confirm the system throws an error for the duplicate ban.
 */
export async function test_api_prefix_admin_bans_test_create_duplicate_ban_for_same_member(
  connection: api.IConnection,
) {
  // Step 1: Prepare required IDs
  const admin_id: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();
  const banned_member_id: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();
  const initial_banned_at: string = new Date().toISOString();
  const later_banned_at: string = new Date(Date.now() + 60000).toISOString();

  // Step 2: Issue the first ban (should succeed)
  const firstBan = await api.functional.prefix.admin.bans.create(connection, {
    body: {
      banned_member_id,
      banned_guest_id: null,
      admin_id,
      ban_reason: "Initial test ban for duplicate prevention",
      banned_at: initial_banned_at,
      notes: "ban creation for duplicate test",
    } satisfies IDiscussionboardBan.ICreate,
  });
  typia.assert(firstBan);

  // Step 3: Attempt to issue a second ban for the same member (should fail)
  await TestValidator.error(
    "duplicate ban for same member must not be allowed",
  )(() =>
    api.functional.prefix.admin.bans.create(connection, {
      body: {
        banned_member_id,
        banned_guest_id: null,
        admin_id,
        ban_reason: "Trying duplicate ban",
        banned_at: later_banned_at,
        notes: "should trigger business rule error for duplicate",
      } satisfies IDiscussionboardBan.ICreate,
    }),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardBan } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardBan";

/**
 * Test successful update of the reason and notes fields of an existing ban
 * record by an admin.
 *
 * Business context: Administrators must be able to edit mutable fields
 * (ban_reason, notes) of an existing ban record without affecting immutable
 * fields (like IDs and issued timestamp). This ensures record traceability
 * while supporting administrative note correctness and refined reasoning.
 *
 * Test process:
 *
 * 1. Create a ban record using the admin ban creation endpoint and capture all
 *    original values.
 * 2. Prepare new values for `ban_reason` and `notes`, including variant values
 *    (such as null or empty string) for the notes test.
 * 3. Call the ban update endpoint with the new reason and notes for the created
 *    ban's ID.
 * 4. Check that the API response includes updated reason and notes and that all
 *    the other fields remain identical to the original record.
 * 5. Use strong type assertions and field equality checks for both updated and
 *    preserved fields.
 * 6. Test both: updating with a different string and clearing notes to null.
 */
export async function test_api_prefix_test_update_ban_reason_and_notes_successfully(
  connection: api.IConnection,
) {
  // 1. Create a ban record (dependency)
  const original_create: IDiscussionboardBan =
    await api.functional.prefix.admin.bans.create(connection, {
      body: {
        admin_id: typia.random<string & tags.Format<"uuid">>(),
        ban_reason: "Spam Posting",
        banned_at: new Date().toISOString(),
        notes: "Initial note",
        banned_member_id: typia.random<string & tags.Format<"uuid">>(),
        banned_guest_id: null,
      } satisfies IDiscussionboardBan.ICreate,
    });
  typia.assert(original_create);

  // 2. Update ban_reason and notes
  const updatedBanReason = "Changed reason for moderation";
  const updatedNotes = "Updated notes on investigation.";

  const updated: IDiscussionboardBan =
    await api.functional.prefix.admin.my.bans.update(connection, {
      id: original_create.id,
      body: {
        ban_reason: updatedBanReason,
        notes: updatedNotes,
      } satisfies IDiscussionboardBan.IUpdate,
    });
  typia.assert(updated);

  // 3. Validate updated fields are changed and immutables are preserved
  TestValidator.equals("ban_reason updated")(updated.ban_reason)(
    updatedBanReason,
  );
  TestValidator.equals("notes updated")(updated.notes)(updatedNotes);
  TestValidator.equals("banned_member_id unchanged")(updated.banned_member_id)(
    original_create.banned_member_id,
  );
  TestValidator.equals("banned_guest_id unchanged")(updated.banned_guest_id)(
    original_create.banned_guest_id,
  );
  TestValidator.equals("admin_id unchanged")(updated.admin_id)(
    original_create.admin_id,
  );
  TestValidator.equals("banned_at unchanged")(updated.banned_at)(
    original_create.banned_at,
  );

  // 4. Also test clearing notes (set to null)
  const cleared: IDiscussionboardBan =
    await api.functional.prefix.admin.my.bans.update(connection, {
      id: original_create.id,
      body: { notes: null } satisfies IDiscussionboardBan.IUpdate,
    });
  typia.assert(cleared);
  TestValidator.equals("notes cleared")(cleared.notes)(null);
  TestValidator.equals("ban_reason remains unchanged")(cleared.ban_reason)(
    updatedBanReason,
  );
  TestValidator.equals("banned_member_id still unchanged")(
    cleared.banned_member_id,
  )(original_create.banned_member_id);
  TestValidator.equals("banned_guest_id still unchanged")(
    cleared.banned_guest_id,
  )(original_create.banned_guest_id);
  TestValidator.equals("admin_id still unchanged")(cleared.admin_id)(
    original_create.admin_id,
  );
  TestValidator.equals("banned_at still unchanged")(cleared.banned_at)(
    original_create.banned_at,
  );
}

