import type { IDiscussionboardBan } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardBan";

/**
 * Test that non-admin or non-owner users cannot update a ban record.
 *
 * This test attempts to update an existing ban using a user account that does
 * not have admin rights or is not the owner of the ban. The API should respond
 * with an access denied error (authorization failure), confirming correct
 * update access control on bans.
 *
