import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardPostReaction } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPostReaction";
import type { IPageIDiscussionboardPostReaction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardPostReaction";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 게시글 리액션 필터·페이지네이션 응답 검증 테스트
 *
 * 게시글 리액션(PostReaction) 목록 API에서 postId, memberId, reaction_type 같은 다양한 필터 조합 및
 * 페이지네이션(parsing) 로직이 올바른지 검증한다.
 *
 * - 여러 개의 리액션 데이터를 생성(서로 다른 postId/memberId/type)하여 조건별 목록 응답을 검증
 * - 단일 필드별 개별 필터링(postId, memberId, reaction_type) 시도 및 결과 체크
 * - 페이지네이션 응답 구조와 필드가 올바른가도 검사
 * - 존재하지 않는 조합의 필터값으로 빈 결과가 오는지(엣지 케이스)도 추가 확인
 *
 * 1. 조건별 필터와 페이지네이션에 쓸 리액션 여러 건 생성
 * 2. PostId, memberId, reaction_type 하나씩 조건으로 목록을 각각 검색 - 모두 응답이 조건에 정확히 일치하는지
 * 3. 페이지네이션 정보 응답(current, limit 등) 구조 및 타입이 정상인지 검토
 * 4. 존재하지 않는 값으로 검색 요청 시 데이터 배열 비어있는지 테스트
 */
export async function test_api_prefix_member_postReactions_test_list_post_reactions_with_valid_filters(
  connection: api.IConnection,
) {
  // [준비] 테스트용 다양한 post, member UUID 및 타입 조합 리액션 3건 생성
  const postId1 = typia.random<string & tags.Format<"uuid">>();
  const postId2 = typia.random<string & tags.Format<"uuid">>();
  const memberId1 = typia.random<string & tags.Format<"uuid">>();
  const memberId2 = typia.random<string & tags.Format<"uuid">>();

  const reaction1 = await api.functional.prefix.member.postReactions.create(
    connection,
    {
      body: {
        discussionboard_post_id: postId1,
        discussionboard_member_id: memberId1,
        reaction_type: "heart",
      } satisfies IDiscussionboardPostReaction.ICreate,
    },
  );
  const reaction2 = await api.functional.prefix.member.postReactions.create(
    connection,
    {
      body: {
        discussionboard_post_id: postId1,
        discussionboard_member_id: memberId2,
        reaction_type: "laugh",
      } satisfies IDiscussionboardPostReaction.ICreate,
    },
  );
  const reaction3 = await api.functional.prefix.member.postReactions.create(
    connection,
    {
      body: {
        discussionboard_post_id: postId2,
        discussionboard_member_id: memberId1,
        reaction_type: "sad",
      } satisfies IDiscussionboardPostReaction.ICreate,
    },
  );
  TestValidator.predicate("at least 3 reactions created")(
    [reaction1, reaction2, reaction3].length >= 3,
  );

  // [케이스1] postId 단일값 필터링: 지정 postId만 리턴
  const outByPost = await api.functional.prefix.member.postReactions.index(
    connection,
    {
      body: {
        discussionboard_post_id: postId1,
      } satisfies IDiscussionboardPostReaction.IRequest,
    },
  );
  typia.assert(outByPost);
  TestValidator.predicate("filtered by postId returns only correct records")(
    outByPost.data.every((r) => r.discussionboard_post_id === postId1),
  );

  // [케이스2] memberId 단일값 필터링: 지정 멤버 리액션만 리턴
  const outByMember = await api.functional.prefix.member.postReactions.index(
    connection,
    {
      body: {
        discussionboard_member_id: memberId1,
      } satisfies IDiscussionboardPostReaction.IRequest,
    },
  );
  typia.assert(outByMember);
  TestValidator.predicate("filtered by memberId returns only correct records")(
    outByMember.data.every((r) => r.discussionboard_member_id === memberId1),
  );

  // [케이스3] reaction_type 기준 필터링: 지정 타입만 리턴
  const outByType = await api.functional.prefix.member.postReactions.index(
    connection,
    {
      body: {
        reaction_type: "heart",
      } satisfies IDiscussionboardPostReaction.IRequest,
    },
  );
  typia.assert(outByType);
  TestValidator.predicate("filtered by type returns only correct records")(
    outByType.data.every((r) => r.reaction_type === "heart"),
  );

  // [페이지네이션] current, limit 등 구조·값 정상인지 확인
  TestValidator.predicate("pagination 정보 존재«current, limit…»")(
    typeof outByPost.pagination.current === "number" &&
      typeof outByPost.pagination.limit === "number",
  );

  // [엣지케이스] 존재하지 않는 값 조합 검색 → 빈 data 돌려주는지
  const outEmpty = await api.functional.prefix.member.postReactions.index(
    connection,
    {
      body: {
        discussionboard_post_id: typia.random<string & tags.Format<"uuid">>(),
        discussionboard_member_id: typia.random<string & tags.Format<"uuid">>(),
        reaction_type: "zzznotype",
      } satisfies IDiscussionboardPostReaction.IRequest,
    },
  );
  typia.assert(outEmpty);
  TestValidator.equals("no match returns empty array")(outEmpty.data)([]);
}

