        discussionboard_member_id: memberAId,
        reaction_type: "heart",
      } satisfies IDiscussionboardPostReaction.ICreate,
    },
  );
  typia.assert(reactionA);

  // 3. Member B creates a 'laugh' reaction to Post X
  const reactionB = await api.functional.prefix.member.postReactions.create(
    connection,
    {
      body: {
        discussionboard_post_id: postXId,
        discussionboard_member_id: memberBId,
        reaction_type: "laugh",
      } satisfies IDiscussionboardPostReaction.ICreate,
    },
  );
  typia.assert(reactionB);

  // 4. As Member A: list all reactions for Post X
  // (Assume connection for Member A authentication; real-world test would require user switching.)
  const respA = await api.functional.prefix.member.postReactions.index(
    connection,
    {
      body: {
        discussionboard_post_id: postXId,
      } satisfies IDiscussionboardPostReaction.IRequest,
    },
  );
