  TestValidator.predicate(
    "Member A does not see Member B's reaction unless permitted",
  )(!respA.data.some((r) => r.discussionboard_member_id === memberBId));

  // 5. As Member B: list all reactions for Post X
  // (Assume connection for Member B authentication)
  const respB = await api.functional.prefix.member.postReactions.index(
    connection,
    {
      body: {
        discussionboard_post_id: postXId,
      } satisfies IDiscussionboardPostReaction.IRequest,
    },
  );
  typia.assert(respB);
  TestValidator.predicate("Member B sees own reaction")(
    respB.data.some((r) => r.discussionboard_member_id === memberBId),
  );
  TestValidator.predicate(
    "Member B does not see Member A's reaction unless permitted",
  )(!respB.data.some((r) => r.discussionboard_member_id === memberAId));

  // 6. As unrelated Member C: list all reactions for Post X
  const respC = await api.functional.prefix.member.postReactions.index(
    connection,
    {
      body: {
        discussionboard_post_id: postXId,
      } satisfies IDiscussionboardPostReaction.IRequest,
    },
  );
  typia.assert(respC);
  TestValidator.equals("Member C reaction list is empty for Post X")(
    respC.data.length,
  )(0);

  // 7. Explicit filtering by member—should return only the correct member’s reactions
  const respAFiltered = await api.functional.prefix.member.postReactions.index(
    connection,
    {
      body: {
        discussionboard_post_id: postXId,
        discussionboard_member_id: memberAId,
      } satisfies IDiscussionboardPostReaction.IRequest,
    },
  );
  typia.assert(respAFiltered);
  TestValidator.predicate("Filtered A: only Member A's reactions")(
    respAFiltered.data.every((r) => r.discussionboard_member_id === memberAId),
  );

  const respBFiltered = await api.functional.prefix.member.postReactions.index(
    connection,
    {
      body: {
        discussionboard_post_id: postXId,
        discussionboard_member_id: memberBId,
      } satisfies IDiscussionboardPostReaction.IRequest,
    },
  );
  typia.assert(respBFiltered);
  TestValidator.predicate("Filtered B: only Member B's reactions")(
    respBFiltered.data.every((r) => r.discussionboard_member_id === memberBId),
  );

  const respCFiltered = await api.functional.prefix.member.postReactions.index(
    connection,
    {
      body: {
        discussionboard_post_id: postXId,
        discussionboard_member_id: memberCId,
      } satisfies IDiscussionboardPostReaction.IRequest,
    },
  );
  typia.assert(respCFiltered);
