  TestValidator.equals("filter correct record")(
    filterList.data[0].search_query,
  )("foo bar one");

  // 4. Check pagination fields (shape)
  TestValidator.predicate("pagination shape")(
    typeof list.pagination.current === "number" &&
      typeof list.pagination.limit === "number",
  );
}

