 * **Note:** Since user registration/login APIs are not included in the provided
 * SDK, this test assumes that test infrastructure can supply connections with
 * different member session contexts (memberA, memberB). No custom
 * authentication helpers or session switching functions are implemented in this
 * scope.
 */
export async function test_api_prefix_member_my_searchHistories_test_get_own_search_history_unauthorized_access(
  connection: api.IConnection,
) {
