  // Create a search history log entry as memberA
  const searchHistoryA =
    await api.functional.prefix.member.my.searchHistories.create(connection, {
      body: {
        search_query: "search by memberA for authorization test",
        executed_at: new Date().toISOString() as string &
          tags.Format<"date-time">,
      } satisfies ISearchHistory.ICreate,
    });
