  const searchHistoryId = searchHistoryA.id;

  // --- STEP 2. Assume: connection is now for memberB (different authenticated member) ---
  // NOTE: The session context must be changed by the test runner/framework to represent memberB.
  // No manual session switching or authentication APIs are present in the SDK.

  // --- STEP 3. As memberB, attempt to fetch memberA's search history ---
  await TestValidator.error(
    "unauthorized access to another member's search history must be rejected",
