import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBan } from "@ORGANIZATION/PROJECT-api/lib/structures/IBan";
import type { IPageIBan } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIBan";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionboardBan } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardBan";

/**
 * Validates that an admin can retrieve a paginated and filtered list of ban
 * records using fields like banned_member_id and banned_guest_id.
 *
 * This test covers the admin workflow for ban management:
 *
 * 1. Creates multiple distinct ban records (members and guests by multiple admins)
 * 2. Retrieves ban list filtering by banned_member_id and verifies correct
 *    record(s)
 * 3. Retrieves ban list filtering by banned_guest_id and verifies
 * 4. Retrieves all bans with no filter
 * 5. Edge case: Filters for nonexistent member (should get empty result)
 *
 * Each step asserts type safety and ensures the API response matches the
 * requested query filters. Pagination is not explicitly tested as IBan.IRequest
 * does not include pagination fields, but IPage.IBan pagination meta is
 * validated implicitly.
 */
export async function test_api_prefix_admin_bans_test_list_bans_with_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Prepare test data: create unique admins, members, guests, and ban records
  const adminId1 = typia.random<string & tags.Format<"uuid">>();
  const adminId2 = typia.random<string & tags.Format<"uuid">>();
  const memberId1 = typia.random<string & tags.Format<"uuid">>();
  const memberId2 = typia.random<string & tags.Format<"uuid">>();
  const guestId1 = typia.random<string & tags.Format<"uuid">>();
  const guestId2 = typia.random<string & tags.Format<"uuid">>();
  const now = new Date().toISOString();

  // Ban: memberId1 by adminId1
  const banMember1 = await api.functional.prefix.admin.bans.create(connection, {
    body: {
      banned_member_id: memberId1,
      banned_guest_id: null,
      admin_id: adminId1,
      ban_reason: "policy breach 1",
      banned_at: now,
      notes: "member ban - 1",
    },
  });
  typia.assert(banMember1);

  // Ban: memberId2 by adminId2
  const banMember2 = await api.functional.prefix.admin.bans.create(connection, {
    body: {
      banned_member_id: memberId2,
      banned_guest_id: null,
      admin_id: adminId2,
      ban_reason: "policy breach 2",
      banned_at: now,
      notes: "member ban - 2",
    },
  });
  typia.assert(banMember2);

  // Ban: guestId1 by adminId1
  const banGuest1 = await api.functional.prefix.admin.bans.create(connection, {
    body: {
      banned_member_id: null,
      banned_guest_id: guestId1,
      admin_id: adminId1,
      ban_reason: "malicious guest 1",
      banned_at: now,
      notes: "guest ban - 1",
    },
  });
  typia.assert(banGuest1);

  // Ban: guestId2 by adminId2
  const banGuest2 = await api.functional.prefix.admin.bans.create(connection, {
    body: {
      banned_member_id: null,
      banned_guest_id: guestId2,
      admin_id: adminId2,
      ban_reason: "malicious guest 2",
      banned_at: now,
      notes: "guest ban - 2",
    },
  });
  typia.assert(banGuest2);

  // 2. Query ban records by banned_member_id (memberId1)
  const member1List = await api.functional.prefix.admin.bans.index(connection, {
    body: {
      banned_member_id: memberId1,
    },
  });
  typia.assert(member1List);
  TestValidator.predicate("filters by banned_member_id")(
    member1List.data.every((r) => r.banned_member_id === memberId1),
  );
  TestValidator.equals("single member ban")(member1List.data.length)(1);

  // 3. Query ban records by banned_guest_id (guestId1)
  const guest1List = await api.functional.prefix.admin.bans.index(connection, {
    body: {
      banned_guest_id: guestId1,
    },
  });
  typia.assert(guest1List);
  TestValidator.predicate("filters by banned_guest_id")(
    guest1List.data.every((r) => r.banned_guest_id === guestId1),
  );
  TestValidator.equals("single guest ban")(guest1List.data.length)(1);

  // 4. Retrieve all bans (no filter)
  const allBans = await api.functional.prefix.admin.bans.index(connection, {
    body: {},
  });
  typia.assert(allBans);
  TestValidator.predicate("returns all bans")(allBans.data.length >= 4);

  // 5. Edge case: filter by unknown memberId (should be empty)
  const notExistsList = await api.functional.prefix.admin.bans.index(
    connection,
    {
      body: {
        banned_member_id: typia.random<string & tags.Format<"uuid">>(),
      },
    },
  );
  typia.assert(notExistsList);
  TestValidator.equals("empty for unknown member")(notExistsList.data.length)(
    0,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
