import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionboardBan } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardBan";

/**
 * Validates that listing bans using filter criteria that match no records
 * returns an empty result set.
 *
 * This test ensures that the ban listing endpoint returns an empty list when
 * queried with filters that have no matching entries, thus demonstrating robust
 * filtering logic and search boundaries.
 *
 * Steps:
 *
 * 1. Create a known ban record via the admin create endpoint to guarantee the
 *    system is populated and to prove the filter really works (not trivially
 *    empty).
 * 2. Query the bans index endpoint using filter criteria guaranteed not to match
 *    any existing record (e.g., use a random UUID for banned_member_id, or a
 *    fake ban reason).
 * 3. Validate that the paged result has zero data entries (i.e., data array is
 *    empty and the pagination metadata confirms zero records).
 */
export async function test_api_prefix_admin_bans_test_list_bans_returns_empty_on_no_match(
  connection: api.IConnection,
) {
  // 1. Create a known ban to guarantee non-empty state
  const banAdminId = typia.random<string & tags.Format<"uuid">>();
  const banMemberId = typia.random<string & tags.Format<"uuid">>();
  const createBanBody = {
    banned_member_id: banMemberId,
    banned_guest_id: null,
    admin_id: banAdminId,
    ban_reason: "policy violation",
    banned_at: new Date().toISOString(),
    notes: "Initial test ban.",
  } satisfies IDiscussionboardBan.ICreate;
  const createdBan = await api.functional.prefix.admin.bans.create(connection, {
    body: createBanBody,
  });
  typia.assert(createdBan);

  // 2. Query with non-matching banned_member_id
  let nonMatchingMemberId = typia.random<string & tags.Format<"uuid">>();
  // ensure it's not the same as banMemberId
  while (nonMatchingMemberId === banMemberId) {
    nonMatchingMemberId = typia.random<string & tags.Format<"uuid">>();
  }
  const filterBody = {
    banned_member_id: nonMatchingMemberId,
  } satisfies IBan.IRequest;
  const listResult = await api.functional.prefix.admin.bans.index(connection, {
    body: filterBody,
  });
  typia.assert(listResult);

  // 3. Validate no results
  TestValidator.equals("no matched records")(listResult.data.length)(0);
  TestValidator.equals("pagination.records is 0")(
    listResult.pagination.records,
  )(0);
  TestValidator.equals("pagination.pages is 0")(listResult.pagination.pages)(0);
}

