export async function test_api_prefix_admin_policyAudit_incidentReports_test_update_incident_report_successfully(
  connection: api.IConnection,
) {
  // 1. Create a new incident report as preparation
  const initial: IDiscussionboardIncidentReport =
    await api.functional.prefix.admin.policyAudit.incidentReports.create(
      connection,
      {
        body: {
          incident_code: `INCIDENT-${new Date()
            .toISOString()
            .replace(/[-:TZ.]/g, "")
            .substring(0, 15)}`,
          status: "OPEN",
          reporter_id: typia.random<string & tags.Format<"uuid">>(),
