/**
 * 자신이 소유한 moderation action 레코드를 스키마에서 허용된 필드(action_description, action_type,
 * affected_post_id, affected_member_id, action_timestamp)로만 정상적으로 업데이트 할 수 있는지
 * 검증합니다.
 *
 * 이 테스트는 다음 절차를 따릅니다:
 *
 * 1. 관리자가 테스트용 모더레이터 역할을 부여합니다.
 * 2. 해당 모더레이터가 moderation action을 생성합니다.
 * 3. 해당 액션 id로 action_description, action_type, affected_post_id,
 *    affected_member_id, action_timestamp만 포함한 업데이트를 실행합니다.
 * 4. 응답값이 갱신 payload와 일치하는지, 변경 전과 다른지 검사합니다.
 */
export async function test_api_moderationActions_test_update_own_moderation_action_with_valid_fields(
  connection: api.IConnection,
) {
  // 1. 관리자가 새로운 모더레이터 역할을 부여
  const moderatorId: string = typia.random<string & tags.Format<"uuid">>();
  const assignedModerator =
    await api.functional.prefix.admin.actors.moderators.create(connection, {
      body: {
        id: moderatorId,
        created_at: new Date().toISOString() as string &
          tags.Format<"date-time">,
      },
    });
  typia.assert(assignedModerator);

  // 2. 모더레이터가 moderation action을 생성
  const originalModerationAction =
    await api.functional.prefix.moderator.moderationActions.create(connection, {
      body: {
        moderator_id: moderatorId,
        action_type: "warned",
        action_description: "초기 경고 내역",
        action_timestamp: new Date().toISOString() as string &
          tags.Format<"date-time">,
        affected_post_id: typia.random<string & tags.Format<"uuid">>(),
        affected_member_id: typia.random<string & tags.Format<"uuid">>(),
      },
    });
  typia.assert(originalModerationAction);

  // 3. moderation action의 허용 필드만 포함해 업데이트 요청
  const updatedFields = {
    action_description: "불건전 게시글 삭제 처리",
    action_type: "deleted_post",
    affected_post_id: typia.random<string & tags.Format<"uuid">>(),
    affected_member_id: typia.random<string & tags.Format<"uuid">>(),
    action_timestamp: new Date(Date.now() + 1000 * 60).toISOString() as string &
      tags.Format<"date-time">,
  };
  const updatedModerationAction =
    await api.functional.prefix.moderator.my.moderationActions.update(
      connection,
      {
        id: originalModerationAction.id,
        body: updatedFields,
      },
    );
  typia.assert(updatedModerationAction);

  // 4. 응답값이 업데이트 요청값과 정확히 일치하는지 확인
  TestValidator.equals("action_description")(
    updatedModerationAction.action_description,
  )(updatedFields.action_description);
  TestValidator.equals("action_type")(updatedModerationAction.action_type)(
    updatedFields.action_type,
  );
  TestValidator.equals("affected_post_id")(
    updatedModerationAction.affected_post_id,
  )(updatedFields.affected_post_id);
  TestValidator.equals("affected_member_id")(
    updatedModerationAction.affected_member_id,
  )(updatedFields.affected_member_id);
  TestValidator.equals("action_timestamp")(
    updatedModerationAction.action_timestamp,
  )(updatedFields.action_timestamp);

  // 변경 전 데이터와 달라졌는지도 검사
  TestValidator.notEquals("action_type 변경됨")(
    updatedModerationAction.action_type,
  )(originalModerationAction.action_type);
  TestValidator.notEquals("action_description 변경됨")(
    updatedModerationAction.action_description,
  )(originalModerationAction.action_description);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardModerator";
import type { IModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IModerationAction";

/**
 * Validate that attempting to update a moderation action with forbidden
 * (non-schema) fields is rejected, and that no data corruption occurs.
 *
 * Scenario:
 *
 * - First, assign the current session a moderator role (prerequisite for owning
 *   moderation actions).
 * - Then, create a valid moderation action using only allowed schema fields (as
 *   preparation for the update).
 * - Try updating this moderation action using the update endpoint, but with extra
 *   forbidden fields (such as a made-up property, or an attempt to change the
 *   id).
 *
 * Test Steps:
 *
 * 1. Assign moderator role (so this session can own moderation actions).
 * 2. Create and store a moderation action (using only allowed schema fields so
 *    it's valid).
 * 3. Attempt to update this moderation action, but deliberately add
 *    forbidden/non-schema fields (e.g., a fake property not in
 *    IModerationAction.IUpdate, or a top-level 'id' property to try changing
 *    id).
 * 4. Assert that the update is rejected with a schema validation error, and no
 *    data or id change occurred.
 * 5. Optionally, ensure the moderation action remains unchanged (e.g., by
 *    attempting to retrieve it if a relevant retrieve endpoint exists; omit if
 *    not possible).
 *
