/**
 * Verify the warning log filtering returns empty results on no matches.
 *
 * This test ensures that when a search is performed on the warning log listing
 * endpoint with filter criteria that do not match any database records (such as
 * a non-existent warned_member_id and a warning_reason string absent in all
 * entries), the API responds correctly with an empty data set (not an error).
 * This is important for user experience, robustness, and API predictability.
 *
 * Step-by-step process:
 *
 * 1. Assign a moderator role using the admin endpoint, simulating giving a
 *    moderator permission to a random member UUID.
 * 2. Create at least one warning log with a "realistic" reason and
 *    warned_member_id so the table is non-empty.
 * 3. Search/list warning logs filtering with a nonsense warned_member_id and a
 *    unique warning_reason string not present in any entry.
 *
 *    - Assert that the returned data list is empty.
 * 4. Additionally, test each filter (reason, member ID) separately, to ensure no
 *    partial matches accidentally pass.
 */
export async function test_api_prefix_test_list_warning_logs_with_no_results(
  connection: api.IConnection,
) {
  // 1. Assign moderator role using admin endpoint
  const moderator_id: string = typia.random<string & tags.Format<"uuid">>();
  const created_at: string = new Date().toISOString();
  const moderator = await api.functional.prefix.admin.actors.moderators.create(
    connection,
    {
      body: {
        id: moderator_id,
        created_at: created_at,
      } satisfies IDiscussionboardModerator.ICreate,
    },
  );
  typia.assert(moderator);

  // 2. Create an actual warning log (so that the warning log system is not empty)
  const warned_member_id_in_db: string = typia.random<
    string & tags.Format<"uuid">
  >();
  const warning_reason_in_db = "test-warning-present";
  const warningLog = await api.functional.prefix.moderator.warningLogs.create(
    connection,
    {
      body: {
        moderator_id,
        warned_member_id: warned_member_id_in_db,
        warning_reason: warning_reason_in_db,
        issued_at: new Date().toISOString(),
      } satisfies IWarningLog.ICreate,
    },
  );
  typia.assert(warningLog);

  // 3. Try to search for logs with both a member_id and a reason string that are not present
  const no_match_warned_member_id = typia.random<
    string & tags.Format<"uuid">
  >();
  const no_match_reason = "no-matching-reason-string-unique";
  const page = await api.functional.prefix.moderator.warningLogs.index(
    connection,
    {
      body: {
        warned_member_id: no_match_warned_member_id,
        warning_reason: no_match_reason,
        page: 1,
        limit: 10,
      } satisfies IWarningLog.IRequest,
    },
  );
  typia.assert(page);
  TestValidator.equals("No results when both filters do not match")(
    page.data.length,
  )(0);

  // 4. Search using only unmatched reason
  const page2 = await api.functional.prefix.moderator.warningLogs.index(
    connection,
    {
      body: {
        warning_reason: no_match_reason,
        page: 1,
        limit: 10,
      } satisfies IWarningLog.IRequest,
    },
  );
  typia.assert(page2);
  TestValidator.equals("No results when only reason is unmatched")(
    page2.data.length,
  )(0);

  // 5. Search using only unmatched warned_member_id
  const page3 = await api.functional.prefix.moderator.warningLogs.index(
    connection,
    {
      body: {
        warned_member_id: no_match_warned_member_id,
        page: 1,
        limit: 10,
      } satisfies IWarningLog.IRequest,
    },
  );
  typia.assert(page3);
  TestValidator.equals("No results when only warned_member_id is unmatched")(
    page3.data.length,
  )(0);
}

