 *
 * Steps:
 *
 * 1. Generate a random UUID not matching any real policy.
 * 2. Attempt to delete the policy via the admin endpoint.
 * 3. Assert that a 404 or similar error is returned, confirming correct handling
 *    of missing resource requests.
 */
export async function test_api_prefix_admin_policyAudit_platformPolicies_test_delete_platform_policy_with_nonexistent_id(
