  // Check fields of returned audit log records
  if (responseDefault.data.length > 0) {
    for (const log of responseDefault.data) {
      TestValidator.predicate("audit log id is uuid-like")(
        typeof log.id === "string" && /[0-9a-fA-F-]{36}/.test(log.id),
      );
      TestValidator.predicate("action_type is present and string")(
        typeof log.action_type === "string",
      );
      TestValidator.predicate("description is present and string")(
        typeof log.description === "string",
      );
      TestValidator.predicate("created_at is date-time string")(
        typeof log.created_at === "string" && /T/.test(log.created_at),
      );
      TestValidator.predicate("actor_id and target_id fields optional or null")(
        !("actor_id" in log) ||
          log.actor_id === null ||
          typeof log.actor_id === "string",
      );
      TestValidator.predicate("actor_id and target_id fields optional or null")(
        !("target_id" in log) ||
          log.target_id === null ||
          typeof log.target_id === "string",
      );
