 * API.
 *
 * This test ensures that system admins can retrieve lists of incident reports:
 *
 * - Unfiltered (default page, all entries)
 * - With various filters: by status, code, reporter, date range, or keyword
 *   (description)
 * - Using pagination controls (page/limit)
 *
 * Each query must return only matching records, with valid pagination
 * structures and fields. The incident report schema details (id, status, code,
 * reporter, etc.) must be adhered to for all returned records.
 *
 * Steps:
 *
 * 1. Call with empty filter (default retrieves some records and valid pagination)
 * 2. Call with each filter separately: status, incident_code, reporter_id,
 *    keyword, created_from/to
 * 3. Call with pagination (page/limit) and verify data structure/field values For
 *    each, validate that only matching records are returned and pagination is
 *    consistent.
 */
export async function test_api_prefix_admin_policyAudit_incidentReports_index(
  connection: api.IConnection,
) {
  // 1. Retrieve first page with no filters
  const allReports =
    await api.functional.prefix.admin.policyAudit.incidentReports.index(
      connection,
      {
        body: {},
      },
    );
  typia.assert(allReports);
  TestValidator.predicate("at least 0 records")(allReports.data.length >= 0);

  // Helper to fetch with a filter and basic assertion
  async function filterAndCheck(
    body: Partial<IDiscussionboardIncidentReport.IRequest>,
    check: (item: IDiscussionboardIncidentReport) => boolean,
  ) {
    const resp =
      await api.functional.prefix.admin.policyAudit.incidentReports.index(
        connection,
        { body },
      );
    typia.assert(resp);
    for (const item of resp.data) {
      TestValidator.predicate("filter matches")(check(item));
    }
    // Confirm pagination is always present and valid
    typia.assert(resp.pagination);
  }

  // 2. Filter: status
  await filterAndCheck({ status: "OPEN" }, (r) => r.status === "OPEN");

  // 3. Filter: incident_code
  const codeSample = allReports.data[0]?.incident_code;
  if (codeSample) {
    await filterAndCheck(
      { incident_code: codeSample },
      (r) => r.incident_code === codeSample,
    );
  }

  // 4. Filter: reporter_id
  const reporterId = allReports.data.find((r) => !!r.reporter_id)?.reporter_id;
  if (reporterId) {
    await filterAndCheck(
      { reporter_id: reporterId },
      (r) => r.reporter_id === reporterId,
    );
  }

  // 5. Filter: keyword (description)
  const descriptionKeyword = allReports.data[0]?.description?.split(" ")[0];
  if (descriptionKeyword) {
    await filterAndCheck({ keyword: descriptionKeyword }, (r) =>
      r.description.includes(descriptionKeyword),
    );
  }

  // 6. Filter: created_at range
  const createdFrom = allReports.data[0]?.created_at;
  if (createdFrom) {
    await filterAndCheck(
      { created_from: createdFrom, created_to: createdFrom },
      (r) => r.created_at === createdFrom,
    );
  }

  // 7. Pagination check (page/limit), only if multiple records exist
  if (allReports.pagination.records > allReports.pagination.limit) {
    const secondPage =
      await api.functional.prefix.admin.policyAudit.incidentReports.index(
        connection,
        {
          body: { page: 2, limit: allReports.pagination.limit },
        },
      );
    typia.assert(secondPage);
    TestValidator.equals("correct page")(secondPage.pagination.current)(2);
    TestValidator.equals("correct limit")(secondPage.pagination.limit)(
      allReports.pagination.limit,
    );
    // Data non-overlap check (optional if ids are unique)
    if (allReports.data.length && secondPage.data.length) {
      TestValidator.notEquals("no overlap between pages")(
        allReports.data[0].id,
      )(secondPage.data[0].id);
    }
  }
}

