import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 보안 검증: 잘못된 세션(만료, 조작, 철회)으로 모더레이터의 인시던트 리포트 목록 요청 시 접근 거부 확인
 *
 * 이 테스트 함수는 시스템 내 모더레이터 정책 감찰(incident report) 목록 엔드포인트가 존재하더라도, 세션이 조작되거나,
 * 만료되거나, 철회된 경우(Authorization 헤더가 잘못된 경우)에 민감한 인시던트 데이터 접근이 차단되는 보안을 보장함을
 * 검증합니다.
 *
 * 1. 명백하게 잘못된 Authorization 헤더(예: 'Bearer INVALIDTOKEN')를 지닌 connection으로 정책감찰
 *    incident report 목록 엔드포인트(
 *    api.functional.prefix.moderator.policyAudit.incidentReports.index)를
 *    호출합니다.
 * 2. 바디는 어떻게든 유효한 IDiscussionboardIncidentReport.IRequest 랜덤 값으로 제공합니다.
 * 3. 해당 요청은 인증 실패(Unauthorized/Session expired)로 반드시 실패해야 하므로,
 *    TestValidator.error("should block invalid session")()으로 오류 발생을 검증합니다.
 * 4. 복수의 오류 유형(아예 Authorization 없음, 명백히 만료된 값, 무효한 토큰)도 반복 검증 가능합니다.
 *
 * 별도의 데이터 생성이나 의존 단계 없이, 순수하게 접근 거부 보안 로직만을 검증하는 테스트입니다.
 */
export async function test_api_prefix_moderator_policyAudit_incidentReports_index_invalid_session(
  connection: api.IConnection,
) {
  // 1. 명백히 무효한 Authorization 헤더로 보안 우회 시도
  const invalidConnection: api.IConnection = {
    ...connection,
    headers: {
      ...(connection.headers ?? {}),
      Authorization: "Bearer INVALIDTOKEN",
    },
  };

  // 2. 랜덤한 (유효 구조이나 데이터 값 상관 없는) 검색 바디
  const body: IDiscussionboardIncidentReport.IRequest =
    typia.random<IDiscussionboardIncidentReport.IRequest>();

  // 3. 요청 시 반드시 인증 오류가 발생해야 함을 보장
  await TestValidator.error("should block invalid session")(() =>
    api.functional.prefix.moderator.policyAudit.incidentReports.index(
      invalidConnection,
      { body },
    ),
  );

  // 4. (선택) Authorization header 누락 케이스도 추가 검증
  const noAuthConnection: api.IConnection = {
    ...connection,
    headers: {
      ...(connection.headers ?? {}),
    }, // Authorization 아예 없음
  };
  await TestValidator.error("should block session if Authorization missing")(
    () =>
      api.functional.prefix.moderator.policyAudit.incidentReports.index(
        noAuthConnection,
        { body: typia.random<IDiscussionboardIncidentReport.IRequest>() },
      ),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
