import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardIncidentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardIncidentReport";

/**
 * Test that a moderator can successfully update an incident report.
 *
 * Business context: Moderators need to manage policy/compliance incident
 * reports in audit workflow. This test verifies that a moderator can update
 * incident reports, but only allowed fields (according to schema), and that
 * immutable fields cannot be changed via the API.
 *
 * Steps:
 *
 * 1. Create a new incident report using valid DTO as a moderator
 * 2. Update the incident report's allowed fields (incident_code, status,
 *    reporter_id, description, updated_at)
 * 3. Assert API response matches the updated values in allowed fields and
 *    immutable fields remain unmodified
 */
export async function test_api_incidentReports_test_update_incident_report_success_by_moderator(
  connection: api.IConnection,
) {
  // 1. Create a new incident report as a moderator (prerequisite)
  const createInput: IDiscussionboardIncidentReport.ICreate = {
    incident_code: `INCIDENT-${new Date().toISOString().slice(0, 10).replace(/-/g, "")}-001`,
    status: "OPEN",
    reporter_id: null, // Not specified (anonymous)
    description: "Test incident for update flow.",
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString(),
  };
  const created: IDiscussionboardIncidentReport =
    await api.functional.prefix.moderator.policyAudit.incidentReports.create(
      connection,
      { body: createInput },
    );
  typia.assert(created);

  // 2. Update all allowed fields of the incident report
  const updateInput: IDiscussionboardIncidentReport.IUpdate = {
    incident_code: `${createInput.incident_code}-REV1`,
    status: "IN_REVIEW",
    reporter_id: typia.random<string & tags.Format<"uuid">>(),
    description: "Updated description for incident workflow.",
    updated_at: new Date(Date.now() + 60 * 1000).toISOString(), // +1 minute
  };
  const updated: IDiscussionboardIncidentReport =
    await api.functional.prefix.moderator.policyAudit.incidentReports.update(
      connection,
      {
        incidentReportId: created.id,
        body: updateInput,
      },
    );
  typia.assert(updated);

  // 3. Assert only allowed mutable fields have changed
  TestValidator.equals("incident_code updated")(updated.incident_code)(
    updateInput.incident_code,
  );
  TestValidator.equals("status updated")(updated.status)(updateInput.status);
  TestValidator.equals("reporter_id updated")(updated.reporter_id)(
    updateInput.reporter_id,
  );
  TestValidator.equals("description updated")(updated.description)(
    updateInput.description,
  );
  TestValidator.equals("updated_at updated")(updated.updated_at)(
    updateInput.updated_at,
  );

  // Assertion: created_at (immutable) must remain unchanged
  TestValidator.equals("created_at should remain unchanged")(
    updated.created_at,
  )(created.created_at);
}

