import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardAppeal } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardAppeal";
import type { IPageIDiscussionboardAppeal } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardAppeal";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate admin listing/searching for policy audit appeals using advanced
 * filters, sorting, and pagination.
 *
 * This test does the following:
 *
 * 1. Creates a diverse set of appeals with different combinations of status,
 *    outcome, appellant_id, and created_at values.
 * 2. Tests searching/filtering on admin appeals index endpoint using:
 *
 *    - By specific status value (should only return matching status)
 *    - By appellant_id (should only return appeals linked to that appellant)
 *    - By created_at date range (results should be within specified interval)
 *    - Combining multiple filters (results should honor ALL criteria)
 *    - Pagination (change limit/page, validate page results/record counts, ensure no
 *         cross-page leaks)
 *    - Sorting (sort_by created_at ascending/descending)
 * 3. For each query, validates that only matching appeals are returned, with
 *    proper pagination/sorting.
 * 4. Edge cases: combine filters that exclude all (empty result), use limits
 *    larger than data set, request pages out of bounds.
 *
 * Note: Filtering by 'outcome' was described in the scenario, but this is NOT
 * possible per the IRequest schema and is therefore omitted.
 */
export async function test_api_prefix_admin_policyAudit_appeals_test_search_appeals_admin_role_with_various_filters(
  connection: api.IConnection,
) {
  // 1. Data setup: create appeals with diverse properties
  //  - status: 'PENDING', 'IN_REVIEW', 'UPHELD', 'REJECTED'
  //  - outcome: 'Ban lifted', 'Suspension upheld', 'Warning removed', 'No action'
  //  - appellant_id: 3-4 different UUIDs, some null
  //  - created_at: varying over a range
  const statuses = ["PENDING", "IN_REVIEW", "UPHELD", "REJECTED"];
  const outcomes = [
    "Ban lifted",
    "Suspension upheld",
    "Warning removed",
    "No action",
  ];
  const appellantIds = [
    typia.random<string & tags.Format<"uuid">>(),
    typia.random<string & tags.Format<"uuid">>(),
    typia.random<string & tags.Format<"uuid">>(),
    null,
  ];
  const totalRecords = 12;
  const now = new Date();
  const baseDate = new Date(now.getTime() - 10 * 24 * 60 * 60 * 1000); // 10 days ago
  const createdAppeals: IDiscussionboardAppeal[] = [];
  for (let i = 0; i < totalRecords; ++i) {
    const created_at = new Date(
      baseDate.getTime() + i * 12 * 60 * 60 * 1000,
    ).toISOString(); // Spread created_at times
    const updated_at = created_at;
    const status = statuses[i % statuses.length];
    const outcome = outcomes[i % outcomes.length];
    const appellant_id = appellantIds[i % appellantIds.length];
    const appeal = await api.functional.prefix.admin.policyAudit.appeals.create(
      connection,
      {
        body: {
          appeal_code: `APPEAL-${now.getFullYear()}${(now.getMonth() + 1).toString().padStart(2, "0")}${now.getDate().toString().padStart(2, "0")}-${(1000 + i).toString().padStart(3, "0")}`,
          status,
          appellant_id,
          incident_id: null,
          outcome,
          created_at,
          updated_at,
        } satisfies IDiscussionboardAppeal.ICreate,
      },
    );
    typia.assert(appeal);
    createdAppeals.push(appeal);
  }

  // 2. Filter: status
  const targetStatus = statuses[1];
  const statusRes = await api.functional.prefix.admin.policyAudit.appeals.index(
    connection,
    {
      body: { status: targetStatus } satisfies IDiscussionboardAppeal.IRequest,
    },
  );
  typia.assert(statusRes);
  TestValidator.predicate("status filter - all have correct status")(
    statusRes.data.every((a) => a.status === targetStatus),
  );
  for (const a of statusRes.data) {
    TestValidator.equals("status matches filter")(a.status)(targetStatus);
  }

  // 3. Filter: appellant_id
  const targetAppellant = appellantIds[0];
  const appellantRes =
    await api.functional.prefix.admin.policyAudit.appeals.index(connection, {
      body: {
        appellant_id: targetAppellant,
      } satisfies IDiscussionboardAppeal.IRequest,
    });
  typia.assert(appellantRes);
  TestValidator.predicate("appellant filter - all correct")(
    appellantRes.data.every((a) => a.appellant_id === targetAppellant),
  );
  for (const a of appellantRes.data) {
    TestValidator.equals("appellant_id matches")(a.appellant_id)(
      targetAppellant,
    );
  }

  // 4. Filter: created_at range
  const middleDate = new Date(
    baseDate.getTime() + 5 * 12 * 60 * 60 * 1000,
  ).toISOString();
  const afterRes = await api.functional.prefix.admin.policyAudit.appeals.index(
    connection,
    {
      body: {
        created_after: middleDate as string & tags.Format<"date-time">,
      } satisfies IDiscussionboardAppeal.IRequest,
    },
  );
  typia.assert(afterRes);
  TestValidator.predicate("created_after filter - all records after")(
    afterRes.data.every((a) => a.created_at > middleDate),
  );

  // 5. Pagination/limit
  const limitNum = 3;
  const pagedRes = await api.functional.prefix.admin.policyAudit.appeals.index(
    connection,
    {
      body: { limit: limitNum } satisfies IDiscussionboardAppeal.IRequest,
    },
  );
  typia.assert(pagedRes);
  TestValidator.equals("pagination limits count")(pagedRes.data.length)(
    Math.min(limitNum, totalRecords),
  );

  // 6. Page bounds out of range (should return empty data)
  const outOfBoundsPage = 1000;
  const oobRes = await api.functional.prefix.admin.policyAudit.appeals.index(
    connection,
    {
      body: {
        page: outOfBoundsPage,
        limit: 5,
      } satisfies IDiscussionboardAppeal.IRequest,
    },
  );
  typia.assert(oobRes);
  TestValidator.equals("out-of-bounds page gives empty")(oobRes.data.length)(0);

  // 7. Sort: created_at descending
  const sortRes = await api.functional.prefix.admin.policyAudit.appeals.index(
    connection,
    {
      body: {
        sort_by: "created_at",
        sort_direction: "desc",
        limit: 10,
      } satisfies IDiscussionboardAppeal.IRequest,
    },
  );
  typia.assert(sortRes);
  TestValidator.predicate("sorted desc by created_at")(
    sortRes.data.every(
      (a, i, arr) => i === 0 || a.created_at <= arr[i - 1].created_at,
    ),
  );

  // 8. Filter: status + appellant_id (AND logic)
  const multiRes = await api.functional.prefix.admin.policyAudit.appeals.index(
    connection,
    {
      body: {
        status: statuses[0],
        appellant_id: appellantIds[0],
      } satisfies IDiscussionboardAppeal.IRequest,
    },
  );
  typia.assert(multiRes);
  TestValidator.predicate(
    "multi filter matched only those with status and appellant",
  )(
    multiRes.data.every(
      (a) => a.status === statuses[0] && a.appellant_id === appellantIds[0],
    ),
  );

  // 9. Date range yields empty when out of bounds
  const farFuture = new Date(
    now.getTime() + 365 * 24 * 60 * 60 * 1000,
  ).toISOString();
  const emptyRangeRes =
    await api.functional.prefix.admin.policyAudit.appeals.index(connection, {
      body: {
        created_after: farFuture as string & tags.Format<"date-time">,
        created_before: farFuture as string & tags.Format<"date-time">,
      } satisfies IDiscussionboardAppeal.IRequest,
    });
  typia.assert(emptyRangeRes);
  TestValidator.equals("date range with no records")(emptyRangeRes.data.length)(
    0,
  );
}

