import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { discussionboard_notifications } from "@ORGANIZATION/PROJECT-api/lib/structures/discussionboard_notifications";
import type { IPageDiscussionboardNotifications } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageDiscussionboardNotifications";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate the retrieval (search/paginated listing) of discussion board
 * notifications for an authenticated member.
 *
 * This test verifies that notifications can be created and retrieved with
 * various filtering and pagination settings, ensuring response correctness,
 * filter compliance, strict result ownership, and pagination metadata.
 *
 * Steps:
 *
 * 1. Assume connection is authenticated as test member.
 * 2. Create multiple distinct notifications (types, opened states).
 * 3. List notifications (no filters): verify all returned are owned by this
 *    member.
 * 4. List with filter: type (e.g., 'mention').
 * 5. List with filter: opened = true / false.
 * 6. List with pagination (limit/page), validate record slicing and meta.
 * 7. (If applicable) On page 2, verify correct continuing slice.
 * 8. All assertions provide clear description context for easy debugging.
 * 9. Conclude with summary of verification.
 */
export async function test_api_prefix_member_my_discussionboardNotifications_test_list_member_notifications_success(
  connection: api.IConnection,
) {
  // Step 1: Assume connection is authenticated as test member

  // Step 2: Create multiple notifications with variants in type, title, opened
  const types = ["mention", "moderator_action", "announcement", "reply"];
  const notifications: discussionboard_notifications[] = [];
  for (let i = 0; i < 7; ++i) {
    const notif =
      await api.functional.prefix.member.my.discussionboardNotifications.create(
        connection,
        {
          body: {
            type: types[i % types.length],
            title: `Test Notification ${i + 1}`,
            body: i % 2 === 0 ? `Content body ${i + 1}` : undefined,
            url: i % 3 === 0 ? `/thread/${i}/post/${100 + i}` : undefined,
            opened: i % 2 === 0,
          } satisfies discussionboard_notifications.ICreate,
        },
      );
    typia.assert(notif);
    notifications.push(notif);
  }
  const memberId = notifications[0].discussionboard_member_id;

  // Step 3: List notifications: no filters
  const resAll =
    await api.functional.prefix.member.my.discussionboardNotifications.index(
      connection,
      {
        body: {},
      },
    );
  typia.assert(resAll);
  resAll.data.forEach((n, idx) => {
    TestValidator.equals(`[all][ownership][notification #${idx}]`)(
      n.discussionboard_member_id,
    )(memberId);
  });

  // Step 4: List with filter: type = 'mention'
  const resType =
    await api.functional.prefix.member.my.discussionboardNotifications.index(
      connection,
      {
        body: { type: "mention" },
      },
    );
  typia.assert(resType);
  resType.data.forEach((n, idx) => {
    TestValidator.equals(`[type=mention][type][notification #${idx}]`)(n.type)(
      "mention",
    );
    TestValidator.equals(`[type=mention][ownership][notification #${idx}]`)(
      n.discussionboard_member_id,
    )(memberId);
  });

  // Step 5: List with opened = true
  const resOpened =
    await api.functional.prefix.member.my.discussionboardNotifications.index(
      connection,
      {
        body: { opened: true },
      },
    );
  typia.assert(resOpened);
  resOpened.data.forEach((n, idx) => {
    TestValidator.equals(`[opened=true][opened][notification #${idx}]`)(
      n.opened,
    )(true);
    TestValidator.equals(`[opened=true][ownership][notification #${idx}]`)(
      n.discussionboard_member_id,
    )(memberId);
  });

  // Step 5b: List with opened = false
  const resUnopened =
    await api.functional.prefix.member.my.discussionboardNotifications.index(
      connection,
      {
        body: { opened: false },
      },
    );
  typia.assert(resUnopened);
  resUnopened.data.forEach((n, idx) => {
    TestValidator.equals(`[opened=false][opened][notification #${idx}]`)(
      n.opened,
    )(false);
    TestValidator.equals(`[opened=false][ownership][notification #${idx}]`)(
      n.discussionboard_member_id,
    )(memberId);
  });

  // Step 6: Paginated - limit/page
  const limit = 3;
  const page1 = 1;
  const resPag1 =
    await api.functional.prefix.member.my.discussionboardNotifications.index(
      connection,
      {
        body: { limit, page: page1 },
      },
    );
  typia.assert(resPag1);
  TestValidator.equals(`[page=1][count]`)(resPag1.data.length)(
    Math.min(limit, notifications.length),
  );
  TestValidator.equals(`[page=1][meta:limit]`)(resPag1.pagination.limit)(limit);
  resPag1.data.forEach((n, idx) => {
    TestValidator.equals(`[page=1][ownership][notification #${idx}]`)(
      n.discussionboard_member_id,
    )(memberId);
  });

  // Step 7: Page 2 (if enough notifications)
  if (notifications.length > limit) {
    const page2 = 2;
    const resPag2 =
      await api.functional.prefix.member.my.discussionboardNotifications.index(
        connection,
        {
          body: { limit, page: page2 },
        },
      );
    typia.assert(resPag2);
    TestValidator.equals(`[page=2][meta:limit]`)(resPag2.pagination.limit)(
      limit,
    );
    resPag2.data.forEach((n, idx) => {
      TestValidator.equals(`[page=2][ownership][notification #${idx}]`)(
        n.discussionboard_member_id,
      )(memberId);
    });
    // Optionally check title sequence for slice continuity
    const expectedTitles = notifications
      .slice(limit, limit * 2)
      .map((x) => x.title);
    resPag2.data.forEach((n, idx) => {
      TestValidator.equals(`[page=2][title][notification #${idx}]`)(n.title)(
        expectedTitles[idx],
      );
    });
  }

  // Step 8: Conclude
  // All retrievals validated for ownership, filter, and pagination compliance. No cross-member leakage.
}

