/**
 * Test advanced filtering and searching of notifications for the authenticated
 * member.
 *
 * This E2E test verifies that when the user requests their notifications list
 * with various filtering and search parameters—such as type, opened status, and
 * keyword search in title—the API correctly returns only notifications matching
 * those criteria. The test ensures all supported filters are honored and the
 * responses are type-safe and correct.
 *
 * Steps:
 *
 * 1. Create three notifications with distinct 'type', 'opened' status, and titles.
 *
 *    - Types: "mention", "moderator_action", "announcement"
 *    - Titles contain unique keywords for clear substring filtering.
 *    - Opened status is varied.
 * 2. Filter notifications by type ('mention') and ensure only that notification is
 *    returned.
 * 3. Filter notifications by opened=true and verify only opened notifications are
 *    returned.
 * 4. Search by a substring in the title and check only relevant notifications are
 *    returned.
 * 5. Combine type and opened filters to test AND-filtering (e.g.,
 *    type="moderator_action" & opened=true).
 * 6. Assert type safety and correct business filtering throughout.
 */
export async function test_api_prefix_member_my_discussionboardNotifications_test_list_notifications_filter_and_search(
  connection: api.IConnection,
) {
  // Step 1: Create three notifications with varied values
  const notifMention =
    await api.functional.prefix.member.my.discussionboardNotifications.create(
      connection,
      {
        body: {
          type: "mention",
          title: "Mentioned in a post - UniqueABC",
          opened: false,
        },
      },
    );
  typia.assert(notifMention);
  const notifModerator =
    await api.functional.prefix.member.my.discussionboardNotifications.create(
      connection,
      {
        body: {
          type: "moderator_action",
          title: "Moderator flag - UniqueXYZ",
          opened: true,
        },
      },
    );
  typia.assert(notifModerator);
  const notifAnnouncement =
    await api.functional.prefix.member.my.discussionboardNotifications.create(
      connection,
      {
        body: {
          type: "announcement",
          title: "Forum wide update - UniqueHELLO",
          opened: false,
        },
      },
    );
  typia.assert(notifAnnouncement);

  // Step 2: Filter by type (should return only the 'mention' notification)
  const filterByType =
    await api.functional.prefix.member.my.discussionboardNotifications.index(
      connection,
      {
        body: { type: "mention" },
      },
    );
  typia.assert(filterByType);
  TestValidator.predicate("type filter: returns only 'mention' notifications")(
    filterByType.data.every((n) => n.type === "mention") &&
      filterByType.data.some((n) => n.id === notifMention.id),
  );
  TestValidator.predicate("type filter: does not return others")(
    filterByType.data.every((n) => n.id === notifMention.id),
  );

  // Step 3: Filter by opened status (opened=true)
  const filterByOpened =
    await api.functional.prefix.member.my.discussionboardNotifications.index(
      connection,
      {
        body: { opened: true },
      },
    );
  typia.assert(filterByOpened);
  TestValidator.predicate("opened=true filter: only opened notifications")(
    filterByOpened.data.every((n) => n.opened === true),
  );
  TestValidator.predicate(
    "opened=true filter: contains moderator notification",
  )(filterByOpened.data.some((n) => n.id === notifModerator.id));
  TestValidator.predicate("opened=true filter: does not contain unopened")(
    filterByOpened.data.every(
      (n) =>
        n.opened === true &&
        n.id !== notifMention.id &&
        n.id !== notifAnnouncement.id,
    ),
  );

  // Step 4: Filter by title substring ("UniqueHELLO")
  const filterByTitle =
    await api.functional.prefix.member.my.discussionboardNotifications.index(
      connection,
      {
        body: { title: "UniqueHELLO" },
      },
    );
  typia.assert(filterByTitle);
  TestValidator.predicate("title filter: matches announcement notification")(
    filterByTitle.data.some((n) => n.id === notifAnnouncement.id),
  );
  TestValidator.predicate("title filter: does not return non-matching")(
    filterByTitle.data.every((n) => n.title.includes("UniqueHELLO")),
  );

  // Step 5: Combined filter (type="moderator_action" & opened=true)
  const filterCombo =
    await api.functional.prefix.member.my.discussionboardNotifications.index(
      connection,
      {
        body: { type: "moderator_action", opened: true },
      },
    );
  typia.assert(filterCombo);
  TestValidator.predicate("type+opened filter: only moderator")(
    filterCombo.data.length === 1 &&
      filterCombo.data[0].id === notifModerator.id &&
      filterCombo.data[0].opened === true &&
      filterCombo.data[0].type === "moderator_action",
  );
}

