/**
 * Test the ability of an admin user to update their own issued warning log
 * entry by ID.
 *
 * This scenario covers:
 *
 * 1. Creating a warning log as an admin with deterministic fields for
 *    updatability.
 * 2. Updating the warning_reason and issued_at fields of the created log via "my"
 *    endpoint.
 * 3. Verifying that the response returns the expected updated data (id,
 *    moderator_id, warned_member_id, warning_reason, issued_at).
 *
 * Steps:
 *
 * 1. Prepare deterministic warningLog data for creation (including moderator_id
 *    and warned_member_id UUIDs, custom issue reason, and exact issued_at
 *    date-time).
 * 2. Call api.functional.prefix.admin.warningLogs.create() as admin to create the
 *    warning log.
 * 3. Prepare new update info for warning_reason and issued_at.
 * 4. Call api.functional.prefix.admin.my.warningLogs.update() with the log id and
 *    update body.
 * 5. Assert the updated fields in the response match the payload, while immutable
 *    fields are preserved.
 */
export async function test_api_prefix_admin_my_warningLogs_update(
  connection: api.IConnection,
) {
  // Step 1: Prepare test data for creating the warning log
  const moderator_id = typia.random<string & tags.Format<"uuid">>();
  const warned_member_id = typia.random<string & tags.Format<"uuid">>();
  const originalData: IWarningLog.ICreate = {
    moderator_id,
    warned_member_id,
    warning_reason: "Original reason for warning",
    issued_at: new Date(Date.now() - 100000).toISOString(),
  };

  // Step 2: Create the warning log as admin
  const created = await api.functional.prefix.admin.warningLogs.create(
    connection,
    {
      body: originalData,
    },
  );
  typia.assert(created);
  TestValidator.equals("created warning log matches input")(
    created.warning_reason,
  )(originalData.warning_reason);
  TestValidator.equals("created warning log matches input")(
    created.moderator_id,
  )(moderator_id);
  TestValidator.equals("created warning log matches input")(
    created.warned_member_id,
  )(warned_member_id);

  // Step 3: Prepare update data
  const updateInput: IWarningLog.IUpdate = {
    warning_reason: "Updated warning reason for test",
    issued_at: new Date().toISOString(),
  };

  // Step 4: Update the warning log using admin's own endpoint
  const updated = await api.functional.prefix.admin.my.warningLogs.update(
    connection,
    {
      id: created.id,
      body: updateInput,
    },
  );
  typia.assert(updated);

  // Step 5: Validate updated fields and preserved immutable fields
  TestValidator.equals("warning_reason should be updated")(
    updated.warning_reason,
  )(updateInput.warning_reason);
  TestValidator.equals("issued_at should be updated")(updated.issued_at)(
    updateInput.issued_at,
  );
  TestValidator.equals("moderator_id should remain")(updated.moderator_id)(
