 *
 * 1. Register two members (memberA, memberB).
 * 2. Each member creates a thread (threadA, threadB) and marks it as archived. As
 *    there is no direct SDK endpoint to create thread archive records, we
 *    simulate archiving via the 'archived: true' field in thread creation.
 * 3. Retrieve archives filtered by memberA's ID.
 * 4. Validate that all returned archive records have 'archived_by_member_id' equal
 *    to memberA's ID.
 * 5. Confirm that archives for threads by other members do not appear.
 */
export async function test_api_prefix_test_filter_thread_archives_by_archived_by_member_id(
  connection: api.IConnection,
) {
  // 1. Register two members
  const memberA_id = typia.random<string & tags.Format<"uuid">>();
