    connection,
    {
      body: {
        id: memberA_id,
        created_at: new Date().toISOString(),
      },
    },
  );
  typia.assert(memberA);

  const memberB = await api.functional.prefix.member.actors.members.create(
    connection,
    {
      body: {
        id: memberB_id,
        created_at: new Date().toISOString(),
      },
    },
  );
  typia.assert(memberB);

  // 2. Each member creates a thread (with archived: true)
  const threadA =
    await api.functional.prefix.member.threadsPosts.threads.create(connection, {
      body: {
        discussionboard_member_id: memberA.id,
        discussionboard_category_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        title: "Thread by A",
        status: "active",
        is_pinned: false,
        is_locked: false,
        archived: true,
        created_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
      },
    });
  typia.assert(threadA);

  const threadB =
    await api.functional.prefix.member.threadsPosts.threads.create(connection, {
      body: {
        discussionboard_member_id: memberB.id,
        discussionboard_category_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        title: "Thread by B",
        status: "active",
        is_pinned: false,
        is_locked: false,
        archived: true,
        created_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
      },
    });
  typia.assert(threadB);

  // 3. Filter thread archives by memberA's ID
  const archivePage =
    await api.functional.prefix.member.threadsPosts.threadArchives.index(
      connection,
      {
        body: {
          archived_by_member_id: memberA.id,
        },
      },
    );
  typia.assert(archivePage);

  // 4. Validate that all returned archives were archived by memberA and not memberB
  for (const archive of archivePage.data) {
    TestValidator.equals("archive archived_by_member_id")(
      archive.archived_by_member_id,
    )(memberA.id);
  }
}

