import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardAdmin";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IThreadArchive } from "@ORGANIZATION/PROJECT-api/lib/structures/IThreadArchive";
import type { IPageIThreadArchive } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIThreadArchive";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate admin's ability to retrieve a paginated and filterable list of
 * thread archive records.
 *
 * Business context: Admin users must be able to audit (list, search, and page
 * through) all archives (soft-deleted threads). This test ensures that the
 * paginated retrieval and filtering features perform as expected, including
 * correct page sizes, navigation, and filter options.
 *
 * Step-by-step process:
 *
 * 1. Ensure there is an admin user (assign admin role with a random UUID)
 * 2. Create more than one page's worth of threads as member (e.g. 15 threads)
 * 3. Archive (soft-delete) each created thread to generate thread archive entries
 * 4. As admin, fetch the first page of thread archive records and check correct
 *    page/size
 * 5. Fetch the second page and check remaining records
 * 6. Apply a filter (by thread_id) and check that results match expectation
 */
export async function test_api_admin_test_admin_list_thread_archives_with_pagination(
  connection: api.IConnection,
) {
  // 1. Assign admin role to a user (simulate existence of at least one admin)
  const adminUserId = typia.random<string & tags.Format<"uuid">>();
  const adminAssignInput = {
    id: adminUserId,
    created_at: new Date().toISOString(),
  } satisfies IDiscussionboardAdmin.ICreate;
  const admin = await api.functional.prefix.admin.actors.admins.create(
    connection,
    {
      body: adminAssignInput,
    },
  );
  typia.assert(admin);

  // 2. Create multiple threads (at least 15) as a member for paging tests
  const categoryId = typia.random<string & tags.Format<"uuid">>();
  const threads: IDiscussionboardThreads[] = [];
  const now = new Date();
  for (let i = 0; i < 15; ++i) {
    const t = await api.functional.prefix.member.threadsPosts.threads.create(
      connection,
      {
        body: {
          discussionboard_category_id: categoryId,
          title: `Thread ${i + 1}`,
          status: "active",
          is_pinned: false,
          is_locked: false,
          archived: false,
          created_at: new Date(now.getTime() + i * 1000).toISOString(),
          updated_at: new Date(now.getTime() + i * 1000).toISOString(),
        } satisfies IDiscussionboardThreads.ICreate,
      },
    );
    typia.assert(t);
    threads.push(t);
  }

  // 3. Archive (soft-delete) all those threads as member
  for (const t of threads) {
    await api.functional.prefix.member.my.threadsPosts.threads.erase(
      connection,
      {
        id: t.id,
      },
    );
  }

  // 4. Retrieve first page of thread archives as admin (limit 10)
  const page1 =
    await api.functional.prefix.admin.threadsPosts.threadArchives.index(
      connection,
      {
        body: {
          page: 1,
          limit: 10,
        } satisfies IThreadArchive.IRequest,
      },
    );
  typia.assert(page1);
  TestValidator.equals("first page record count")(page1.data.length)(10);
  TestValidator.equals("pagination limit")(page1.pagination.limit)(10);
  TestValidator.equals("pagination current")(page1.pagination.current)(1);

  // 5. Retrieve next page (remaining 5 records)
  const page2 =
    await api.functional.prefix.admin.threadsPosts.threadArchives.index(
      connection,
      {
        body: {
          page: 2,
          limit: 10,
        } satisfies IThreadArchive.IRequest,
      },
    );
  typia.assert(page2);
  TestValidator.equals("second page record count")(page2.data.length)(5);
  TestValidator.equals("pagination current 2")(page2.pagination.current)(2);

  // 6. Filtering: filter by specific thread id (should match one entry)
  const threadToFilter = threads[0];
  const filtered =
    await api.functional.prefix.admin.threadsPosts.threadArchives.index(
      connection,
      {
        body: {
          thread_id: threadToFilter.id,
        } satisfies IThreadArchive.IRequest,
      },
    );
  typia.assert(filtered);
  TestValidator.equals("filtered size")(filtered.data.length)(1);
  TestValidator.equals("filtered thread id")(
    filtered.data[0].discussionboard_thread_id,
  )(threadToFilter.id);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardAdmin";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IThreadArchive } from "@ORGANIZATION/PROJECT-api/lib/structures/IThreadArchive";
import type { IPageIThreadArchive } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIThreadArchive";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E: archive_reason 필터로 관리자 스레드 아카이브 목록 필터링
 *
 * - 여러 개 스레드 각각을 soft-archive 처리한 뒤, archive_reason 필드로 필터링 조회 동작을 검증한다
 * - 비즈니스상 아카이브 사유는 직접 입력 불가(erase API 제한) → 실제 시스템에서는 동일한 사유 값으로만 아카이브가 생성될 수 있음
 * - 테스트는 API의 제약 내에서 archive_reason 필터 동작과 빈 결과 리턴 처리까지 검증한다
 *
 * 1. 관리자로 사용할 테스트 UUID를 생성하고, 관리자로 role 할당을 수행
 * 2. 3개 이상의 스레드를 순차 생성(같은 카테고리 사용, 각 스레드는 unarchived로 시작)
 * 3. 각 스레드별로 erase API로 soft-archive 수행 (사유값은 직접 제어 불가)
 * 4. 관리자는 archive_reason으로 아카이브 목록을 필터링하여 조회 (존재하는 값/없는 값)
 * 5. 각 케이스에 대한 반환 데이터의 archive_reason, 개수 등 검증
 */
export async function test_api_admin_test_admin_filter_thread_archives_by_reason(
  connection: api.IConnection,
) {
  // 1. 테스트용 관리자 UUID 생성 & 관리자 역할 할당
  const adminId: string = typia.random<string & tags.Format<"uuid">>();
  const admin: IDiscussionboardAdmin =
    await api.functional.prefix.admin.actors.admins.create(connection, {
      body: {
        id: adminId,
        created_at: new Date().toISOString(),
      } satisfies IDiscussionboardAdmin.ICreate,
    });
  typia.assert(admin);

  // 2. 동일 카테고리로 3개 스레드 생성
  const categoryId = typia.random<string & tags.Format<"uuid">>();
  const now = new Date();
  const threads: IDiscussionboardThreads[] = await ArrayUtil.asyncRepeat(3)(
    async (idx) => {
      return api.functional.prefix.member.threadsPosts.threads.create(
        connection,
        {
          body: {
            discussionboard_category_id: categoryId,
            title: `테스트 스레드 ${idx + 1}`,
            status: "active",
            is_pinned: false,
            is_locked: false,
            archived: false,
            created_at: new Date(now.getTime() + idx * 5000).toISOString(),
            updated_at: new Date(now.getTime() + idx * 5000).toISOString(),
          } satisfies IDiscussionboardThreads.ICreate,
        },
      );
    },
  );
  threads.forEach((thread) => typia.assert(thread));

  // 3. 각 스레드별로 soft-archive 처리 (erase는 직접 사유 지정 불가)
  await ArrayUtil.asyncMap(threads)(async (thread) => {
    await api.functional.prefix.member.my.threadsPosts.threads.erase(
      connection,
      { id: thread.id },
    );
  });

  // 4-1. 존재하는 archive_reason (시스템 기본 사유, 예시로 '정책위반')로 필터링
  const targetReason = "정책위반";
  const page: IPageIThreadArchive =
    await api.functional.prefix.admin.threadsPosts.threadArchives.index(
      connection,
      {
        body: { archive_reason: targetReason },
      },
    );
  typia.assert(page);
  page.data.forEach((archive) => {
    TestValidator.equals("archive reason match")(archive.archive_reason)(
      targetReason,
    );
  });

  // 4-2. 존재하지 않는 archive_reason으로 필터링 시 빈 데이터
  const emptyResult =
    await api.functional.prefix.admin.threadsPosts.threadArchives.index(
      connection,
      { body: { archive_reason: "존재하지않는사유" } },
    );
  typia.assert(emptyResult);
  TestValidator.equals("no archives for unknown reason")(
    emptyResult.data.length,
  )(0);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IThreadArchive } from "@ORGANIZATION/PROJECT-api/lib/structures/IThreadArchive";

/**
 * 인증된 멤버가 자신의 스레드를 아카이브(soft delete)한 후, 아카이브 레코드 상세정보를 id로 조회하여 무결성과 권한을 검증하는
 * E2E 테스트입니다.
 *
 * 본 테스트는 다음의 실제 사용자 흐름을 검증합니다:
 *
 * 1. 멤버 역할을 등록 및 인증합니다 (id 고정)
 * 2. 해당 멤버 권한으로 스레드를 생성합니다
 * 3. 생성된 스레드를 해당 멤버가 직접 아카이브(soft delete) 처리합니다
 * 4. 아카이브 레코드 id로 thread archive 상세 조회를 수행합니다
 * 5. 반환값의 논리적 일관성, 소유성, 통합 데이터 무결성을 검증합니다
 *
 * 단, 아카이브 id는 실제 운영 시스템에서는 아카이브 create/delete API 반환값이나 목록조회 API 등에서 획득해야 하나, 본
