      body: {
        appeal_code: `APPEAL-${new Date().toISOString().slice(0, 10).replace(/-/g, "")}-001`,
        status: "PENDING",
        created_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
      },
    },
  );
  typia.assert(appeal);

  // 2. 기존 값 snapshot 확보
  const beforeCode = appeal.appeal_code;
  const beforeStatus = appeal.status;

  // 3. 존재하지 않는 status 값 등 schema 위반 값으로 수정 요청 → 오류 발생 기대
  await TestValidator.error("잘못된 status 값으로 수정 시도시 오류 발생")(
