import type { IDiscussionboardAppeal } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardAppeal";
import type { IDiscussionboardAppeals } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardAppeals";

/**
 * Validate that an admin cannot update an appeal with an invalid schema (e.g.,
 * disallowed enum values or missing required fields).
 *
 * This test ensures the backend validation catches attempts to update an appeal
 * record using data that:
 *
 * - Supplies illegal enum/string values, or
 * - Omits all updatable fields, or
 * - Provides property values with forbidden types or nulls for required fields.
 *
 * Workflow:
 *
 * 1. Create a valid appeal (dependency setup)
 * 2. Attempt to update the appeal using at least two different invalid payloads:
 *    a. Provide a status value not allowed by business rules (e.g.,
 *    'INVALID_STATUS') b. Remove all updatable fields from the payload (i.e.,
 *    pass {}) c. Provide null where property requires string, if any required
 *    string property exists
 * 3. For each invalid update attempt, expect the API to throw an error (typically
 *    a validation error, e.g., HTTP 400).
 * 4. After failure, reload the appeal and verify it is unchanged from the
 *    original, confirming no update was committed.
 *
 * This test is important for ensuring data integrity and backend enforcement of
 * domain rules.
 */
export async function test_api_prefix_admin_policyAudit_appeals_test_admin_update_appeal_with_invalid_schema_values(
  connection: api.IConnection,
) {
  // 1. Create valid appeal
  const baseAppeal =
    await api.functional.prefix.admin.policyAudit.appeals.create(connection, {
      body: {
        appeal_code: `APPEAL-${new Date().toISOString().slice(0, 10).replace(/-/g, "")}-001`,
        status: "PENDING",
        appellant_id: typia.random<string & tags.Format<"uuid">>(),
        incident_id: null,
        outcome: null,
        created_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
      } satisfies IDiscussionboardAppeal.ICreate,
    });
  typia.assert(baseAppeal);

  // Helper to reload the appeal after test
  const reload = async () => {
    // There is NO .at or fetch-by-id endpoint for a single appeal in the available SDK API.
    // As a workaround, we cannot reload; so we skip post-validation of no-changes. Normally we would check by fetching again.
    // In real code, would request such endpoint be implemented for proper data integrity test.
    return baseAppeal;
  };

  // 2a. Attempt invalid update with disallowed status value
  await TestValidator.error("disallowed status enum should fail")(async () => {
    await api.functional.prefix.admin.policyAudit.appeals.update(connection, {
      appealId: baseAppeal.id,
      body: {
        status: "INVALID_STATUS",
      } satisfies IDiscussionboardAppeals.IUpdate,
    });
  });

  await reload();

  // 2b. Attempt completely empty update (no updatable fields)
  await TestValidator.error("empty body should fail")(async () => {
    await api.functional.prefix.admin.policyAudit.appeals.update(connection, {
      appealId: baseAppeal.id,
