 *
 * 1. The member creates an alert for themselves (prerequisite).
 * 2. The member updates the alert using the correct alertId and only permitted
 *    schema-defined fields (is_active, resolved_at).
 * 3. The update operation enforces ownership and does not allow over-posting or
 *    changing other fields.
 * 4. The response returns the updated alert record with only the allowed fields
 *    changed, all others remaining the same.
 */
export async function test_api_discussionboardAlerts_test_update_own_alert_successfully(
  connection: api.IConnection,
) {
  // 1. Create an alert as the authenticated member (prerequisite)
  const alert =
    await api.functional.prefix.member.my.discussionboardAlerts.create(
      connection,
      {
        body: {
          type: "policy_update",
          severity: "info",
          title: RandomGenerator.alphabets(10),
          body: RandomGenerator.paragraph()(),
          is_active: true,
        },
      },
    );
