 * 1. Register a new member (ID, created_at)
 * 2. Create a thread as that member (category, title, status, flags, timestamps)
 * 3. Create a post in that thread by the member
 * 4. Create a post like on that post by the same member
 * 5. Delete the post like as the user (hard delete)
 * 6. Attempt to delete again—should fail (confirms hard delete)
 */
export async function test_api_prefix_test_delete_post_like_owned_by_authenticated_member(
  connection: api.IConnection,
) {
  // 1. Register a new member (ID, created_at)
  const memberId = typia.random<string & tags.Format<"uuid">>();
  const memberCreatedAt = new Date().toISOString();
  const member = await api.functional.prefix.member.actors.members.create(
    connection,
    {
      body: {
        id: memberId,
        created_at: memberCreatedAt,
      } satisfies IDiscussionboardMembers.ICreate,
    },
  );
  typia.assert(member);

  // 2. Create a thread
  const thread = await api.functional.prefix.member.threadsPosts.threads.create(
    connection,
    {
      body: {
        discussionboard_category_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        title: "Test thread for like delete",
        status: "active",
        is_pinned: false,
        is_locked: false,
        archived: false,
        created_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
      } satisfies IDiscussionboardThreads.ICreate,
    },
  );
  typia.assert(thread);

  // 3. Create a post in the thread
  const post = await api.functional.prefix.member.threadsPosts.posts.create(
    connection,
    {
      body: {
        discussionboard_thread_id: thread.id,
        body: "This is the post to be liked.",
      } satisfies IDiscussionboardPosts.ICreate,
    },
  );
