import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IPoll } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoll";
import type { IPageIPoll } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPoll";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate advanced poll listing with pagination and filters.
 *
 * This test ensures the PATCH /prefix/member//polls endpoint correctly supports
 * paginated retrieval and advanced filtering. It validates that filters for
 * creator, anonymity, expiration date, thread, and prompt substring work as
 * expected, and handles empty result scenarios for valid/invalid queries.
 *
 * Steps:
 *
 * 1. Register two members (memberA and memberB)
 * 2. Create two threads in the same category
 * 3. As memberA, create polls in thread1 with varied settings (prompt, anonymity,
 *    multiple)
 * 4. As memberB, create at least one poll in thread2
 * 5. Test poll listing/filters: by creator, by thread, allow_multiple_choices,
 *    anonymity, expiration, prompt substring; assert all results strictly match
 *    filter
 * 6. Test empty result for non-existent creator and absurd prompt substring
 */
export async function test_api_polls_test_list_polls_with_pagination_and_filtering(
  connection: api.IConnection,
) {
  // 1. Register two members
  const memberA = await api.functional.prefix.member.actors.members.create(
    connection,
    {
      body: {
        id: typia.random<string & tags.Format<"uuid">>(),
        created_at: new Date().toISOString() as string &
          tags.Format<"date-time">,
      },
    },
  );
  typia.assert(memberA);
  const memberB = await api.functional.prefix.member.actors.members.create(
    connection,
    {
      body: {
        id: typia.random<string & tags.Format<"uuid">>(),
        created_at: new Date(Date.now() - 10000).toISOString() as string &
          tags.Format<"date-time">,
      },
    },
  );
  typia.assert(memberB);

  // 2. Create two threads in one category
  const categoryId = typia.random<string & tags.Format<"uuid">>();
  const now = new Date();
  const thread1 =
    await api.functional.prefix.member.threadsPosts.threads.create(connection, {
      body: {
        discussionboard_category_id: categoryId,
        title: "Thread: Fruit Opinions",
        status: "active",
        is_pinned: false,
        is_locked: false,
        archived: false,
        created_at: now.toISOString() as string & tags.Format<"date-time">,
        updated_at: now.toISOString() as string & tags.Format<"date-time">,
      },
    });
  typia.assert(thread1);
  const thread2 =
    await api.functional.prefix.member.threadsPosts.threads.create(connection, {
      body: {
        discussionboard_category_id: categoryId,
        title: "Thread: Politics Q&A",
        status: "active",
        is_pinned: false,
        is_locked: false,
        archived: false,
        created_at: new Date(now.getTime() + 60000).toISOString() as string &
          tags.Format<"date-time">,
        updated_at: new Date(now.getTime() + 60000).toISOString() as string &
          tags.Format<"date-time">,
      },
    });
  typia.assert(thread2);

  // 3. As memberA create 3 polls in thread1 (varied attributes)
  const pollA1 = await api.functional.prefix.member.polls.create(connection, {
    body: {
      discussionboard_thread_id: thread1.id,
      prompt: "What is your favorite fruit?",
      allow_multiple_choices: false,
      is_anonymous: false,
      expires_at: new Date(
        now.getTime() + 2 * 3600000,
      ).toISOString() as string & tags.Format<"date-time">,
    },
  });
  typia.assert(pollA1);
  const pollA2 = await api.functional.prefix.member.polls.create(connection, {
    body: {
      discussionboard_thread_id: thread1.id,
      prompt: "Best summer fruit poll?",
      allow_multiple_choices: true,
      is_anonymous: true,
      expires_at: new Date(
        now.getTime() + 3 * 3600000,
      ).toISOString() as string & tags.Format<"date-time">,
    },
  });
  typia.assert(pollA2);
  const pollA3 = await api.functional.prefix.member.polls.create(connection, {
    body: {
      discussionboard_thread_id: thread1.id,
      prompt: "Fruit seasons schedule",
      allow_multiple_choices: false,
      is_anonymous: true,
      expires_at: new Date(now.getTime() - 3600000).toISOString() as string &
        tags.Format<"date-time">,
    },
  });
  typia.assert(pollA3);

  // 4. As memberB create a poll in thread2
  const pollB1 = await api.functional.prefix.member.polls.create(connection, {
    body: {
      discussionboard_thread_id: thread2.id,
      prompt: "Current events in politics",
      allow_multiple_choices: false,
      is_anonymous: false,
      expires_at: new Date(
        now.getTime() + 3 * 3600000,
      ).toISOString() as string & tags.Format<"date-time">,
    },
  });
  typia.assert(pollB1);

  // 5.1 Filter by creator
  let page = await api.functional.prefix.member.polls.index(connection, {
    body: { created_by_member_id: pollA1.created_by_member_id },
  });
  typia.assert(page);
  TestValidator.predicate("all polls by memberA")(
    page.data.every(
      (p) => p.created_by_member_id === pollA1.created_by_member_id,
    ),
  );

  page = await api.functional.prefix.member.polls.index(connection, {
    body: { created_by_member_id: pollB1.created_by_member_id },
  });
  typia.assert(page);
  TestValidator.predicate("all polls by memberB")(
    page.data.every(
      (p) => p.created_by_member_id === pollB1.created_by_member_id,
    ),
  );

  // 5.2 Filter by thread
  page = await api.functional.prefix.member.polls.index(connection, {
    body: { discussionboard_thread_id: thread1.id },
  });
  typia.assert(page);
  TestValidator.predicate("all polls in thread1")(
    page.data.every((p) => p.discussionboard_thread_id === thread1.id),
  );
  page = await api.functional.prefix.member.polls.index(connection, {
    body: { discussionboard_thread_id: thread2.id },
  });
  typia.assert(page);
  TestValidator.predicate("all polls in thread2")(
    page.data.every((p) => p.discussionboard_thread_id === thread2.id),
  );

  // 5.3 Filter by allow_multiple_choices
  page = await api.functional.prefix.member.polls.index(connection, {
    body: { allow_multiple_choices: true },
  });
  typia.assert(page);
  TestValidator.predicate("all allow multiple")(
    page.data.every((p) => p.allow_multiple_choices === true),
  );
  page = await api.functional.prefix.member.polls.index(connection, {
    body: { allow_multiple_choices: false },
  });
  typia.assert(page);
  TestValidator.predicate("all do not allow multiple")(
    page.data.every((p) => p.allow_multiple_choices === false),
  );

  // 5.4 Filter by anonymity
  page = await api.functional.prefix.member.polls.index(connection, {
    body: { is_anonymous: true },
  });
  typia.assert(page);
  TestValidator.predicate("all are anonymous")(
    page.data.every((p) => p.is_anonymous === true),
  );
  page = await api.functional.prefix.member.polls.index(connection, {
    body: { is_anonymous: false },
  });
  typia.assert(page);
  TestValidator.predicate("all are not anonymous")(
    page.data.every((p) => p.is_anonymous === false),
  );

  // 5.5 Expiry - get expired/active
  const currentISO = new Date().toISOString() as string &
    tags.Format<"date-time">;
  page = await api.functional.prefix.member.polls.index(connection, {
    body: { expires_before: currentISO },
  });
  typia.assert(page);
  TestValidator.predicate("all expired")(
    page.data.every((p) => !!p.expires_at && p.expires_at < currentISO),
  );
  page = await api.functional.prefix.member.polls.index(connection, {
    body: { expires_after: currentISO },
  });
  typia.assert(page);
  TestValidator.predicate("all active")(
    page.data.every((p) => !!p.expires_at && p.expires_at > currentISO),
  );

  // 5.6 Prompt keyword (fruit/politics)
  page = await api.functional.prefix.member.polls.index(connection, {
    body: { prompt: "fruit" },
  });
  typia.assert(page);
  TestValidator.predicate("prompt contains fruit")(
    page.data.every((p) => p.prompt.toLowerCase().includes("fruit")),
  );
  page = await api.functional.prefix.member.polls.index(connection, {
    body: { prompt: "Politics" },
  });
  typia.assert(page);
  TestValidator.predicate("prompt contains politics")(
    page.data.every((p) =>
      p.prompt.toLowerCase().includes("politics".toLowerCase()),
    ),
  );

  // 6. Empty result scenarios
  page = await api.functional.prefix.member.polls.index(connection, {
    body: {
      created_by_member_id: typia.random<string & tags.Format<"uuid">>(),
    },
  });
  typia.assert(page);
  TestValidator.equals("empty data")(page.data.length)(0);
  page = await api.functional.prefix.member.polls.index(connection, {
    body: { prompt: "unfindablerandomtextxyz" },
  });
  typia.assert(page);
  TestValidator.equals("empty data by nonsense prompt")(page.data.length)(0);
}

