import api from "@ORGANIZATION/PROJECT-api";
import type { IPoll } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoll";
import type { IPageIPoll } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPoll";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validates poll search returns empty page for non-matching criteria.
 *
 * This test verifies that searching for polls using filters that do not match
 * any existing records returns an empty results page, and handles the 'not
 * found' scenario properly without errors.
 *
 * Steps:
 *
 * 1. Construct a poll filter (using a random/unlikely prompt or an expiration date
 *    far in the future) that should not match any real poll in the database.
 * 2. Call the poll list/search endpoint using these criteria.
 * 3. Validate the result is a valid page with an empty data array and correct
 *    pagination.
 * 4. Ensure that no errors are thrown by the server (HTTP 2xx, valid response
 *    shape).
 */
export async function test_api_prefix_member_polls_index_with_no_match(
  connection: api.IConnection,
) {
  // 1. Prepare a search filter that should match no polls.
  const unlikelyPrompt = `unlikely-prompt-${typia.random<string & tags.Format<"uuid">>()}`;
  const farFuture = new Date(
    Date.now() + 10 * 365 * 24 * 60 * 60 * 1000,
  ).toISOString(); // +10 years

  // 2. Search polls by a prompt that almost certainly doesn't exist.
  const outputByPrompt = await api.functional.prefix.member.polls.index(
    connection,
    {
      body: {
        prompt: unlikelyPrompt,
      },
    },
  );
  typia.assert(outputByPrompt);
  TestValidator.equals("empty poll data for unlikely prompt")(
    outputByPrompt.data,
  )([]);

  // 3. Search polls by far future expiration, which should have no matches.
  const outputByExpiration = await api.functional.prefix.member.polls.index(
    connection,
    {
      body: {
        expires_before: farFuture,
        expires_after: farFuture,
      },
    },
  );
  typia.assert(outputByExpiration);
  TestValidator.equals("empty poll data for far future filters")(
    outputByExpiration.data,
  )([]);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IPoll } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoll";
import type { IPollVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IPollVote";

/**
 * Validate that an authenticated member can successfully update their own poll
 * vote's selected_option before poll closure.
 *
 * This test covers the business workflow:
 *
 * 1. Create/register a new member (roles only, via id/created_at)
 * 2. Create a new poll for a discussion thread, owned by the new member
 * 3. Vote on the poll as that member, with one selected option
 * 4. Update the vote's selected_option via the 'update' endpoint
 * 5. Confirm the returned vote object now reflects the new option selected
 *
 * This ensures business logic compliance: authenticated members can update
 * their own votes for active (not yet closed) polls.
 */
export async function test_api_prefix_test_update_own_poll_vote_successfully(
  connection: api.IConnection,
) {
  // 1. Create/register a new member
  const memberId = typia.random<string & tags.Format<"uuid">>();
  const createdAt = new Date().toISOString();
  const member = await api.functional.prefix.member.actors.members.create(
    connection,
    {
      body: {
        id: memberId,
        created_at: createdAt,
      },
    },
  );
  typia.assert(member);

  // 2. Create a new poll (thread id random, owned by our member)
  const threadId = typia.random<string & tags.Format<"uuid">>();
  const pollPrompt = "Who was the greatest physicist?";
  // Simulate a poll with three options
  const pollOptions = ["Isaac Newton", "Albert Einstein", "Marie Curie"];
  const poll = await api.functional.prefix.member.polls.create(connection, {
    body: {
      discussionboard_thread_id: threadId,
      prompt: pollPrompt,
      allow_multiple_choices: false,
      is_anonymous: false,
      expires_at: new Date(Date.now() + 3600 * 1000).toISOString(), // Expires in 1 hour
    },
  });
  typia.assert(poll);

  // 3. Vote on the poll as that member, selecting "Isaac Newton"
  const firstSelection = pollOptions[0];
  const pollVote = await api.functional.prefix.member.pollVotes.create(
    connection,
    {
      body: {
        discussionboard_poll_id: poll.id,
        selected_option: firstSelection,
      },
    },
  );
  typia.assert(pollVote);
  TestValidator.equals("voted option, initial")(pollVote.selected_option)(
    firstSelection,
  );
  TestValidator.equals("poll id matches")(pollVote.discussionboard_poll_id)(
    poll.id,
  );
  TestValidator.equals("member id matches")(pollVote.voting_member_id)(
    member.id,
  );

  // 4. Update the vote's selected_option to "Marie Curie"
  const newSelection = pollOptions[2];
  const updatedVote = await api.functional.prefix.member.my.pollVotes.update(
    connection,
    {
      id: pollVote.id,
      body: {
        selected_option: newSelection,
      },
    },
  );
  typia.assert(updatedVote);

  // 5. Confirm the updated vote's selected_option is now the new value
  TestValidator.equals("voted option updated")(updatedVote.selected_option)(
    newSelection,
  );
  TestValidator.equals("vote id unchanged")(updatedVote.id)(pollVote.id);
  TestValidator.equals("member id unchanged")(updatedVote.voting_member_id)(
    pollVote.voting_member_id,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
