    body: {
      discussionboard_poll_id: poll.id,
      selected_option: option,
    },
  });
  typia.assert(vote);

  // 4. Delete the poll vote as the member
  await api.functional.prefix.member.my.pollVotes.erase(connection, {
    id: vote.id,
  });

  // 5. Unable to check explicit not found on GET due to missing GET endpoint, so only ensure no error on delete
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IPoll } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoll";
import type { IPollVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IPollVote";

/**
 * Poll vote ownership enforcement – forbidden delete test
 *
 * This test confirms that a member cannot hard-delete (erase) another member's
 * poll vote. The flow ensures ownership-only enforcement on DELETE
 * /prefix/member//my/pollVotes/{id}:
 *
 * 1. Create two distinct members (Member A and Member B).
 * 2. As Member A, create a poll attached to a (random) thread.
 * 3. As Member A, cast a vote for an option in the poll (creates poll vote A).
 * 4. Switch session – as Member B, also vote on the same poll with a different
 *    option (creates poll vote B).
 * 5. Switch back to Member A. Attempt to hard-delete (erase) poll vote B (the vote
 *    made by Member B) using the DELETE /my/pollVotes/{id} endpoint.
 * 6. Validate that the API returns a 403 Forbidden error, proving that only the
 *    owner (creator) of a poll vote can erase their own votes – not others'.
 *
 * This ensures strict enforcement against accidental or malicious deletion of
 * other users' poll votes, critical in hard-delete scenarios (where no
 * soft-delete exists).
 */
export async function test_api_prefix_test_delete_poll_vote_not_owned_fails_with_forbidden(
  connection: api.IConnection,
) {
  // 1. Create Member A
  const memberAId = typia.random<string & tags.Format<"uuid">>();
  const memberAJoinPayload = {
    id: memberAId,
    created_at: new Date().toISOString() as string & tags.Format<"date-time">,
  } satisfies IDiscussionboardMembers.ICreate;
  const memberA = await api.functional.prefix.member.actors.members.create(
    connection,
    { body: memberAJoinPayload },
  );
  typia.assert(memberA);

  // 2. Create Member B (separate session)
  const memberBId = typia.random<string & tags.Format<"uuid">>();
  const memberBJoinPayload = {
    id: memberBId,
    created_at: new Date().toISOString() as string & tags.Format<"date-time">,
  } satisfies IDiscussionboardMembers.ICreate;
  const memberB = await api.functional.prefix.member.actors.members.create(
    connection,
    { body: memberBJoinPayload },
  );
  typia.assert(memberB);

  // 3. As Member A, create a poll
  // (We need a random thread id; membership context is handled externally, but 'created_by_member_id' is filled by session)
  const threadId = typia.random<string & tags.Format<"uuid">>();
  const pollCreatePayload = {
    discussionboard_thread_id: threadId,
    prompt: "Who should lead next quarter?",
    allow_multiple_choices: false,
    is_anonymous: false,
    expires_at: undefined,
  } satisfies IPoll.ICreate;
  const poll = await api.functional.prefix.member.polls.create(connection, {
    body: pollCreatePayload,
  });
  typia.assert(poll);

  // 4. As Member A, cast a vote (option: "optionA")
  const voteAPayload = {
    discussionboard_poll_id: poll.id,
    selected_option: "optionA",
  } satisfies IPollVote.ICreate;
  const voteA = await api.functional.prefix.member.pollVotes.create(
    connection,
    { body: voteAPayload },
  );
  typia.assert(voteA);

  // 5. Switch to Member B. Cast a vote (option: "optionB")
  const voteBPayload = {
    discussionboard_poll_id: poll.id,
    selected_option: "optionB",
  } satisfies IPollVote.ICreate;
  const voteB = await api.functional.prefix.member.pollVotes.create(
    connection,
    { body: voteBPayload },
  );
  typia.assert(voteB);

  // 6. Switch back to Member A and attempt to delete Member B's poll vote
  // Should return forbidden (403)
  await TestValidator.error("cannot delete another member's poll vote")(
    async () => {
      await api.functional.prefix.member.my.pollVotes.erase(connection, {
        id: voteB.id,
      });
    },
  );
}

