  // 5. discussionboard_post_id 기준 Mentions 조회 및 방금 생성된 mention 포함여부 확인
  const mentionsByPost = await api.functional.prefix.member.mentions.index(
    connection,
    {
      body: { discussionboard_post_id: post.id },
    },
  );
  typia.assert(mentionsByPost);
  const existsByPost = mentionsByPost.data.some((m) => m.id === mention.id);
  TestValidator.predicate("discussionboard_post_id로 조회 시 생성된 멘션 포함")(
    existsByPost,
  );

  // 6. mentioned_member_id 기준 Mentions 조회 및 방금 생성된 mention 포함여부 확인
  const mentionsByMember = await api.functional.prefix.member.mentions.index(
    connection,
