 * 3. Query with an invalid date-time string for created_at_from and expect
 *    validation error.
 * 4. Query with an invalid date-time string for created_at_to and expect
 *    validation error.
 * 5. Query with a negative integer for page and expect validation error.
 * 6. Query with an excessively large (unrealistic) limit value and expect
 *    validation error.
 * 7. In all cases, confirm that the API does not leak mention data, does not
 *    crash, and only returns clean validation errors.
 */
export async function test_api_mentions_test_admin_mentions_invalid_query_returns_validation_error(
  connection: api.IConnection,
) {
  // 1. Invalid discussionboard_post_id (not a UUID string)
  await TestValidator.error("invalid discussionboard_post_id should fail")(() =>
    api.functional.prefix.admin.mentions.index(connection, {
      body: { discussionboard_post_id: "invalid-uuid" },
    }),
  );

  // 2. Invalid mentioned_member_id (not a UUID string)
  await TestValidator.error("invalid mentioned_member_id should fail")(() =>
    api.functional.prefix.admin.mentions.index(connection, {
      body: { mentioned_member_id: "not-a-uuid" },
    }),
  );

  // 3. Invalid created_at_from date-time format
  await TestValidator.error("invalid created_at_from should fail")(() =>
    api.functional.prefix.admin.mentions.index(connection, {
      body: { created_at_from: "2025-13-99T99:99:99Z" },
    }),
  );

  // 4. Invalid created_at_to date-time format
  await TestValidator.error("invalid created_at_to should fail")(() =>
    api.functional.prefix.admin.mentions.index(connection, {
      body: { created_at_to: "32nd-of-June-2040" },
