  // 5. Invalid (negative) page value
  await TestValidator.error("negative page value should fail")(() =>
    api.functional.prefix.admin.mentions.index(connection, {
      body: { page: -5 },
    }),
  );

  // 6. Excessively large limit value
  await TestValidator.error("excessively large limit should fail")(() =>
    api.functional.prefix.admin.mentions.index(connection, {
      body: { limit: 5000000 },
    }),
  );
}

