    {
      body: {
        id: memberId,
        created_at: createdAt,
      } satisfies IDiscussionboardMembers.ICreate,
    },
  );
  typia.assert(member);
  TestValidator.equals("registered member id")(member.id)(memberId);

  // 2. (Assumed) Authenticate as member - assumed handled by connection

  // 3. Create a search history record for the member
  const rawSearchQuery = "test search query";
  const rawExecutedAt = new Date().toISOString() as string &
    tags.Format<"date-time">;
  const searchHistory =
    await api.functional.prefix.member.my.searchHistories.create(connection, {
      body: {
        discussionboard_member_id: memberId,
        search_query: rawSearchQuery,
        used_filters: null,
        executed_at: rawExecutedAt,
        deleted_at: null,
      } satisfies ISearchHistory.ICreate,
    });
  typia.assert(searchHistory);
  TestValidator.equals("belongs to member")(
    searchHistory.discussionboard_member_id,
  )(memberId);
  TestValidator.equals("not deleted yet")(searchHistory.deleted_at)(null);

  // 4. Soft-delete this search history
  await api.functional.prefix.member.my.searchHistories.erase(connection, {
    searchHistoryId: searchHistory.id,
  });
  // Cannot verify after deletion because SDK exposes no get/list.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
