export async function test_api_prefix_member_my_searchHistories_test_soft_delete_nonexistent_search_history_record_not_found(
  connection: api.IConnection,
) {
  // 1. Register and authenticate a discussion board member (prerequisite)
  const memberId: string = typia.random<string & tags.Format<"uuid">>();
  const createdAt: string = typia.random<string & tags.Format<"date-time">>();
