 * criteria.
 *
 * This test will:
 *
 * 1. Create a diverse set of thread tag records, each with unique combinations of
 *    code, display_name, is_restricted, is_hidden, and (optionally)
 *    description.
 * 2. Search for thread tags using different filters (code, display_name,
 *    is_restricted, is_hidden), including combinations of filters.
 * 3. Test pagination by adjusting page, limit, and verifying only expected records
 *    are returned.
 * 4. Verify that returned records exactly match the filter/search criteria.
 * 5. Test boundary cases such as zero results, partial matches, and invalid filter
 *    values.
 */
export async function test_api_prefix_test_search_thread_tags_with_various_filters(
  connection: api.IConnection,
) {
  // 1. Create a diverse set of thread tags
  const now = new Date();
  const testTags = [
    {
      code: "macroeconomics",
      display_name: "Macroeconomics",
      description: "Big picture economics",
      is_restricted: false,
      is_hidden: false,
      created_at: now.toISOString(),
    },
    {
      code: "microeconomics",
      display_name: "Microeconomics",
      description: "Individual actors",
      is_restricted: false,
      is_hidden: true,
      created_at: now.toISOString(),
    },
    {
      code: "fiscal_policy",
      display_name: "Fiscal Policy",
      description: null,
      is_restricted: true,
      is_hidden: false,
      created_at: now.toISOString(),
    },
    {
      code: "monetary_policy",
      display_name: "Monetary Policy",
      description: "Central banks",
      is_restricted: true,
      is_hidden: true,
      created_at: now.toISOString(),
    },
  ] satisfies IThreadTag.ICreate[];

  const createdTags: IThreadTag[] = [];
  for (const tag of testTags) {
    const createdTag = await api.functional.prefix.member.threadTags.create(
      connection,
      { body: tag },
    );
    typia.assert(createdTag);
    createdTags.push(createdTag);
  }

  // Helper to map code to tag
  const getTagByCode = (code: string) =>
    createdTags.find((t) => t.code === code)!;

  // 2. Query by 'code'
  const byCode = await api.functional.prefix.threadTags.index(connection, {
    body: { code: "macroeconomics" },
  });
  typia.assert(byCode);
  TestValidator.predicate("Found one macroeconomics tag")(
    byCode.data.length === 1 && byCode.data[0].code === "macroeconomics",
  );

  // 3. Query by 'display_name'
  const byDisplay = await api.functional.prefix.threadTags.index(connection, {
    body: { display_name: "Microeconomics" },
  });
  typia.assert(byDisplay);
  TestValidator.predicate("Found one microeconomics tag")(
    byDisplay.data.length === 1 &&
      byDisplay.data[0].display_name === "Microeconomics",
  );

  // 4. Query by 'is_restricted'
  const byRestricted = await api.functional.prefix.threadTags.index(
    connection,
    { body: { is_restricted: true } },
  );
  typia.assert(byRestricted);
  const restrictedCodes = createdTags
    .filter((t) => t.is_restricted)
    .map((t) => t.code);
  TestValidator.equals("Tags with is_restricted=true")(
    new Set(byRestricted.data.map((t) => t.code)),
  )(new Set(restrictedCodes));

  // 5. Query by 'is_hidden'
  const byHidden = await api.functional.prefix.threadTags.index(connection, {
    body: { is_hidden: true },
  });
  typia.assert(byHidden);
  const hiddenCodes = createdTags.filter((t) => t.is_hidden).map((t) => t.code);
  TestValidator.equals("Tags with is_hidden=true")(
    new Set(byHidden.data.map((t) => t.code)),
  )(new Set(hiddenCodes));

  // 6. Combined filter (e.g., is_restricted + is_hidden)
  const byRestrictedAndHidden = await api.functional.prefix.threadTags.index(
    connection,
    { body: { is_restricted: true, is_hidden: true } },
  );
  typia.assert(byRestrictedAndHidden);
  const restrictedHiddenCodes = createdTags
    .filter((t) => t.is_restricted && t.is_hidden)
    .map((t) => t.code);
  TestValidator.equals("Tags with is_restricted=true and is_hidden=true")(
    new Set(byRestrictedAndHidden.data.map((t) => t.code)),
  )(new Set(restrictedHiddenCodes));

  // 7. Query with invalid values (should return zero results)
  const nonsense = await api.functional.prefix.threadTags.index(connection, {
    body: { code: "not_a_tag" },
  });
  typia.assert(nonsense);
  TestValidator.equals("Nonsense code - no results")(nonsense.data.length)(0);

  // 8. Pagination test (limit = 2)
  const paged = await api.functional.prefix.threadTags.index(connection, {
    body: { limit: 2 } as any,
  });
  typia.assert(paged);
  TestValidator.equals("Paged response")(paged.data.length)(2);
  TestValidator.equals("Page limit set")(paged.pagination.limit)(2);
}

