 *
 * Steps:
 *
 * 1. Create a saved filter as the authenticated user.
 * 2. Ensure the filter exists and is not soft-deleted.
 * 3. Soft-delete the filter using DELETE.
 * 4. Confirm that subsequent reads for the filter fail.
 * 5. Ensure repeated soft-deletes on the same filter fail.
 * 6. Attempt to soft-delete a non-existent filter (random UUID) and expect error.
 * 7. (If test infra allows, try deleting someone else's filter; if not possible
 *    via public API, skip.)
 */
export async function test_api_prefix_member_filters_test_soft_delete_own_filter_and_error_on_non_owned_or_already_deleted(
  connection: api.IConnection,
) {
  // 1. Create a new filter for the authenticated user
  const filterInput = {
    name: RandomGenerator.alphabets(8),
    definition: JSON.stringify({ query: RandomGenerator.paragraph()() }),
    is_public: false,
  } satisfies IDiscussionboardFilter.ICreate;
  const filter = await api.functional.prefix.member.my.filters.create(
    connection,
    { body: filterInput },
  );
  typia.assert(filter);

  // 2. Read the filter and confirm it exists and is not soft-deleted
  const ownedFilter = await api.functional.prefix.member.my.filters.at(
    connection,
    { filterId: filter.id },
  );
