/**
 * E2E: Retrieve thread archive details as a moderator using a valid id
 *
 * 비즈니스 컨텍스트:
 *
 * - Thread archive(soft-delete)는 moderation, 컴플라이언스, 유저 이의신청 등 실무핵심 이벤트로 정확한
 *   상세조회가 매우 중요
 *
 * 테스트 시나리오:
 *
 * 1. (가정) moderator 인증 (테스트 SDK 내 인증 구현 없으므로 comment로 대체)
 * 2. Member 계정으로 discussion thread를 생성 (필수 파라미터만 사용)
 * 3. Member가 해당 thread를 soft-delete(archive) API 호출
 * 4. (erase는 archive id 반환하지 않음 → thread id==archive id로 목업 진행)
 * 5. Moderator로 threadArchives/:id 상세 조회 호출
 * 6. 반환 필드(id, discussionboard_thread_id, archived_by_member_id, archive_reason,
 *    created_at) 유무와 논리 일치성, uuid/iso8601 검증
 */
export async function test_api_moderator_test_retrieve_thread_archive_details_with_valid_id_as_moderator(
  connection: api.IConnection,
) {
  // 1. (SKIP) Moderator 인증: 실제 인증 SDK 미제공(구현 가능 시점에 추가)

  // 2. member로 discussion thread 생성
  const now = new Date().toISOString();
  const thread = await api.functional.prefix.member.threadsPosts.threads.create(
    connection,
    {
      body: {
        discussionboard_category_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        title: "테스트 스레드 제목",
        status: "active",
        is_pinned: false,
        is_locked: false,
        archived: false,
        created_at: now,
        updated_at: now,
      },
    },
  );
  typia.assert(thread);

  // 3. member가 자신의 thread를 archive(soft-delete) 처리
  await api.functional.prefix.member.my.threadsPosts.threads.erase(connection, {
    id: thread.id,
  });

  // 4. archive id 확보: erase가 archive id/엔트리 미반환하므로, thread id==archive id로 간주
  const archiveId = thread.id as string & tags.Format<"uuid">;

  // 5. moderator로 archive 상세 조회
  const archive =
    await api.functional.prefix.moderator.threadsPosts.threadArchives.at(
      connection,
      {
        id: archiveId,
      },
    );
  typia.assert(archive);

  // 6. 필드 유효성 및 논리 일치성 점검
  TestValidator.equals("discussionboard_thread_id 일치")(
    archive.discussionboard_thread_id,
  )(thread.id);
  TestValidator.predicate("archive id uuid 형식")(
    /^\w{8}(-\w{4}){3}-\w{12}$/.test(archive.id),
  );
  TestValidator.predicate("archived_by_member_id uuid 형식")(
    /^\w{8}(-\w{4}){3}-\w{12}$/.test(archive.archived_by_member_id),
  );
  TestValidator.predicate("created_at iso8601 형식")(
    /^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(.+)$/.test(
      archive.created_at,
    ),
  );
  TestValidator.predicate("archive_reason: string 타입")(
    typeof archive.archive_reason === "string" &&
      archive.archive_reason.length > 0,
  );
}

