  const invalidTagId = typia.random<string & tags.Format<"uuid">>();
  const now = new Date().toISOString() as string & tags.Format<"date-time">;

  // 2. Attempt to create an association and expect a foreign key constraint error
  await TestValidator.error("Foreign key constraint error")(() =>
    api.functional.prefix.member.taggedThreads.create(connection, {
