import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IThreadTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IThreadTag";
import type { IDiscussionboardTaggedThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardTaggedThread";

/**
 * Test updating an existing thread-tag association's linked thread or tag.
 *
 * This test verifies that a thread-tag association (taggedThread) can be
 * successfully updated to reference a different thread or tag. It first creates
 * an initial thread, an initial tag, and associates them together. Then, it
 * creates either a second thread or tag to perform the update: it either
 * changes the association's thread or tag by updating the association via PUT.
 * Finally, it asserts that the association now points to the new thread or
 * tag.
 *
 * - Step 1: Create the first discussion thread.
 * - Step 2: Create the first thread tag.
 * - Step 3: Associate the thread and tag to create an initial taggedThread
 *   association.
 * - Step 4: Create a new thread and tag for update purposes.
 * - Step 5: Update the existing taggedThread, switching either its thread or tag
 *   as the association's target via the update endpoint.
 * - Step 6: Assert that the update took effect – the association now references
 *   the new thread or tag.
 */
export async function test_api_taggedThreads_test_update_thread_tag_association_success(
  connection: api.IConnection,
) {
  // Step 1: Create the first discussion thread
  const thread1 =
    await api.functional.prefix.member.threadsPosts.threads.create(connection, {
      body: {
        discussionboard_category_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        title: "Initial thread",
        status: "active",
        is_pinned: false,
        is_locked: false,
        archived: false,
        created_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
      },
    });
  typia.assert(thread1);

  // Step 2: Create the first thread tag
  const tag1 = await api.functional.prefix.member.threadTags.create(
    connection,
    {
      body: {
        code: `code_${Date.now()}`,
        display_name: "Initial Tag",
        description: "Tag for update test.",
        is_restricted: false,
        is_hidden: false,
        created_at: new Date().toISOString(),
      },
    },
  );
  typia.assert(tag1);

  // Step 3: Create initial taggedThread association between thread1 and tag1
  const taggedThread = await api.functional.prefix.member.taggedThreads.create(
    connection,
    {
      body: {
        discussionboard_thread_id: thread1.id,
        discussionboard_thread_tag_id: tag1.id,
        created_at: new Date().toISOString(),
      },
    },
  );
  typia.assert(taggedThread);

  // Step 4: Create a new thread and a new tag for updating associations
  const thread2 =
    await api.functional.prefix.member.threadsPosts.threads.create(connection, {
      body: {
        discussionboard_category_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        title: "Updated thread",
        status: "active",
        is_pinned: false,
        is_locked: false,
        archived: false,
        created_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
      },
    });
  typia.assert(thread2);

  const tag2 = await api.functional.prefix.member.threadTags.create(
    connection,
    {
      body: {
        code: `newtag_${Date.now()}`,
        display_name: "Updated Tag",
        description: "Second tag for update.",
        is_restricted: false,
        is_hidden: false,
        created_at: new Date().toISOString(),
      },
    },
  );
  typia.assert(tag2);

  // Step 5: Update the association to point to the second thread (can also switch tags)
  const updatedTaggedThread =
    await api.functional.prefix.member.taggedThreads.update(connection, {
      taggedThreadId: taggedThread.id,
      body: {
        discussionboard_thread_id: thread2.id,
        // Or update tag as: discussionboard_thread_tag_id: tag2.id,
        // Optionally, can update created_at if needed
      },
    });
  typia.assert(updatedTaggedThread);

  // Step 6: Validate the association now matches the updated thread
  TestValidator.equals("thread ID should be updated")(
    updatedTaggedThread.discussionboard_thread_id,
  )(thread2.id);
  // If updated tag as well, can assert similarly:
  // TestValidator.equals("tag ID should be updated")(updatedTaggedThread.discussionboard_thread_tag_id)(tag2.id);
}

