import type { IDiscussionboardTaggedThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardTaggedThread";

/**
 * Thread-Tag 연관관계에 대한 외래키 오류 update 시도 검사.
 *
 * - 이 테스트는 토론 스레드에 태그를 부여하는 연관 레코드(taggedThread,
 *   discussionboard_tagged_threads)에서 update (PUT)을 할 때, 실제로 존재하지 않는 스레드 혹은 태그의
 *   UUID로 변경 시도를 했을 때 시스템이 제대로 외래키 위반(foreign key violation) 에러를 반환하는지 검증한다.
 * - 정상적인 연관 레코드가 미리 준비되어야 하며, 그 PK (taggedThreadId)는 존재하는 값이어야 한다.
 * - Update 본문의 thread ID 또는 tag ID 필드에, 확실히 존재하지 않는 값(UUID) (즉, 비어있는 UUID 등)을 직접
 *   입력해 update 시도를 한다.
 * - 시스템이 명확하게 외래키 위반 오류 (DB 레벨 혹은 명시적 비즈니스 체크) 로 4xx/5xx 에러(예: 400/404/409/422
 *   등)를 리턴하는지, 성공적으로 update 되지 않고 기존 값이 그대로 보존되는지 확인한다.
 *
 * **단계별 흐름**
 *
 * 1. 정상 토론 스레드 레코드 생성
 * 2. 정상 태그 레코드 생성
 * 3. 이 둘을 이용해 taggedThread (연관정보) 생성 → 이 PK(taggedThreadId)로 테스트 진행
 * 4. 존재하지 않는 threadId(uuid) 또는 tagId(uuid)로 업데이트 시도 (body에 invalid uuid 입력)
 * 5. 시스템이 명확한 외래키 위반 오류를 리턴하고, 실제 DB 값이 그대로임을 검증
 */
export async function test_api_taggedThreads_test_update_thread_tag_association_foreign_key_error(
  connection: api.IConnection,
) {
  // 1. 정상 토론 스레드 생성
  const thread = await api.functional.prefix.member.threadsPosts.threads.create(
    connection,
    {
      body: {
        discussionboard_category_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        title: RandomGenerator.alphaNumeric(10),
        status: "active",
        is_pinned: false,
        is_locked: false,
        archived: false,
        created_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
      } satisfies IDiscussionboardThreads.ICreate,
    },
  );
  typia.assert(thread);

  // 2. 정상 태그 생성
  const tag = await api.functional.prefix.member.threadTags.create(connection, {
    body: {
      code: RandomGenerator.alphabets(8),
      display_name: RandomGenerator.alphabets(10),
      description: null,
      is_restricted: false,
      is_hidden: false,
      created_at: new Date().toISOString(),
    } satisfies IThreadTag.ICreate,
  });
  typia.assert(tag);

  // 3. threadedThread 생성
  const taggedThread = await api.functional.prefix.member.taggedThreads.create(
    connection,
    {
      body: {
        discussionboard_thread_id: thread.id,
        discussionboard_thread_tag_id: tag.id,
        created_at: new Date().toISOString(),
      } satisfies IDiscussionboardTaggedThread.ICreate,
    },
  );
  typia.assert(taggedThread);

  // 4-1. 존재하지 않는 threadId로 update 시도
  const invalidThreadId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error(
    "존재하지 않는 discussionboard_thread_id update 외래키 위반",
  )(async () => {
    await api.functional.prefix.member.taggedThreads.update(connection, {
      taggedThreadId: taggedThread.id,
      body: {
        discussionboard_thread_id: invalidThreadId,
      } satisfies IDiscussionboardTaggedThread.IUpdate,
    });
  });

  // 4-2. 존재하지 않는 tagId로 update 시도
  const invalidTagId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error(
    "존재하지 않는 discussionboard_thread_tag_id update 외래키 위반",
  )(async () => {
    await api.functional.prefix.member.taggedThreads.update(connection, {
      taggedThreadId: taggedThread.id,
      body: {
        discussionboard_thread_tag_id: invalidTagId,
      } satisfies IDiscussionboardTaggedThread.IUpdate,
    });
  });

  // 5. 실제 데이터가 변경되지 않았음을 검증하려면, 별도의 조회 API가 필요하지만 이 시점에서는 해당 함수가 제공되지 않아 skip 처리함.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardFilter } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardFilter";
import type { IPageIDiscussionboardFilter } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardFilter";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate searching, filtering, pagination, and exclusion of soft deleted
 * filters for the member's saved filter configurations.
 *
 * This test verifies:
 *
 * - Only the authenticated member's filters are returned (no other users/guests).
 * - Filters can be searched by partial name, and by is_public status.
 * - Pagination and creation timestamps are respected in results and pagination
 *   meta.
 * - Soft-deleted filters (deleted_at !== null) are never returned in searches.
 *
 * Steps:
 *
 * 1. Create multiple filters for the test member, mixing names ("Alpha", "Beta",
 *    "GammaPublic", "DeltaPrivate"), is_public true/false, and different
 *    created_at.
 * 2. Soft-delete one of the filters.
 * 3. Test unfiltered retrieval: All active filters for the test member (minus
 *    soft-deleted).
 * 4. Filter by partial name: e.g., name = "Alpha" retrieves only the matching
 *    filter.
 * 5. Filter by is_public=true: retrieves only public filters for the member.
 * 6. Pagination: create at least 10 filters and query with limit=5; validate
 *    correct meta/result count.
 * 7. Edge case: Search by a non-existent name, expect empty result.
 * 8. Edge case: Request a page size (limit) larger than result count, ensure all
 *    available are returned.
 * 9. Invalid filter combination: name and is_public mismatch, expect empty array.
 */
export async function test_api_prefix_member_filters_test_list_saved_filters_with_various_filters_and_pagination(
  connection: api.IConnection,
) {
  // Helper for creating new unique names/definitions for testing
  const now = new Date();
  function makeFilterParams(
    name: string,
    isPublic: boolean,
    createdAt: string,
  ) {
    return {
      name,
      definition: JSON.stringify({ search: name, created: createdAt }),
      is_public: isPublic,
      created_at: createdAt,
    } satisfies IDiscussionboardFilter.ICreate;
  }

  // 1. Create a diverse set of filters
  const createdFilters: IDiscussionboardFilter[] = [];
  const filterNames = [
    "AlphaTest", // will search for "Alpha"
    "BetaCase",
    "GammaPublic",
    "DeltaPrivate",
    "Epsilon",
    "Zeta",
    "Eta",
    "ThetaPublic",
    "IotaPrivate",
    "Kappa",
    "Lambda",
  ];
  const isPublicFlags = [
    true,
    false,
    true,
    false,
    false,
    true,
    false,
    true,
    false,
    true,
    true,
  ];
  for (let i = 0; i < filterNames.length; ++i) {
    const dt = new Date(now.getTime() + i * 60000).toISOString(); // incremental timestamps
    const filter = await api.functional.prefix.member.filters.create(
      connection,
      {
        body: makeFilterParams(filterNames[i], isPublicFlags[i], dt),
      },
    );
    typia.assert(filter);
    createdFilters.push(filter);
  }
  // Save special filter IDs for testing
  const filterAlpha = createdFilters[0];
  const filterGamma = createdFilters[2];
  const filterDelta = createdFilters[3];
  const filterZeta = createdFilters[5];

  // 2. Soft-delete one (DeltaPrivate)
  await api.functional.prefix.member.filters.erase(connection, {
    filterId: filterDelta.id,
  });
  // 3. Test unfiltered retrieval: should not include DeltaPrivate
  {
    const result = await api.functional.prefix.member.filters.index(
      connection,
      {
        body: {},
      },
    );
    typia.assert(result);
    // None should have deleted_at
    TestValidator.predicate("no soft-deleted filter in full list")(
      result.data.every((f) => f.deleted_at == null),
    );
    TestValidator.predicate("no other member filters")(
      result.data.every(
        (f) =>
          !f.discussionboard_member_id ||
          f.discussionboard_member_id === filterAlpha.discussionboard_member_id,
      ),
    );
    TestValidator.equals("no DeltaPrivate present")(false)(
      result.data.some((x) => x.id === filterDelta.id),
    );
  }

  // 4. Partial name filtering: should get only filterAlpha
  {
    const result = await api.functional.prefix.member.filters.index(
      connection,
      {
        body: { name: "Alpha" },
      },
    );
    typia.assert(result);
    TestValidator.equals("alpha search only gets AlphaTest")(1)(
      result.data.length,
    );
    TestValidator.equals("alpha search result is correct")(filterAlpha.id)(
      result.data[0]?.id,
    );
  }

  // 5. is_public filter: true
  {
    const result = await api.functional.prefix.member.filters.index(
      connection,
      {
        body: { is_public: true },
      },
    );
    typia.assert(result);
    TestValidator.predicate("all are public")(
      result.data.every((f) => f.is_public),
    );
  }

  // 6. Pagination (limit = 5)
  {
    const result = await api.functional.prefix.member.filters.index(
      connection,
      {
        body: {},
      },
    );
    typia.assert(result);
    // If total filters >= 10 (after soft-delete), test paging
    if (result.data.length >= 10) {
      const paged = await api.functional.prefix.member.filters.index(
        connection,
        {
          body: {},
        },
      );
      typia.assert(paged);
      // Default paging in result.pagination (validate presence)
      TestValidator.predicate("pagination meta exists")(
        !!paged.pagination && typeof paged.pagination.current === "number",
      );
      TestValidator.predicate("page 1 has <= 10 records")(
        paged.data.length <= 10,
      );
    }
  }

  // 7. Edge: search for non-existent name
  {
    const result = await api.functional.prefix.member.filters.index(
      connection,
      {
        body: { name: "___NO_MATCH___" },
      },
    );
    typia.assert(result);
