 * lookup by filterId.
 *
 * Steps:
 *
 * 1. Create a new filter (POST /prefix/member//filters) as a member user and save
 *    the returned ID and body values.
 * 2. Retrieve it back with GET /prefix/member//filters/{filterId} and check all
 *    properties and values match precisely.
 * 3. Attempt to fetch a filterId that does not exist and verify error (not found).
 * 4. (Skipped: Permission check for cross-user access, as user switching/auth not
 *    available.)
 * 5. Soft-delete a filter (by passing deleted_at in creation) then attempt to
 *    fetch and confirm it is not found or is marked deleted as expected.
 *
 * Validates API authorization, ownership, and visibility rules and proper
 * adherence to the detailed schema.
 */
export async function test_api_prefix_member_filters_test_get_own_saved_filter_details_success_and_not_found(
  connection: api.IConnection,
) {
