import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardFilter } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardFilter";

/**
 * Validate creation of discussion board filters (saved search) including
 * success, conflict, and error conditions.
 *
 * This test ensures:
 *
 * - Authenticated members can create filters with valid schema fields only.
 * - Filters are owned by and attributed to the creating member only (ownership
 *   cannot be spoofed).
 * - Duplicate name/definition pairs are tested to see if uniqueness per user is
 *   enforced.
 * - All required fields must be present and valid.
 * - Invalid data and schema violations are rejected.
 * - Out-of-schema property injection is prohibited.
 *
 * Steps:
 *
 * 1. Create a filter with valid fields (minimal required)
 * 2. Verify response structure and owner assignment
 * 3. Attempt to create a filter with the same name/definition (check for business
 *    rule enforcement)
 * 4. Negative test: omit name (expect error)
 * 5. Negative test: omit definition (expect error)
 * 6. Negative test: use non-boolean for is_public (expect error)
 * 7. Negative test: try to pass discussionboard_member_id (should fail or be
 *    ignored)
 * 8. Negative test: inject out-of-schema property (should fail)
 */
export async function test_api_prefix_member_filters_test_create_saved_filter_with_valid_and_conflicting_data(
  connection: api.IConnection,
) {
  // 1. Successful creation with valid fields
  const filterName = RandomGenerator.alphabets(10);
  const filterDefinition = '{"type":"tag","tags":["test"]}';
  const createInput = {
    name: filterName,
    definition: filterDefinition,
    is_public: true,
  } satisfies IDiscussionboardFilter.ICreate;
  const created = await api.functional.prefix.member.filters.create(
    connection,
    {
      body: createInput,
    },
  );
  typia.assert(created);
  TestValidator.equals("name")(created.name)(filterName);
  TestValidator.equals("definition")(created.definition)(filterDefinition);
  TestValidator.equals("is_public")(created.is_public)(true);
  // Owner is set and matches (should not be null)
  TestValidator.predicate("owner assigned")(
    typeof created.discussionboard_member_id === "string" &&
      created.discussionboard_member_id.length > 0,
  );
  // id is set
  TestValidator.predicate("id is uuid")(created.id.length === 36);

  // 2. Attempt duplicate (same name/definition)
  const duplicate = await api.functional.prefix.member.filters.create(
    connection,
    {
      body: createInput,
    },
  );
  typia.assert(duplicate);
  TestValidator.equals("name")(duplicate.name)(filterName);
  TestValidator.equals("definition")(duplicate.definition)(filterDefinition);
  // Depending on system logic, either allowed or error. If allowed, id must differ
  TestValidator.notEquals("different id for duplicate")(duplicate.id)(
    created.id,
  );
  // Owner must still be same
  TestValidator.equals("duplicate owner")(duplicate.discussionboard_member_id)(
    created.discussionboard_member_id,
  );

  // 3. Negative: missing name
  TestValidator.error("missing name should fail")(async () => {
    await api.functional.prefix.member.filters.create(connection, {
      body: {
        definition: filterDefinition,
        is_public: false,
      } as any, // type system won't let us omit required so use as any for runtime error
    });
  });

  // 4. Negative: missing definition
  TestValidator.error("missing definition should fail")(async () => {
    await api.functional.prefix.member.filters.create(connection, {
      body: {
        name: "MissingDef",
        is_public: false,
      } as any,
    });
  });

  // 5. Negative: is_public non-boolean
  TestValidator.error("is_public as non-boolean should fail")(async () => {
    await api.functional.prefix.member.filters.create(connection, {
      body: {
        name: "badBool",
        definition: filterDefinition,
        is_public: 123 as any,
      } as any,
    });
  });

  // 6. Negative: try to assign discussionboard_member_id (should fail or be ignored)
  TestValidator.error("cannot spoof owner discussionboard_member_id")(
    async () => {
      await api.functional.prefix.member.filters.create(connection, {
        body: {
          name: "spoof",
          definition: filterDefinition,
          is_public: false,
          discussionboard_member_id: typia.random<
            string & tags.Format<"uuid">
          >(),
        } as any,
      });
    },
  );

  // 7. Negative: inject extra/out-of-schema property
  TestValidator.error("out-of-schema field should fail")(async () => {
    await api.functional.prefix.member.filters.create(connection, {
      body: {
        name: "extra",
        definition: filterDefinition,
        is_public: true,
        bogus_field: "nope",
      } as any,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardFilter } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardFilter";

/**
 * Test updating fields of a saved discussion board filter configuration a
 * member owns, and handling soft-deleted/forbidden/nonexistent cases.
 *
 * This test validates both positive and negative behaviors for updating
 * IDiscussionboardFilter via the update endpoint:
 *
 * 1. Create a filter as the current member (obtain filterId).
 * 2. Update individual fields (name, definition, is_public, updated_at).
 * 3. Update multiple fields in combination.
 * 4. Ensure changes persist and ownership (discussionboard_member_id) cannot be
 *    changed by update.
 * 5. Soft-delete the filter, then verify that subsequent update fails.
 * 6. Attempt update with random (nonexistent) filterId (expect error).
 * 7. (If possible) Attempt to update a filter owned by another member (expect
 *    error).
 * 8. Attempt to update using extraneous/invalid fields (ensure type error is
 *    present at compile time and update cannot proceed; in runtime only valid
 *    props can be tested).
 *
 * Negative test cases only check that an error occurs, not specific error text.
 */
export async function test_api_prefix_member_filters_test_update_saved_filter_fields_and_handle_soft_deleted_filter(
  connection: api.IConnection,
) {
  // 1. Create filter as current member
  const baseFilterInput = {
    name: `BaseFilter_${RandomGenerator.alphaNumeric(6)}`,
    definition: JSON.stringify({ q: RandomGenerator.alphaNumeric(4) }),
    is_public: false,
  } satisfies IDiscussionboardFilter.ICreate;
  const created = await api.functional.prefix.member.filters.create(
    connection,
    { body: baseFilterInput },
  );
  typia.assert(created);

  // 2. Update each field individually and check changed values & owner
  // (a) name
  const newName = `UpdatedName_${RandomGenerator.alphaNumeric(6)}`;
  let updated = await api.functional.prefix.member.filters.update(connection, {
    filterId: created.id,
    body: { name: newName },
  });
  typia.assert(updated);
  TestValidator.equals("name updated")(updated.name)(newName);
  TestValidator.equals("ownership unchanged")(
    updated.discussionboard_member_id,
  )(created.discussionboard_member_id ?? null);

  // (b) definition
  const newDefinition = JSON.stringify({
    keyword: RandomGenerator.alphaNumeric(8),
  });
  updated = await api.functional.prefix.member.filters.update(connection, {
    filterId: created.id,
    body: { definition: newDefinition },
  });
  typia.assert(updated);
  TestValidator.equals("definition updated")(updated.definition)(newDefinition);

  // (c) is_public
  updated = await api.functional.prefix.member.filters.update(connection, {
    filterId: created.id,
    body: { is_public: true },
  });
  typia.assert(updated);
  TestValidator.equals("is_public updated")(updated.is_public)(true);

  // (d) updated_at
  const newUpdateTime = new Date().toISOString();
  updated = await api.functional.prefix.member.filters.update(connection, {
    filterId: created.id,
    body: { updated_at: newUpdateTime },
  });
  typia.assert(updated);
  TestValidator.equals("updated_at updated")(updated.updated_at ?? undefined)(
    newUpdateTime,
  );

  // 3. Multi-field update
  const comboUpdate = {
    name: `Combo_${RandomGenerator.alphaNumeric(5)}`,
    definition: JSON.stringify({ nested: RandomGenerator.alphaNumeric(9) }),
    is_public: false,
    updated_at: new Date(Date.now() + 1000).toISOString(),
  } satisfies IDiscussionboardFilter.IUpdate;
  updated = await api.functional.prefix.member.filters.update(connection, {
    filterId: created.id,
    body: comboUpdate,
  });
  typia.assert(updated);
  TestValidator.equals("multi-fields updated")(updated.name)(comboUpdate.name);
  TestValidator.equals("multi-fields updated definition")(updated.definition)(
    comboUpdate.definition,
  );
  TestValidator.equals("multi-fields updated is_public")(updated.is_public)(
    comboUpdate.is_public,
  );
  TestValidator.equals("multi-fields updated updated_at")(
    updated.updated_at ?? undefined,
  )(comboUpdate.updated_at);

  // 4. Soft-delete the filter, then further update must fail
  await api.functional.prefix.member.filters.erase(connection, {
    filterId: created.id,
  });
  TestValidator.error("update after soft-delete fails")(async () => {
    await api.functional.prefix.member.filters.update(connection, {
      filterId: created.id,
      body: { name: "ShouldFail" },
    });
  });

  // 5. Attempt update with non-existent filterId
  const fakeId = typia.random<string & tags.Format<"uuid">>();
  TestValidator.error("update of non-existent filter fails")(async () => {
    await api.functional.prefix.member.filters.update(connection, {
      filterId: fakeId,
      body: { name: "NoSuchFilter" },
    });
  });

  // 6. (If possible) Attempt update as another user. This test assumes
  //    connection user context can be changed; if unavailable, skip this.
  //    This is left as a comment for extension if user context logic exists.

  // 7. Attempt to call update using extraneous fields. This is not possible
  //    via strictly-typed SDK, as non-schema fields are not permitted at
  //    compile time, so runtime test is not possible here.
}

