/**
 * E2E test for soft-deleting a saved discussion board filter and verifying
 * idempotency, permissions, and error edge cases.
 *
 * Business context: Members can save filter configurations (searches) for
 * reuse. Rather than being permanently removed, filters are soft-deleted by
 * setting their deleted_at field, allowing history, possible recovery, and
 * compliance tracking.
 *
 * This test does all of the following:
 *
 * 1. Creates a saved filter for the test member
 * 2. Soft-deletes the filter by ID (checks: operation succeeds)
 * 3. Attempts soft-deletion again to confirm idempotency (must not error)
 * 4. Tries to delete a filter that does not exist (should throw)
 * 5. Attempts delete with invalid UUID format (should throw)
 *
 * Steps not possible due to missing API:
 *
 * - Fetching filter after delete to verify deleted_at is set
 * - Deleting a filter belonging to another member (no member switching/auth
 *   provided)
 *
 * Test strictly omits any scenario that is not feasible with the currently
 * available endpoints, as per instructions.
 */
export async function test_api_prefix_member_filters_test_soft_delete_saved_filter_and_idempotency(
  connection: api.IConnection,
) {
  // 1. Create a new filter configuration for this member
  const createInput = {
    name: RandomGenerator.alphabets(8),
    definition: JSON.stringify({ q: RandomGenerator.alphaNumeric(5) }),
    is_public: false,
  } satisfies IDiscussionboardFilter.ICreate;

  const filter = await api.functional.prefix.member.filters.create(connection, {
    body: createInput,
  });
