  await api.functional.prefix.member.filters.erase(connection, {
    filterId: filter.id,
  });

  // 3. Attempt soft-delete again for idempotency. Should not raise error.
  await api.functional.prefix.member.filters.erase(connection, {
    filterId: filter.id,
  });

  // 4. Attempt to delete a non-existent filter (random UUID). Should fail.
  await TestValidator.error("delete non-existent filter")(async () => {
    await api.functional.prefix.member.filters.erase(connection, {
      filterId: typia.random<string & tags.Format<"uuid">>(),
    });
  });

  // 5. Attempt to delete using an invalid/malformed UUID
  await TestValidator.error("delete invalid UUID")(async () => {
    await api.functional.prefix.member.filters.erase(connection, {
      filterId: "invalid-uuid" as string & tags.Format<"uuid">,
