  const expiresAt = new Date(
    Date.now() + 60 * 60 * 1000,
  ).toISOString() as string & tags.Format<"date-time">;
  const pollInput = {
    discussionboard_thread_id: threadId,
    prompt: pollPrompt,
    allow_multiple_choices: true,
    is_anonymous: false,
    expires_at: expiresAt,
