    threadId,
  );
  TestValidator.equals("created_by matches member")(poll.created_by_member_id)(
    memberId,
  );
  TestValidator.equals("prompt")(poll.prompt)(pollPrompt);
  TestValidator.equals("allow_multiple_choices")(poll.allow_multiple_choices)(
    true,
  );
  TestValidator.equals("is_anonymous")(poll.is_anonymous)(false);
  TestValidator.equals("expires_at")(poll.expires_at)(expiresAt);
  TestValidator.predicate("created_at exists and valid")(
    typeof poll.created_at === "string" && poll.created_at.length > 0,
  );
}

