  );
  typia.assert(member);

  // 2. Create a thread (associate to fake a category)
  const threadInput: IDiscussionboardThreads.ICreate = {
    // discussionboard_member_id is optional per schema (set by backend)
    discussionboard_category_id: typia.random<string & tags.Format<"uuid">>(),
    title: "Poll Test Thread",
    status: "active",
    is_pinned: false,
    is_locked: false,
    archived: false,
    created_at: new Date().toISOString() as string & tags.Format<"date-time">,
    updated_at: new Date().toISOString() as string & tags.Format<"date-time">,
  };
  const thread = await api.functional.prefix.member.threadsPosts.threads.create(
    connection,
    { body: threadInput },
  );
  typia.assert(thread);

  // 3. Create a poll for the thread
  const pollInput: IPoll.ICreate = {
    discussionboard_thread_id: thread.id,
    prompt: "What is your favorite color?",
    allow_multiple_choices: true,
    is_anonymous: false,
    expires_at: new Date(Date.now() + 3600000).toISOString() as string &
      tags.Format<"date-time">,
  };
  const poll = await api.functional.prefix.member.polls.create(connection, {
    body: pollInput,
  });
  typia.assert(poll);

  // Ownership check
  TestValidator.equals(
    "ownership: poll created_by_member_id same as member.id",
  )(poll.created_by_member_id)(member.id);

  // 4. Update mutable poll fields
  const newPrompt = "What is your favorite programming language?";
  const updateInput: IPoll.IUpdate = {
    prompt: newPrompt,
    allow_multiple_choices: false,
    is_anonymous: true,
    expires_at: new Date(Date.now() + 2 * 3600000).toISOString() as string &
      tags.Format<"date-time">,
  };
  const updated = await api.functional.prefix.member.my.polls.update(
    connection,
    { id: poll.id, body: updateInput },
  );
  typia.assert(updated);

  // 5. Validate fields have changed as expected and ownership is unchanged
  TestValidator.equals("prompt updated")(updated.prompt)(newPrompt);
  TestValidator.equals("allow_multiple_choices updated")(
    updated.allow_multiple_choices,
  )(false);
  TestValidator.equals("is_anonymous updated")(updated.is_anonymous)(true);
  TestValidator.equals("expires_at updated")(updated.expires_at)(
    updateInput.expires_at,
  );

  TestValidator.equals("ownership enforced after update")(
    updated.created_by_member_id,
  )(member.id);
  TestValidator.equals("thread unchanged")(updated.discussionboard_thread_id)(
    thread.id,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
