/**
 * 존재하지 않거나 회원 소유가 아닌 poll의 수정 시 오류가 발생함을 검증합니다.
 *
 * - 비정상(실패) 시나리오: 시스템에 없는 poll UUID 혹은 타인 소유 poll을 수정하려면 반드시 forbidden 또는 not
 *   found 오류를 반환해야 합니다. (test에서는 DB에 없는 임의 poll UUID 대상만 검증, 다른 회원 소유 poll은 별도
 *   생성 API 미제공으로 생략)
 *
 * [검증 절차]
 *
 * 1. 신규 토론 멤버(회원)를 등록한다.
 * 2. 존재하지 않는 임의 poll UUID로, IPoll.IUpdate 데이터와 함께 update 시도를 한다.
 * 3. Update 시 HttpError 예외가 발생하는지(TestValidator.error) 반드시 확인한다.
 */
export async function test_api_polls_test_update_nonexistent_poll_fails(
  connection: api.IConnection,
) {
  // 1. 신규 회원 등록(토론 멤버)
  const member: IDiscussionboardMembers =
    await api.functional.prefix.member.actors.members.create(connection, {
      body: {
        id: typia.random<string & tags.Format<"uuid">>(),
        created_at: new Date().toISOString() as string &
          tags.Format<"date-time">,
      } satisfies IDiscussionboardMembers.ICreate,
    });
  typia.assert(member);

  // 2. 존재하지 않는 poll UUID로 update 시도를 한다
  const unusedPollId: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();
  const updateBody: IPoll.IUpdate = {
    prompt: "존재하지 않는 poll 수정 시도",
    allow_multiple_choices: false,
    is_anonymous: false,
    expires_at: new Date(Date.now() + 3600 * 1000).toISOString() as string &
      tags.Format<"date-time">,
  } satisfies IPoll.IUpdate;

  // 실제 예외가 반드시 발생하는지 검증 (404 not found 또는 403 forbidden)
  await TestValidator.error("존재하지 않는 poll update 시 예외")(async () => {
    await api.functional.prefix.member.my.polls.update(connection, {
      id: unusedPollId,
      body: updateBody,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
