  const categoryId: string = typia.random<string & tags.Format<"uuid">>();
  const threadTime = new Date(Date.now() + 2000).toISOString();
  const thread = await api.functional.prefix.member.threadsPosts.threads.create(
    connection,
    {
      body: {
        discussionboard_category_id: categoryId,
        title: "Poll Ownership Protection Test",
        status: "active",
        is_pinned: false,
        is_locked: false,
        archived: false,
        created_at: threadTime,
        updated_at: threadTime,
      },
    },
