/**
 * Test that a member can successfully update their own content report before
 * moderator review.
 *
 * This test validates that a member can update their own content report's
 * details, such as changing the report reason or attaching a moderator note,
 * prior to any moderator action. The workflow covers:
 *
 * 1. Registering a new member to establish an authenticated ownership context.
 * 2. Creating a post (as the member) which will serve as the target for a
 *    moderation report.
 * 3. Filing an initial content report for that post, with the report in 'pending'
 *    status.
 * 4. Updating the report fields (e.g., report_reason, moderator_note, and status)
 *    before any moderator review/action.
 * 5. Verifying that the fields were updated as expected, status is appropriately
 *    set, and no unauthorized fields were mutated or lost. All schema/business
 *    contracts are asserted.
 *
 * Steps:
 *
 * 1. Register a test member
 * 2. Member posts new content (thread post); test uses a random thread id as
 *    context
 * 3. Member creates initial content report for the post
 * 4. Update (amend) the report fields before moderator action (e.g., change
 *    reason, add note, move to 'in_review')
 * 5. Validate all updated fields, ids, and contract constraints
 */
export async function test_api_contentReports_test_update_own_content_report_with_valid_data(
  connection: api.IConnection,
) {
  // 1. Register a test member
  const memberId = typia.random<string & tags.Format<"uuid">>();
  const memberCreatedAt = new Date().toISOString();
  const member = await api.functional.prefix.member.actors.members.create(
    connection,
    {
      body: {
        id: memberId,
        created_at: memberCreatedAt,
      },
    },
  );
  typia.assert(member);

  // 2. Member posts new content (thread post)
  const threadId = typia.random<string & tags.Format<"uuid">>();
  const postBody = "Initial test post for report";
  const post = await api.functional.prefix.member.threadsPosts.posts.create(
    connection,
    {
      body: {
        discussionboard_thread_id: threadId,
        body: postBody,
      },
    },
  );
  typia.assert(post);

  // 3. Member creates initial content report for the post
  const reportReason1 = "Initial inappropriate content report";
  const reportCreatedAt = new Date().toISOString();
  const contentReport =
    await api.functional.prefix.member.contentReports.create(connection, {
      body: {
        reported_post_id: post.id,
        reporter_member_id: member.id,
        report_reason: reportReason1,
        status: "pending",
        reported_at: reportCreatedAt,
        moderator_note: null,
      },
    });
  typia.assert(contentReport);

  // 4. Update the report fields BEFORE moderator action (status still 'pending')
  const newReportReason = "Amended reason: contains prohibited language";
  const updatedNote = "Additional details for triage.";
  const updatedStatus: "in_review" = "in_review";
  const updated = await api.functional.prefix.member.my.contentReports.update(
    connection,
    {
      id: contentReport.id,
      body: {
        report_reason: newReportReason,
        moderator_note: updatedNote,
        status: updatedStatus,
      },
    },
  );
  typia.assert(updated);

  // 5. Validate the fields are updated and writable
  TestValidator.equals("updated id matches")(updated.id)(contentReport.id);
  TestValidator.equals("updated reported_post_id matches")(
    updated.reported_post_id,
  )(post.id);
  TestValidator.equals("updated reporter_member_id matches")(
    updated.reporter_member_id,
  )(member.id);
  TestValidator.equals("updated report_reason field is amended")(
    updated.report_reason,
  )(newReportReason);
  TestValidator.equals("updated moderator_note is set")(updated.moderator_note)(
    updatedNote,
  );
  TestValidator.equals("updated status is now 'in_review'")(updated.status)(
    updatedStatus,
  );

  // Confirm additional business contract invariants remain valid
  TestValidator.predicate(
    "report is still updatable after member update and before moderator action",
  )(updated.status === "in_review");
}

