 * Steps:
 *
 * 1. Register two separate members (Member A and Member B).
 * 2. Member A creates a discussion thread post.
 * 3. Member A files a content report on the post they created (to own the report
 *    as Member A).
 * 4. Member B attempts to update Member A's content report using the
 *    /my/contentReports/{id} endpoint.
 * 5. Assert that the operation is forbidden and the API responds with a suitable
 *    authorization error (e.g., forbidden/unauthorized).
 */
export async function test_api_prefix_test_update_other_users_content_report_forbidden(
  connection: api.IConnection,
) {
