  TestValidator.equals("update: id unchanged")(updated.id)(created.id);
  TestValidator.notEquals("update: name changed")(updated.name)(
    createInput.name,
  );
  TestValidator.equals("update: new name")(updated.name)(updateInput.name);
  TestValidator.equals("update: settings_json")(updated.settings_json)(
    updateInput.settings_json,
  );
  TestValidator.equals("update: description")(updated.description)(
    updateInput.description,
  );

  // 4. Attempt to create another configuration with the updated (now-taken) name; expect error for uniqueness constraint
  await TestValidator.error("creation with non-unique name fails")(async () => {
    await api.functional.prefix.admin.discussionboardConfigurations.create(
      connection,
      {
        body: {
          name: updateName,
          settings_json: JSON.stringify({ dummy: true }),
          description: "Should fail due to non-unique name",
        },
      },
    );
  });
}

