/**
 * Test updating a discussion board configuration with missing or invalid
 * required fields.
 *
 * This test verifies that the API enforces required and non-nullable field
 * constraints when updating a configuration:
 *
 * - Attempts to set non-nullable fields ("name" and "settings_json") to null are
 *   rejected
 * - Omitting "name" or "settings_json" in the update payload is allowed (fields
 *   are optional and will not be changed)
 * - Updates setting "description" to null are permitted (the field is nullable)
 *
 * Test workflow:
 *
 * 1. Create a valid configuration using the admin API to get a configurationId for
 *    patching.
 * 2. Attempt to update with `name: null` (should fail, not nullable).
 * 3. Update omitting "name" (should succeed; value remains unchanged).
 * 4. Attempt to update with `settings_json: null` (should fail, not nullable).
 * 5. Update with `description: null` (should succeed; value set to null).
 * 6. Validate that the API rejects or accepts each operation appropriately.
 */
export async function test_api_discussionboardConfigurations_test_update_discussion_board_configuration_with_missing_required_fields(
  connection: api.IConnection,
) {
  // 1. Create valid configuration for update attempts
  const created =
    await api.functional.prefix.admin.discussionboardConfigurations.create(
      connection,
      {
        body: {
          name: "required-fields-test-" + RandomGenerator.alphaNumeric(8),
          settings_json: "{}",
          description: "Testing required field constraints on update",
        } satisfies IDiscussionboardConfiguration.ICreate,
      },
    );
  typia.assert(created);

  // 2. Try to update: name set to null (should fail)
  await TestValidator.error("update: name cannot be null")(async () => {
    await api.functional.prefix.admin.discussionboardConfigurations.update(
      connection,
      {
        configurationId: created.id,
        body: { name: null } as any,
      },
    );
  });

  // 3. Update: omit name (should succeed, name remains unchanged)
  const patchNoName =
    await api.functional.prefix.admin.discussionboardConfigurations.update(
      connection,
      {
        configurationId: created.id,
        body: {
          description: "No name changed",
        } satisfies IDiscussionboardConfiguration.IUpdate,
      },
    );
  typia.assert(patchNoName);
  TestValidator.equals("unchanged name after patch")(patchNoName.name)(
    created.name,
  );
  TestValidator.equals("unchanged settings_json after patch")(
    patchNoName.settings_json,
  )(created.settings_json);

  // 4. Try to update: settings_json set to null (should fail)
  await TestValidator.error("update: settings_json cannot be null")(
    async () => {
      await api.functional.prefix.admin.discussionboardConfigurations.update(
        connection,
        {
          configurationId: created.id,
          body: { settings_json: null } as any,
        },
      );
    },
  );

  // 5. Update: set description=null (should succeed)
  const patchNullDesc =
    await api.functional.prefix.admin.discussionboardConfigurations.update(
      connection,
      {
        configurationId: created.id,
        body: {
          description: null,
        } satisfies IDiscussionboardConfiguration.IUpdate,
      },
    );
  typia.assert(patchNullDesc);
  TestValidator.equals("description is null")(patchNullDesc.description)(null);
  TestValidator.equals("name unchanged")(patchNullDesc.name)(created.name);
  TestValidator.equals("settings_json unchanged")(patchNullDesc.settings_json)(
    created.settings_json,
  );
}

